    def finalize_material_polyline(self):
        """Finalizes the drawing of a material polyline, creates a 3D prism, and saves the data."""
        if not self.material_drawing_active or len(self.material_drawing_points) < 2:
            self.message_text.append("Material drawing not active or not enough points.")
            self.cancel_material_drawing()
            return

        material_idx = self.active_material_index
        if material_idx is None or material_idx >= len(self.material_configs):
            self.message_text.append(f"Invalid active material index: {material_idx}")
            self.cancel_material_drawing()
            return

        # Ensure the required baselines ('construction' and 'road_surface') are loaded.
        # This is critical for creating the 3D prism.
        if 'construction' not in self.line_types or not self.line_types['construction']['data']:
            self.message_text.append("Warning: Construction baseline not loaded. Attempting to load from design layer.")
            self._load_baseline_from_design_layer({'ref_layer': 'construction'})

        if 'road_surface' not in self.line_types or not self.line_types['road_surface']['data']:
            self.message_text.append("Warning: Road Surface baseline not loaded. Attempting to load from design layer.")
            self._load_baseline_from_design_layer({'ref_layer': 'road_surface'})

        # Re-check if loading was successful
        if 'construction' not in self.line_types or not self.line_types['construction']['data']:
            QMessageBox.critical(self, "Error", "Could not load the 'construction' baseline. Cannot create 3D material prism.")
            self.cancel_material_drawing()
            return

        # The drawn points are the 2D polyline for the top of the material
        polyline_2d = self.material_drawing_points

        # Store the finalized 2D polyline
        if material_idx not in self.material_polylines:
            self.material_polylines[material_idx] = []
        self.material_polylines[material_idx].append(polyline_2d)

        # Get material properties (like width) from the material's configuration
        material_props = self.material_configs[material_idx]

        # Create the 2D and 3D visuals for this new polyline
        self.create_material_visuals(material_idx, polyline_2d, material_props)

        # Save the data
        self.save_material_polyline_data(material_idx, polyline_2d, material_props)

        # Clean up the drawing state
        if self.current_material_line_artist:
            self.current_material_line_artist.remove()
            self.current_material_line_artist = None
        self.material_drawing_points = []
        self.material_drawing_active = False
        self.active_material_index = None

        # Update the UI
        self.start_material_button.setText("Start")
        self.finish_material_button.setEnabled(False)
        self.message_text.append(f"Finished drawing for Material {material_idx + 1}.")
        self.canvas.draw_idle()
        self.vtk_widget.GetRenderWindow().Render()

    def check_trial_reminder(self):
        """Check if we should show the free trial reminder today"""
        user_config_path = os.path.join(r"C:\3D_Tool\user", str(self.current_user_id), "user_config.txt")
        if not os.path.exists(user_config_path):
            return

        try:
            with open(user_config_path, 'r', encoding='utf-8') as f:
                config_data = json.load(f)
            
            remaining_days = config_data.get("remaining_days", 0)
            if remaining_days is None:
                remaining_days = 0
            last_reminder_str = config_data.get("last_reminder_date")
            today_str = datetime.now().strftime("%Y-%m-%d")

            if last_reminder_str != today_str and 1 <= remaining_days <= 15:
                # Show reminder once a day when 15 or fewer days remain
                msg = (
                    "Free Trial Reminder\n\n"
                    f"â³ Your trial of 3D Bharat Road Design Application will expire in {remaining_days} days."
                )
                # Show after a short delay to ensure UI is ready
                QTimer.singleShot(1500, lambda: self._show_reminder_dlg(msg, today_str, config_data, user_config_path))
                
        except Exception as e:
            print(f"Error checking trial reminder: {e}")

    def _show_reminder_dlg(self, msg, today_str, config_data, config_path):
        dlg = ModernInfoDialog("Free Trial Reminder", msg, parent=self)
        if dlg.exec_():
            # Update last reminder date in config
            config_data["last_reminder_date"] = today_str
            try:
                with open(config_path, 'w', encoding='utf-8') as f:
                    json.dump(config_data, f, indent=4, ensure_ascii=False)
            except Exception as e:
                print(f"Error saving reminder date: {e}")

