    def open_create_new_design_layer_dialog(self):
        """Open the Design New Layer dialog and save config to current worksheet's designs folder"""
        if not hasattr(self, 'current_worksheet_name') or not self.current_worksheet_name:
            QMessageBox.warning(self, "No Active Worksheet",
                                "Please create or open a worksheet first before creating a design layer.")
            return

        dialog = DesignNewDialog(self)
        if dialog.exec_() == QDialog.Accepted:
            # === CLEAR EXISTING BASELINES BEFORE CREATING NEW LAYER ===
            # This allows users to create multiple design layers in one worksheet
            self.clear_current_design_layer()
            self.clear_current_material_line()
            self.clear_deck_actors_and_labels()  ###
            
            config = dialog.get_configuration()
            layer_name = config["layer_name"]
            dimension = config["dimension"]
            ref_type = config["reference_type"]
            ref_line = config["reference_line"]
            creation_mode = config.get("creation_mode", "design")

            # Get current point cloud filename (from worksheet config or current state)
            pc_file = self.current_worksheet_data.get("point_cloud_file")
            pc_filename = os.path.basename(pc_file) if pc_file else "None"

            # Build path
            base_designs_path = os.path.join(self.WORKSHEETS_BASE_DIR, self.current_worksheet_name, "designs")
            layer_folder = os.path.join(base_designs_path, layer_name)
            os.makedirs(layer_folder, exist_ok=True)

            # === EXACT SAME CONFIG STRUCTURE ===
            full_config = {
                "layer_name": layer_name,
                "dimension": dimension,
                "reference_type": ref_type or "None",
                "reference_line": ref_line or "None",
                "master_layer": config.get("master_layer", False),
                "project_name": getattr(self, 'current_project_name', 'None') or "None",
                "worksheet_name": self.current_worksheet_name,
                "point_cloud_file": pc_filename,
                "created_by": self.current_user,
                "created_at": datetime.now().isoformat(),
            }

            # Save config
            config_file_path = os.path.join(layer_folder, "design_layer_config.txt")
            try:
                with open(config_file_path, 'w', encoding='utf-8') as f:
                    json.dump(full_config, f, indent=4)

                QMessageBox.information(self, "Success",
                                        f"Design layer '{layer_name}' created successfully!\n\n"
                                        f"Location:\n{layer_folder}")

                self.message_text.append(f"New design layer created: {layer_name}")
                self.message_text.append(f"  Path: {layer_folder}")
                self.message_text.append(f"  Dimension: {dimension}")
                self.message_text.append(f"  Point Cloud: {pc_filename}")
                if ref_type:
                    self.message_text.append(f"  Reference Type: {ref_type} ({ref_line or 'No reference'})")
                self.current_layer_name = layer_name
                self.reference_type = ref_type
                self.current_design_layer_path = layer_folder 

            except Exception as e:
                QMessageBox.critical(self, "Save Failed", f"Could not save design layer config:\n{str(e)}")
                return
            
            if creation_mode == "design_with_material":
                material_created = self._duplicate_material_layer_for_design(layer_name)
                if not material_created:
                    self.message_text.append(
                        f"Warning: design layer '{layer_name}' was created, but material duplication was not completed."
                    )

            # Add to left panel
            if dimension == "2D":
                self.two_D_frame.setVisible(True)
            else: 
                self.three_D_frame.setVisible(True)
            self.add_layer_to_panel(layer_name, dimension)
            if hasattr(self, 'set_layer_panel_highlight'):
                self.set_layer_panel_highlight(
                    active_layer_name=layer_name,
                    active_subfolder="designs" if dimension == "2D" else None,
                    linked_design_layer_name=None
                )

            self.switch_to_design_mode()

            # UI updates (same as before)
            self.bottom_section.setVisible(False)
            self.right_section.setMinimumHeight(1200)
            for container in [self.surface_container, self.construction_container, self.road_surface_container,
                              self.zero_container, self.deck_line_container, self.projection_container,
                              self.construction_dots_container, getattr(self, 'bridge_zero_container', None)]:
                if container:
                    container.setVisible(False)

            if ref_type == "Road":
                self.surface_container.setVisible(True)
                self.construction_container.setVisible(True)
                self.road_surface_container.setVisible(True)
                self.zero_container.setVisible(True)
                self.ax.set_title('Road Construction Layers', fontsize=12, fontweight='bold', color='#4A148C', pad=8)  # Added pad
            elif ref_type == "Bridge":
                self.deck_line_container.setVisible(True)
                self.projection_container.setVisible(True)
                self.construction_dots_container.setVisible(True)
                if hasattr(self, 'bridge_zero_container'):
                    self.bridge_zero_container.setVisible(True)
                self.ax.set_title('Bridge Construction Layers', fontsize=12, fontweight='bold', color='#4A148C', pad=8)  # Added pad

            self.preview_button.setVisible(True)
            self.elivation_angle_button.setVisible(True)
            self.threed_map_button.setVisible(True)
            self.save_button.setVisible(True)

            self.zero_line.setChecked(False)
            if hasattr(self, 'bridge_zero_line'):
                self.bridge_zero_line.setChecked(False)

            self.canvas.draw()
            if hasattr(self, 'vtk_widget'):
                self.vtk_widget.GetRenderWindow().Render()

    def _duplicate_material_layer_for_design(self, design_layer_name):
        """Create a construction/material layer that follows the newly created design layer."""
        if not hasattr(self, 'current_worksheet_name') or not self.current_worksheet_name:
            QMessageBox.warning(self, "Material Layer", "No active worksheet found for material duplication.")
            return False

        worksheet_root = os.path.join(self.WORKSHEETS_BASE_DIR, self.current_worksheet_name)
        construction_root = os.path.join(worksheet_root, "construction")
        os.makedirs(construction_root, exist_ok=True)

        target_material_name = f"Material {design_layer_name}"
        target_material_path = os.path.join(construction_root, target_material_name)
        os.makedirs(target_material_path, exist_ok=True)

        source_material_path = getattr(self, 'current_construction_layer_path', None)
        source_material_file = None
        if source_material_path:
            candidate = os.path.join(source_material_path, "material_construction_config.json")
            if os.path.exists(candidate):
                source_material_file = candidate

        if source_material_file is None:
            try:
                for folder_name in sorted(os.listdir(construction_root)):
                    candidate = os.path.join(construction_root, folder_name, "material_construction_config.json")
                    if os.path.exists(candidate):
                        source_material_file = candidate
                        break
            except Exception:
                source_material_file = None

        source_data = {}
        if source_material_file:
            try:
                with open(source_material_file, 'r', encoding='utf-8') as f:
                    source_data = json.load(f)
            except Exception as e:
                self.message_text.append(f"Warning: Could not read source material config: {e}")
                source_data = {}

        def _coords_for_chainage(chainage_m):
            x, y, z = self.get_real_coordinates_from_chainage(chainage_m)
            if x is None or y is None or z is None:
                x, y, z = self.interpolate_xyz(chainage_m)
            return [round(float(x or 0.0), 3), round(float(y or 0.0), 3), round(float(z or 0.0), 3)]

        def _rebuild_material_geometry(material_entry):
            from_info = material_entry.get('overall_from_chainage', {})
            to_info = material_entry.get('overall_to_chainage', {})

            from_chainage = float(from_info.get('chainage_m', 0.0) or 0.0)
            to_chainage = float(to_info.get('chainage_m', 0.0) or 0.0)
            material_entry['overall_from_chainage'] = {
                'coordinates': _coords_for_chainage(from_chainage),
                'chainage_m': round(from_chainage, 3),
                'chainage_str': from_info.get('chainage_str', '')
            }
            material_entry['overall_to_chainage'] = {
                'coordinates': _coords_for_chainage(to_chainage),
                'chainage_m': round(to_chainage, 3),
                'chainage_str': to_info.get('chainage_str', '')
            }

            for segment in material_entry.get('segments', []):
                seg_from = float(segment.get('from_chainage_m', 0.0) or 0.0)
                seg_to = float(segment.get('to_chainage_m', 0.0) or 0.0)
                segment['from_coordinates'] = _coords_for_chainage(seg_from)
                segment['to_coordinates'] = _coords_for_chainage(seg_to)

                rebuilt_points = []
                for point in segment.get('polyline_points', []):
                    chainage = float(point.get('chainage_m', 0.0) or 0.0)
                    relative_elevation = float(point.get('relative_elevation_m', 0.0) or 0.0)
                    base_x, base_y, base_z = self.get_real_coordinates_from_chainage(chainage)
                    if base_x is None or base_y is None or base_z is None:
                        base_x, base_y, base_z = self.interpolate_xyz(chainage)
                    rebuilt_point = point.copy()
                    rebuilt_point['absolute_coordinates'] = [
                        round(float(base_x or 0.0), 3),
                        round(float(base_y or 0.0), 3),
                        round(float((base_z or 0.0) + relative_elevation), 3)
                    ]
                    rebuilt_points.append(rebuilt_point)
                if rebuilt_points:
                    segment['polyline_points'] = rebuilt_points

        materials = source_data.get('materials', []) if isinstance(source_data, dict) else []
        if materials:
            for material_entry in materials:
                _rebuild_material_geometry(material_entry)
                material_entry['construction_layer'] = target_material_name
                material_entry['worksheet'] = self.current_worksheet_name
                material_entry['updated_at'] = datetime.now().isoformat()

        material_lines_config = None
        if isinstance(source_data, dict):
            material_lines_config = source_data.get('material_lines_config')
            if material_lines_config is not None:
                material_lines_config = json.loads(json.dumps(material_lines_config))

        if material_lines_config is None:
            material_lines_config = {
                "worksheet_name": self.current_worksheet_name,
                "project_name": getattr(self, 'current_project_name', "None") or "None",
                "created_by": getattr(self, 'current_user', 'user'),
                "created_at": datetime.now().isoformat(),
                "material_line": []
            }
        else:
            material_lines_config["worksheet_name"] = self.current_worksheet_name
            material_lines_config["created_by"] = getattr(self, 'current_user', 'user')
            material_lines_config["created_at"] = datetime.now().isoformat()

        unified_data = {
            "materials": materials,
            "last_updated": datetime.now().isoformat(),
            "updated_by": getattr(self, 'current_user', 'user'),
            "construction_layer": target_material_name,
            "worksheet": self.current_worksheet_name,
            "material_lines_config": material_lines_config
        }

        with open(os.path.join(target_material_path, 'material_construction_config.json'), 'w', encoding='utf-8') as f:
            json.dump(unified_data, f, indent=4, ensure_ascii=False)

        with open(os.path.join(target_material_path, 'material_lines_config.txt'), 'w', encoding='utf-8') as f:
            json.dump(material_lines_config, f, indent=4, ensure_ascii=False)

        construction_layer_config = {
            "construction_layer_name": target_material_name,
            "worksheet_name": self.current_worksheet_name,
            "project_name": getattr(self, 'current_project_name', "None") or "None",
            "worksheet_type": "Design",
            "worksheet_category": "Road",
            "construction_type": "Road",
            "reference_layer_2d": design_layer_name,
            "design_layer_name": design_layer_name,
            "base_lines_reference": ["Surface", "Construction", "Road Surface"],
            "created_at": datetime.now().isoformat(),
            "created_by": getattr(self, 'current_user', 'user'),
            "material_lines": []
        }

        with open(os.path.join(target_material_path, 'Construction_Layer_config.txt'), 'w', encoding='utf-8') as f:
            json.dump(construction_layer_config, f, indent=4, ensure_ascii=False)

        self.current_construction_layer_path = target_material_path
        self.current_construction_layer = target_material_name
        if hasattr(self, 'construction_layer_info') and isinstance(self.construction_layer_info, dict):
            self.construction_layer_info['folder'] = target_material_path
            self.construction_layer_info['name'] = target_material_name

        self.message_text.append(f"Material layer created: {target_material_name}")
        self.message_text.append(f"  Path: {target_material_path}")
        return True

