    def load_zero_line_from_layer(self, layer_path):
        """
        Load zero line configuration from the unified design_construction_config.json file.
        Sets all variables exactly like open_zero_line_dialog does.
        Updates main graph ticks + bottom chainage scale.
        """
        from json_manager import DesignConstructionManager
        
        try:
            # Try to load from unified file first
            all_baselines = DesignConstructionManager.load_all_baselines_from_unified(layer_path)
            config = all_baselines.get("zero_line_config")
            
            if not config:
                # Fallback to old file format if unified file doesn't have it
                json_path = os.path.join(layer_path, "zero_line_config.json")
                if os.path.exists(json_path):
                    with open(json_path, 'r', encoding='utf-8') as f:
                        config = json.load(f)
                else:
                    self.message_text.append(" No zero_line_config found in unified file or as separate file")
                    return False

            if not config.get("zero_line_set", False):
                self.message_text.append(" Zero line is not set in config")
                return False

            # 
            # Parse NEW format
            # 
            point1 = config.get("point1", {})
            point2 = config.get("point2", {})

            # Coordinates (must exist)
            self.zero_start_point = np.array(point1.get("coordinates", [0,0,0]), dtype=float)
            self.zero_end_point   = np.array(point2.get("coordinates", [0,0,0]), dtype=float)

            # Chainage values â€” these are what the user actually entered
            self.zero_start_km        = float(point1.get("from_km", 0))
            self.zero_start_chainage  = float(point1.get("from_chainage", 0.0))
            self.zero_end_km          = float(point2.get("to_km", 0))
            self.zero_end_chainage    = float(point2.get("to_chainage", 0.0))

            # Other settings
            self.zero_interval = float(config.get("interval_m", 20.0))
            self.zero_start_z  = config.get("reference_elevation_z")   # may be None

            # Calculate chainage-based length (this is what matters for ticks & slider)
            start_total_m = self.zero_start_km * 1000 + self.zero_start_chainage
            end_total_m   = self.zero_end_km   * 1000 + self.zero_end_chainage
            self.total_distance = end_total_m - start_total_m
            self.original_total_distance = self.total_distance

            # Mark as active
            self.zero_line_set = True

            # 
            # Update UI elements
            # 

            # 1. Redraw zero line on main 2D graph (from 0 to total chainage distance)
            if hasattr(self, 'zero_graph_line') and self.zero_graph_line is not None:
                try:
                    self.zero_graph_line.remove()
                except:
                    pass

            self.zero_graph_line, = self.ax.plot(
                [0, self.total_distance],
                [0, 0],
                color='purple',
                linewidth=3,
                label='Zero Line'
            )

            # 2. Update main graph chainage ticks
            self.update_chainage_ticks()

            # 3. Update BOTTOM chainage scale (the most common missing piece)
            if hasattr(self, 'update_scale_ticks') and callable(self.update_scale_ticks):
                self.update_scale_ticks()
                if hasattr(self, 'scale_canvas') and self.scale_canvas:
                    self.scale_canvas.draw_idle()

            # 4. Redraw canvas
            self.canvas.draw_idle()

            # 
            # Feedback
            # 
            self.message_text.append("Zero line loaded successfully (new format)")
            self.message_text.append(f"   Start: {self.zero_start_km:+.0f}+{self.zero_start_chainage:06.3f}")
            self.message_text.append(f"     End: {self.zero_end_km:+.0f}+{self.zero_end_chainage:06.3f}")
            self.message_text.append(f"  Length: {self.total_distance:,.1f} m (chainage-based)")
            self.message_text.append(f"Interval: {self.zero_interval:.1f} m")

            return True

        except Exception as e:
            msg = f"Failed to load zero line config: {type(e).__name__}: {str(e)}"
            self.message_text.append("ERROR  " + msg)
            print(msg)  # also to console for debugging
            return False

