    def load_all_baselines_from_layer(self, layer_path):
        """Load all baselines from the unified design_construction_config.json file.
        Returns dict of loaded data.
        Also updates color and polylines in self.line_types for proper display.
        """
        from json_manager import DesignConstructionManager
        
        loaded = {}
        
        # Load all baselines from unified file
        all_baselines = DesignConstructionManager.load_all_baselines_from_unified(layer_path)
        
        baseline_keys = ['surface_baseline', 'construction_baseline', 'road_surface_baseline', 'deck_line', 'projection_line']
        
        key_to_ltype = {
            'surface_baseline': 'surface',
            'construction_baseline': 'construction',
            'road_surface_baseline': 'road_surface',
            'deck_line': 'deck_line',
            'projection_line': 'projection_line',
        }

        for baseline_key in baseline_keys:
            data = all_baselines.get(baseline_key)
            if not data:
                continue

            try:
                ltype = key_to_ltype[baseline_key]
                loaded[ltype] = data

                # Initialize line_type entry if not exists
                if ltype not in self.line_types:
                    self.line_types[ltype] = {'color': 'gray', 'polylines': [], 'artists': []}

                # Update color from JSON if available
                saved_color = data.get("color")
                if saved_color:
                    self.line_types[ltype]['color'] = saved_color

                # Store polylines in memory (for 3D planes and 2D graph)
                polylines_2d = []
                for poly in data.get("polylines", []):
                    # Add layer_folder to polyline for wall creation logic
                    poly["layer_folder"] = layer_path
                    
                    poly_2d = [(pt["chainage_m"], pt["relative_elevation_m"]) for pt in poly["points"]]
                    if len(poly_2d) >= 2:
                        polylines_2d.append(poly_2d)

                self.line_types[ltype]['polylines'] = polylines_2d

            except Exception as e:
                self.message_text.append(f"Error loading {baseline_key}: {str(e)}")

        return loaded

    # ---- Aniket added on 02-05-2026 for the material filling logic in Save Construction ---- ture & false checks
    def _as_bool_flag(self, value, default=False):
        """Normalize persisted boolean-like values from JSON/config files."""
        if isinstance(value, bool):
            return value
        if value is None:
            return default
        if isinstance(value, str):
            normalized = value.strip().lower()
            if normalized in ("true", "1", "yes", "y", "on"):
                return True
            if normalized in ("false", "0", "no", "n", "off", "flase"):
                return False
            return default
        return bool(value)

