    def save_current_design_layer(self):
        """
        Save checked baselines + create realistic earthwork operation_config.json
        after road_surface is saved.
        For Bridge mode: Save without width requirement (green polylines only)
        For Road mode: Save with width data (plane strips)
        """
        # Intercept when Save Construction is clicked
        if hasattr(self, 'save_button') and self.save_button.text() == "Save Construction":
            self.upload_construction_material_data()
            return

        if not hasattr(self, 'current_worksheet_name') or not self.current_worksheet_name:
            QMessageBox.warning(self, "No Worksheet", "No active worksheet.")
            return
        if not hasattr(self, 'current_layer_name') or not self.current_layer_name:
            QMessageBox.warning(self, "No Layer", "No active design layer.")
            return

        layer_folder = os.path.join(
            self.WORKSHEETS_BASE_DIR,
            self.current_worksheet_name,
            "designs",
            self.current_layer_name
        )
        if not os.path.exists(layer_folder):
            QMessageBox.critical(self, "Folder Missing", f"Design layer folder not found:\n{layer_folder}")
            return

        if not self.zero_line_set:
            QMessageBox.warning(self, "Zero Line Required", "Zero line must be set.")
            return

        # Determine reference type (Bridge or Road)
        current_ref_type = self.get_current_reference_type()

        # ====== Handle duplication for editing ======
        if getattr(self, 'is_edited', False):
            self.is_edited = False  # Reset flag so we don't infinitely duplicate
            import shutil
            import re
            
            designs_folder = os.path.dirname(layer_folder)
            base_name = self.current_layer_name
            # Remove any trailing _N
            base_name_clean = re.sub(r'_\d+$', '', base_name)
            
            counter = 1
            while True:
                new_layer_name = f"{base_name_clean}_{counter}"
                new_layer_folder = os.path.join(designs_folder, new_layer_name)
                if not os.path.exists(new_layer_folder):
                    break
                counter += 1
                
            try:
                shutil.copytree(layer_folder, new_layer_folder)
                self.message_text.append(f" Editing detected. Duplicating active layer to '{new_layer_name}' before saving changes.")
                
                # Update current paths
                self.current_layer_name = new_layer_name
                layer_folder = new_layer_folder
                
                # Add to UI
                self.add_layer_to_panel(new_layer_name, "2D", full_path=layer_folder, subfolder=self.current_subfolder_type)
                if hasattr(self, 'set_layer_panel_highlight'):
                    linked_design = None
                    if str(getattr(self, 'current_subfolder_type', '')).lower() == 'construction':
                        linked_design = getattr(self, 'reference_design_layer', None)
                    self.set_layer_panel_highlight(
                        active_layer_name=new_layer_name,
                        active_subfolder=self.current_subfolder_type,
                        linked_design_layer_name=linked_design
                    )
            except Exception as e:
                QMessageBox.critical(self, "Error", f"Failed to create new edited layer folder:\n{e}")
                return

        # ====== Load all baselines from master JSON ======
        surface_data = None
        construction_data = None
        road_surface_data = None

        try:
            from json_manager import DesignConstructionManager
            master_data = DesignConstructionManager.load_master(layer_folder)
            design_dict = master_data.get("design", {})
            surface_data = design_dict.get("surface_baseline")
            construction_data = design_dict.get("construction_baseline")
            road_surface_data = design_dict.get("road_surface_baseline")
        except Exception as e:
            self.message_text.append(f"Warning: Could not load baselines from master JSON: {e}")

        saved_count = 0
        saved_files = []
        road_surface_just_saved = False

        dir_vec = self.zero_end_point - self.zero_start_point
        zero_length = self.total_distance
        ref_z = self.zero_start_z

        baseline_checkboxes = {
            'surface': self.surface_baseline,
            'construction': self.construction_line,
            'road_surface': self.road_surface_line,
            'deck_line': self.deck_line,
            'projection_line': self.projection_line,
        }

        # ===== Bridge-specific baselines that don't need width =====
        bridge_baselines = ['deck_line', 'projection_line']

        # ====== Collect baseline data (no individual saves) ======
        baselines_data = {
            'surface': None,
            'construction': None,
            'road_surface': None,
            'deck_line': None,
            'projection_line': None,
        }

        for ltype, checkbox in baseline_checkboxes.items():
            if not checkbox.isChecked():
                continue

            polylines = self.line_types[ltype]['polylines']
            if not polylines:
                continue

            # ===== Check width requirement =====
            if current_ref_type == "Bridge" and ltype in bridge_baselines:
                self.baseline_widths[ltype] = 0.0
            else:
                has_lane_drop = (ltype in getattr(self, 'baseline_configs', {}) and getattr(self, 'baseline_configs', {}).get(ltype, {}).get('mode') == 'lane_drop')
                
                if (ltype not in self.baseline_widths or self.baseline_widths[ltype] <= 0) and not has_lane_drop:
                    QMessageBox.warning(
                        self,
                        "Width Missing",
                        f"No valid width for {ltype.replace('_', ' ').title()}.\n"
                        "Please set width via 'Map on 3D' first."
                    )
                    continue

            try:
                # ===== BUILD baseline data (don't save individual files) =====
                baseline_data = self._build_baseline_data(ltype)
                
                if baseline_data:
                    saved_count += 1
                    baselines_data[ltype] = baseline_data
                    saved_files.append(f"{ltype}_baseline")
                    
                    if ltype == "surface":
                        surface_data = baseline_data
                    elif ltype == "construction":
                        construction_data = baseline_data
                    elif ltype == "road_surface":
                        road_surface_just_saved = True
                        road_surface_data = baseline_data
                else:
                    self.message_text.append(f"Failed to build {ltype} baseline data")

            except Exception as e:
                QMessageBox.critical(self, "Build Failed", f"Error building {ltype}:\n{str(e)}")
                return

       # ======================================================================
        #   After road surface built  add diff + realistic earthwork config
        #   (Only for Road mode)
       # ======================================================================
        if current_ref_type != "Bridge" and road_surface_just_saved and surface_data and road_surface_data:

            # 1. Add surface_to_road_surface_diff_m to road surface points
            for poly in road_surface_data["polylines"]:
                for pt in poly["points"]:
                    ch = pt["chainage_m"]
                    min_d = float('inf')
                    surf_rel = None
                    for s_poly in surface_data.get("polylines", []):
                        for s_pt in s_poly.get("points", []):
                            d = abs(s_pt["chainage_m"] - ch)
                            if d < min_d:
                                min_d = d
                                surf_rel = s_pt["relative_elevation_m"]
                    if surf_rel is not None:
                        abs_diff = abs(round(surf_rel - pt["relative_elevation_m"], 3))
                        pt["surface_to_road_surface_diff_m"] = abs_diff

            # 2. Build earthwork operation_config data (don't save individually)

            operations = []

            if road_surface_data.get("polylines"):
                main_poly = road_surface_data["polylines"][0]  # assuming single main alignment
                points = main_poly["points"]

                TOL_BALANCED = 0.20   # meters - adjust if needed
                TOL_SURF_ROAD = 0.04  # old small tolerance - can keep or merge with above

                # Width configuration for each baseline type
                rs_config   = getattr(self, 'baseline_configs', {}).get("road_surface", {"mode": "normal", "width": self.baseline_widths.get("road_surface", 12.0)})
                const_config = getattr(self, 'baseline_configs', {}).get("construction", {"mode": "normal", "width": self.baseline_widths.get("construction", 20.0)})
                surf_config  = getattr(self, 'baseline_configs', {}).get("surface",      {"mode": "normal", "width": self.baseline_widths.get("surface", 0.0)})

                # No need to build separate lookups (curve_lookup, approach_lookup) 
                # because save_baseline_with_curves has already embedded the data into the points.

                for i in range(len(points) - 1):
                    p1 = points[i]
                    p2 = points[i + 1]

                    ch1 = p1["chainage_m"]
                    ch2 = p2["chainage_m"]
                    str1 = p1["chainage_str"]
                    str2 = p2["chainage_str"]

                    length = ch2 - ch1
                    if length <= 0:
                        continue

                    def get_abs_elev(baseline_data, chainage, ref_z):
                        min_d = float('inf')
                        rel_elev = None
                        for poly in baseline_data.get("polylines", []):
                            for pt in poly["points"]:
                                d = abs(pt["chainage_m"] - chainage)
                                if d < min_d:
                                    min_d = d
                                    rel_elev = pt["relative_elevation_m"]
                        if rel_elev is not None and min_d < 10.0:
                            return ref_z + rel_elev
                        return None

                    surf_z1   = get_abs_elev(surface_data,   ch1, ref_z)
                    surf_z2   = get_abs_elev(surface_data,   ch2, ref_z)
                    road_z1   = get_abs_elev(road_surface_data, ch1, ref_z)
                    road_z2   = get_abs_elev(road_surface_data, ch2, ref_z)
                    const_z1  = get_abs_elev(construction_data, ch1, ref_z) if construction_data else None
                    const_z2  = get_abs_elev(construction_data, ch2, ref_z) if construction_data else None

                    # Parse KM/Chainage for easier reading in JSON
                    f_km, f_ch = 0, 0
                    if '+' in str1:
                        try:
                            parts = str1.split('+')
                            if len(parts) >= 2:
                                f_km = int(float(parts[0]))
                                f_ch = int(float(parts[1]))
                        except:
                            pass

                    t_km, t_ch = 0, 0
                    if '+' in str2:
                        try:
                            parts = str2.split('+')
                            if len(parts) >= 2:
                                t_km = int(float(parts[0]))
                                t_ch = int(float(parts[1]))
                        except:
                            pass
                            
                    # Calculate heights at midpoint for 100% accuracy (avoids boundary ambiguity)
                    mid_m = (ch1 + ch2) / 2
                    
                    surf_rel = self.interpolate_rel_z_at_chainage(surface_data, mid_m)
                    road_rel = self.interpolate_rel_z_at_chainage(road_surface_data, mid_m)
                    const_rel = self.interpolate_rel_z_at_chainage(construction_data, mid_m) if construction_data else None

                    # Calculate absolute elevations
                    avg_surf = surf_rel + ref_z if surf_rel is not None else None
                    avg_road = road_rel + ref_z if road_rel is not None else None
                    avg_const = const_rel + ref_z if const_rel is not None else None

                    if avg_surf is None or avg_road is None:
                        # Skip if basic data missing
                        continue

                    surface_to_road_val = abs(avg_surf - avg_road)
                    surface_to_construction_val = 0.0
                    construction_to_road_val = 0.0

                    if avg_const is not None:
                        surface_to_construction_val = abs(avg_surf - avg_const)
                        construction_to_road_val = abs(avg_const - avg_road)

                    # Extract angle data directly from point p1 (embedded by save_baseline_with_curves)
                    road_ang = 0.0
                    road_dir_int = 0  # 0=None, 1=Inner, 2=Outer

                    if "angle_deg" in p1:
                        road_ang = float(p1["angle_deg"])
                        # Check direction booleans or legacy strings if any
                        if p1.get("inner_curve"):
                            road_dir_int = 1
                        elif p1.get("outer_curve"):
                            road_dir_int = 2
                        # Default is 0

                    app_ang = 0.0
                    app_dir_int = 0 # 0=None, 1=Upward, 2=Downward

                    if "elevation_angle" in p1:
                        app_ang = float(p1["elevation_angle"])
                        if p1.get("upward"):
                            app_dir_int = 1
                        elif p1.get("downward"):
                            app_dir_int = 2

                    # Calculate widths
                    w_surface = round((self.get_width_at_chainage(surf_config, ch1) + self.get_width_at_chainage(surf_config, ch2)) / 2, 2)
                    w_construction = round((self.get_width_at_chainage(const_config, ch1) + self.get_width_at_chainage(const_config, ch2)) / 2, 2)
                    w_road_surface = round((self.get_width_at_chainage(rs_config, ch1) + self.get_width_at_chainage(rs_config, ch2)) / 2, 2)

                    segment = {
                        "from_chainage_str": str1,
                        "to_chainage_str": str2,
                        "from_km": f_km,
                        "from_chainage": f_ch,
                        "to_km": t_km,
                        "to_chainage": t_ch,
                        "operation_type": "data_missing",
                        "cut_volume_ref_construction_m3": 0.0,
                        "cut_volume_ref_road_surface_m3": 0.0,
                        "digging_volume_m3": 0.0,
                        
                        # New Data Fields
                        "surface_to_construction_line_avg_m": round(surface_to_construction_val, 3),
                        "construction_to_road_surface_line_avg_m": round(construction_to_road_val, 3),
                        "surface_to_road_surface_line_avg_m": round(surface_to_road_val, 3),
                        
                        # Updated width calculation: Use average width (ch1 to ch2) for better accuracy during transitions
                        "width_surface_m": w_surface,
                        "width_construction_m": w_construction,
                        "width_road_surface_m": w_road_surface,
                        
                        "road_angle": float(road_ang),
                        "road_angle_direction": int(road_dir_int),
                        
                        "approach_angle": float(app_ang),
                        "approach_angle_direction": int(app_dir_int)
                    }


                    # Trigger operation type based on Surface crossing Road Surface
                    # (avg_surf, avg_road, avg_const are already calculated at midpoint)
                    height_surf_road_signed = avg_surf - avg_road
                    height_surf_const_signed = avg_surf - avg_const if avg_const is not None else 0.0

                    #  New priority: check construction closeness first 
                    is_balanced_by_construction = False

                    if avg_const is not None:
                        if abs(height_surf_const_signed) <= TOL_BALANCED:
                            is_balanced_by_construction = True

                    cut_vol_constr = 0.0
                    cut_vol_road   = 0.0
                    digging_vol    = 0.0

                    if is_balanced_by_construction:
                        operation = "balanced"
                    elif height_surf_road_signed > TOL_SURF_ROAD:
                        operation = "cutting"

                        # Cut to construction (Volume = Surface - Construction)
                        if avg_const is not None:
                            h_constr = abs(height_surf_const_signed)
                            cut_vol_constr = round(h_constr * w_construction * length, 2)

                        # Cut to road surface volume is ignored
                        cut_vol_road = 0.0

                    elif height_surf_road_signed < -TOL_SURF_ROAD:
                        operation = "digging"
                        # Digging volume (Volume = Construction - Surface)
                        h_dig = abs(height_surf_const_signed)
                        digging_vol = round(h_dig * w_construction * length, 2)
                    else:
                        operation = "balanced"

                    segment["operation_type"] = operation

                    if operation == "cutting":
                        segment["cut_volume_ref_construction_m3"] = cut_vol_constr
                        segment["cut_volume_ref_road_surface_m3"] = cut_vol_road
                    elif operation == "digging":
                        segment["digging_volume_m3"] = digging_vol
                    # balanced  all volumes stay 0.0

                    operations.append(segment)


            # Sort segments by chainage string
            operations.sort(key=lambda x: x["from_chainage_str"])

            config_data = {
                "zero_line_start": self.zero_start_point.tolist(),
                "zero_line_end": self.zero_end_point.tolist(),
                "zero_start_elevation": float(ref_z),
                "total_chainage_length": float(zero_length),
                "volume_method": "Average End Area (Trapezoidal)",
                "segments": operations
            }

            config_path = os.path.join(layer_folder, "operation_config.json")
            # Store operation config instead of saving individual file
            baselines_data['operation_config'] = config_data
                  
        # Final feedback 
        if saved_count > 0:
            file_list = "\n".join([f"• {f}" for f in saved_files])
            mode_type = "Bridge" if current_ref_type == "Bridge" else "Road"
            self.message_text.append(f"{mode_type} Mode - Collected {saved_count} baseline(s) for unified save:")
            self.message_text.append(file_list)

            QMessageBox.information(
                self,
                "Data Collected",
                f"{mode_type} Mode\n\n"
                f"Collected {saved_count} baseline(s).\n\n"
                f"Creating unified JSON file..."
            )
        else:
            QMessageBox.information(self, "Nothing Saved", "No valid baselines to save.")

        # =================================================================================================================
        # NOW CONSOLIDATE ALL DATA INTO ONE UNIFIED LAYER JSON FILE

        
        if saved_count > 0 or saved_files:
            self.consolidate_design_layer_to_single_json(layer_folder, baselines_data)

