    def _build_baseline_data(self, ltype):
        """
        Build baseline data structure with curves and coordinates.
        Similar to save_baseline_with_curves() but returns data instead of saving.
        """
        if not self.line_types[ltype]['polylines']:
            return None

        dir_vec = self.zero_end_point - self.zero_start_point
        zero_length = self.total_distance
        ref_z = self.zero_start_z

        def format_chainage_str(chainage_m: float) -> str:
            if not hasattr(self, 'zero_start_km') or self.zero_start_km is None:
                return f"{chainage_m:.3f}m"
            start_abs_m = (self.zero_start_km * 1000) + self.zero_start_chainage
            cur_abs_m = start_abs_m + chainage_m
            km_part = int(cur_abs_m // 1000)
            metres_part = cur_abs_m % 1000
            return f"{km_part}+{metres_part:06.3f}"

        baseline_data = {
            "baseline_type": ltype.replace('_', ' ').title(),
            "baseline_key": ltype,
            "color": self.line_types[ltype]['color'],
            "width_meters": float(self.baseline_widths.get(ltype, 0.0)),
            "zero_line_start": self.zero_start_point.tolist(),
            "zero_line_end": self.zero_end_point.tolist(),
            "zero_start_elevation": float(ref_z),
            "total_chainage_length": float(zero_length),
            "polylines": []
        }

        if hasattr(self, 'reference_type') and self.reference_type:
            baseline_data["reference_type"] = self.reference_type
        else:
            baseline_data["reference_type"] = "Road"

        curve_list = []
        if self.curve_labels:
            for item in self.curve_labels:
                chainage = float(item['chainage'])
                angle_data = {
                    'angle_deg': float(item['config']['angle']),
                    'inner_curve': bool(item['config']['inner_curve']),
                    'outer_curve': bool(item['config']['outer_curve'])
                }
                curve_list.append((chainage, angle_data))
            curve_list.sort(key=lambda x: x[0])

        def find_matching_curve(dist, tolerance=0.5):
            if not curve_list:
                return None
            min_diff = float('inf')
            best_angle_data = None
            for curve_ch, angle_data in curve_list:
                diff = abs(dist - curve_ch)
                if diff < min_diff and diff <= tolerance:
                    min_diff = diff
                    best_angle_data = angle_data
            return best_angle_data

        for poly_2d in self.line_types[ltype]['polylines']:
            poly_3d_points = []
            for pt in poly_2d:
                if len(pt) == 3:
                    dist, rel_z, angle = pt
                    inline_angle = float(angle) if angle is not None else None
                else:
                    dist, rel_z = pt
                    inline_angle = None

                abs_z = ref_z + rel_z
                try:
                    real_x, real_y, _ = self.get_real_coordinates_from_chainage(dist)
                    
                    if real_x is None or real_y is None:
                        # Fallback to linear if alignment yields nothing
                        t = dist / zero_length if zero_length > 0 else 0
                        pos_along = self.zero_start_point + t * dir_vec
                        real_x, real_y = pos_along[0], pos_along[1]
                except Exception:
                    t = dist / zero_length if zero_length > 0 else 0
                    pos_along = self.zero_start_point + t * dir_vec
                    real_x, real_y = pos_along[0], pos_along[1]

                world_point = [float(real_x), float(real_y), float(abs_z)]

                baseline_config = getattr(self, 'baseline_configs', {}).get(ltype, {'mode': 'normal', 'width': self.baseline_widths.get(ltype, 10.0)})
                width_at_pt = self.get_width_at_chainage(baseline_config, dist)

                point_data = {
                    "chainage_m": float(dist),
                    "chainage_str": format_chainage_str(dist),
                    "relative_elevation_m": float(rel_z),
                    "width_m": float(width_at_pt),
                    "world_coordinates": world_point
                }

                angle_data = find_matching_curve(dist, tolerance=0.5)
                if angle_data:
                    point_data["angle_deg"] = angle_data['angle_deg']
                    point_data["inner_curve"] = angle_data['inner_curve']
                    point_data["outer_curve"] = angle_data['outer_curve']

                if inline_angle is not None:
                    point_data["elevation_angle"] = abs(inline_angle)   # store magnitude
                    point_data["upward"] = inline_angle > 0
                    point_data["downward"] = inline_angle < 0

                poly_3d_points.append(point_data)

            if len(poly_3d_points) >= 2:
                start_ch = poly_3d_points[0]["chainage_m"]
                end_ch = poly_3d_points[-1]["chainage_m"]
                baseline_data["polylines"].append({
                    "start_chainage_m": float(start_ch),
                    "start_chainage_str": format_chainage_str(start_ch),
                    "end_chainage_m": float(end_ch),
                    "end_chainage_str": format_chainage_str(end_ch),
                    "points": poly_3d_points
                })

        if self.curve_labels:
            baseline_data["curves"] = []
            for item in self.curve_labels:
                curve_entry = {
                    "chainage_m": float(item['chainage']),
                    "angle_deg": float(item['config']['angle']),
                    "inner_curve": bool(item['config']['inner_curve']),
                    "outer_curve": bool(item['config']['outer_curve'])
                }
                baseline_data["curves"].append(curve_entry)

        # ========== ADD APPROACH ROAD WALL CONFIGURATION ==========
        if ltype == 'road_surface' and hasattr(self, 'approach_road_wall_width'):
            baseline_data["approach_road_wall_configuration"] = {
                "wall_width": self.approach_road_wall_width
            }

        return baseline_data

