    def consolidate_design_layer_to_single_json(self, layer_folder, baselines_data):
        """
        Consolidates all collected baseline data into a single unified JSON file.
        File name: design_construction_config.json (ALWAYS)
        Includes ALL baselines (surface, construction, road_surface, deck_line, projection_line, operational_config)
        """
        try:
            from json_manager import DesignConstructionManager
            
            # Get zero_line_config data
            zero_line_config = self.save_zero_line_config_to_current_layer()
            
            # Extract ALL baselines from the collected data (including None values)
            surface_baseline = baselines_data.get('surface')
            construction_baseline = baselines_data.get('construction')
            road_surface_baseline = baselines_data.get('road_surface')
            deck_line = baselines_data.get('deck_line')
            projection_line = baselines_data.get('projection_line')
            operational_config = baselines_data.get('operation_config')
            
            # Get current user
            current_user = getattr(self, 'current_user', 'aniket07')
            
            # Save ALL data to unified JSON using manager
            # Note: layer_name parameter is ignored - always saves to design_construction_config.json
            success = DesignConstructionManager.save_all_design_layer_baselines(
                layer_root=layer_folder,
                layer_name=None,
                zero_line_config=zero_line_config,
                surface_baseline=surface_baseline,
                construction_baseline=construction_baseline,
                road_surface_baseline=road_surface_baseline,
                deck_line=deck_line,
                projection_line=projection_line,
                operational_config=operational_config,
                saved_by=current_user
            )
            
            if success:
                mode_type = "ðŸŒ‰ Bridge" if hasattr(self, 'reference_type') and self.reference_type == "Bridge" else "ðŸ›£ Road"
                self.message_text.append(f" {mode_type} Mode - All baseline data consolidated into design_construction_config.json")
                self.message_text.append(f"  Location: {os.path.join(layer_folder, 'design_construction_config.json')}")
                QMessageBox.information(
                    self,
                    " Save Complete",
                    f" All baseline data consolidated into:\n\ndesign_construction_config.json\n\nLocation:\n{layer_folder}"
                )
                
                # After successful local save, send full JSON to remote API
                try:
                    json_path = os.path.join(layer_folder, 'design_construction_config.json')
                    if os.path.exists(json_path):
                        with open(json_path, 'r', encoding='utf-8') as jf:
                            layer_json = json.load(jf)

                        # Determine ids for API call
                        api_user_id = getattr(self, 'current_api_user_id', None) or getattr(self, 'current_user_id', None) or getattr(self, 'current_user', None)
                        layer_id = getattr(self, 'current_layer_id', None)
                        # Collect candidate worksheet id values and pick a valid primitive id
                        candidate = (
                            getattr(self, 'current_worksheet_id', None)
                            or (getattr(self, 'current_worksheet_data', {}) or {}).get('id')
                            or (getattr(self, 'current_worksheet_data', {}) or {}).get('worksheet_id')
                            or getattr(self, 'created_worksheet_id', None)
                        )

                        # Normalize: if candidate is a dict (error or response), attempt to extract id; else accept if primitive
                        def _normalize_wsid(c):
                            if c is None:
                                return None
                            if isinstance(c, dict):
                                for k in ('worksheet_id', 'worksheetId', 'id'):
                                    v = c.get(k)
                                    if v is not None and not isinstance(v, dict):
                                        return v
                                return None
                            if isinstance(c, (int, str)):
                                s = str(c).strip()
                                return int(s) if s.isdigit() else s
                            return None

                        worksheet_id = _normalize_wsid(candidate)
                        print(f"candidate: {candidate}")
                        print(f"worksheet_id: {worksheet_id}")

                        # Call the API (mode=1)
                        try:
                            resp = WorksheetAPI.update_worksheet_layer(api_user_id, 1, layer_id, worksheet_id, layer_json)
                            if resp.get('success'):
                                QMessageBox.information(self, "Upload", "Design layer JSON sent to server successfully.")
                                self.message_text.append(" design_construction_config.json uploaded to server.")
                            else:
                                # Show server response for troubleshooting
                                errmsg = resp.get('message') or resp.get('text') or str(resp)
                                QMessageBox.warning(self, "Upload Failed", f"Server returned an error:\n{errmsg}")
                                self.message_text.append(f"  Failed to upload design JSON: {errmsg}")
                        except Exception as e:
                            QMessageBox.warning(self, "Upload Error", f"Error while calling API:\n{e}")
                            self.message_text.append(f"  Exception during API call: {e}")
                    else:
                        self.message_text.append("  design_construction_config.json not found for upload.")
                except Exception as e:
                    self.message_text.append(f"Error preparing upload: {e}")
                # Additionally, if a construction layer exists with material JSON, upload it using mode=2
                try:
                    material_path = None
                    # Prefer explicit current_construction_layer_path if set
                    if hasattr(self, 'current_construction_layer_path') and self.current_construction_layer_path:
                        candidate = os.path.join(self.current_construction_layer_path, 'material_construction_config.json')
                        if os.path.exists(candidate):
                            material_path = candidate
                    # Fallback: look for material file relative to layer_folder (sibling 'construction' folder)
                    if not material_path:
                        sibling = os.path.join(os.path.dirname(layer_folder), '..', 'construction')
                        sibling_path = os.path.normpath(os.path.join(sibling, 'material_construction_config.json'))
                        if os.path.exists(sibling_path):
                            material_path = sibling_path

                    if material_path and os.path.exists(material_path):
                        try:
                            with open(material_path, 'r', encoding='utf-8') as mf:
                                material_json = json.load(mf)
                        except Exception:
                            material_json = None

                        if material_json is not None:
                            api_user_id = getattr(self, 'current_api_user_id', None) or getattr(self, 'current_user_id', None) or getattr(self, 'current_user', None)
                            layer_id = getattr(self, 'current_layer_id', None)
                            candidate = (
                                getattr(self, 'current_worksheet_id', None)
                                or (getattr(self, 'current_worksheet_data', {}) or {}).get('id')
                                or (getattr(self, 'current_worksheet_data', {}) or {}).get('worksheet_id')
                                or getattr(self, 'created_worksheet_id', None)
                            )

                            def _normalize_wsid(c):
                                if c is None:
                                    return None
                                if isinstance(c, dict):
                                    for k in ('worksheet_id', 'worksheetId', 'id'):
                                        v = c.get(k)
                                        if v is not None and not isinstance(v, dict):
                                            return v
                                    return None
                                if isinstance(c, (int, str)):
                                    s = str(c).strip()
                                    return int(s) if s.isdigit() else s
                                return None

                            worksheet_id = _normalize_wsid(candidate)
                            print(f"MODE=2 upload: material_path={material_path}, worksheet_candidate={candidate}, worksheet_id={worksheet_id}")

                            try:
                                resp2 = WorksheetAPI.update_worksheet_layer(api_user_id, 2, layer_id, worksheet_id, material_json)
                                if resp2.get('success'):
                                    QMessageBox.information(self, "Upload", "Material JSON sent to server successfully.")
                                    self.message_text.append(" material_construction_config.json uploaded to server.")
                                else:
                                    errmsg = resp2.get('message') or resp2.get('text') or str(resp2)
                                    QMessageBox.warning(self, "Upload Failed", f"Material upload failed:\n{errmsg}")
                                    self.message_text.append(f"  Failed to upload material JSON: {errmsg}")
                            except Exception as e:
                                QMessageBox.warning(self, "Upload Error", f"Error during material upload:\n{e}")
                                self.message_text.append(f"  Exception during material upload: {e}")
                    else:
                        # No material file found â€” silently continue
                        pass
                except Exception as e:
                    self.message_text.append(f"Error preparing material upload: {e}")
            else:
                self.message_text.append(f"  Failed to consolidate to design_construction_config.json")
                
        except Exception as e:
            self.message_text.append(f"Error during layer consolidation: {e}")
            import traceback
            traceback.print_exc()

