    def get_master_data(self, loaded_baselines):
            for key in ['road_surface', 'construction', 'surface']:
                if key in loaded_baselines:
                    return loaded_baselines[key]
            if loaded_baselines:
                return next(iter(loaded_baselines.values()))
            return None
    
    def interpolate_rel_z_at_chainage(self, baseline_data, ch):
        rel_z = 0.0  # Default if not found
        for poly in baseline_data.get("polylines", []):
            points = poly.get("points", [])
            for i in range(len(points) - 1):
                pt1 = points[i]
                pt2 = points[i + 1]
                ch1 = pt1["chainage_m"]
                ch2 = pt2["chainage_m"]
                if ch1 <= ch <= ch2 or ch2 <= ch <= ch1:  # Handle possible reverse order
                    denom = abs(ch2 - ch1)
                    if denom > 0:
                        t = abs(ch - ch1) / denom
                    else:
                        t = 0
                    z1 = pt1["relative_elevation_m"]
                    z2 = pt2["relative_elevation_m"]
                    rel_z = z1 + t * (z2 - z1)
                    return rel_z
        # If not found, find nearest point
        min_dist = float('inf')
        nearest_z = 0.0
        for poly in baseline_data.get("polylines", []):
            for pt in poly.get("points", []):
                dist = abs(pt["chainage_m"] - ch)
                if dist < min_dist:
                    min_dist = dist
                    nearest_z = pt["relative_elevation_m"]
        if min_dist < 10.0:  # Reasonable threshold
            return nearest_z
        self.message_text.append(f"Warning: No rel_z found or near ch={ch:.2f} for {baseline_data.get('baseline_key', 'unknown')}")
        return rel_z

    def get_width_at_chainage(self, config, chainage):
        """
        Helper to get width at a specific chainage based on configuration.
        config: {'mode': 'normal'|'lane_drop', 'width': float, 'sections': [...]}
        chainage: distance from start of zero line (can be relative if offset is handled)
        """
        # Calculate absolute chainage if possible
        abs_start = 0.0
        if hasattr(self, 'zero_start_km') and self.zero_start_km is not None:
            abs_start = (self.zero_start_km * 1000) + (self.zero_start_chainage or 0.0)
        
        # We work with actual chainage used in sections
        target_ch = abs_start + chainage
        
        if config.get('mode') == 'normal':
            return float(config.get('width', 10.0))
        
        sections = config.get('sections', [])
        if not sections:
            return float(config.get('width', 10.0))
        
        # Sort sections by from_ch (using the key defined in dialogs.py)
        # We use .get() and a fallback to avoid crashes if keys are missing
        try:
            sorted_sections = sorted(sections, key=lambda x: x.get('from_ch', x.get('from_chainage', 0)))
        except Exception as e:
            print(f"Error sorting sections: {e}")
            return float(config.get('width', 10.0))
        
        # 1. Check if inside a section (constant width)
        for section in sorted_sections:
            f_ch = section.get('from_ch', section.get('from_chainage'))
            t_ch = section.get('to_ch', section.get('to_chainage'))
            w = section.get('width', 10.0)
            
            if f_ch is not None and t_ch is not None:
                if f_ch <= target_ch <= t_ch:
                    return float(w)
        
        # 2. Check if in a gap between sections (linear transition)
        for i in range(len(sorted_sections) - 1):
            s1 = sorted_sections[i]
            s2 = sorted_sections[i+1]
            
            ch1 = s1.get('to_ch', s1.get('to_chainage'))
            ch2 = s2.get('from_ch', s2.get('from_chainage'))
            w1 = s1.get('width', 10.0)
            w2 = s2.get('width', 10.0)
            
            if ch1 is not None and ch2 is not None:
                if ch1 < target_ch < ch2:
                    d = ch2 - ch1
                    if d > 1e-4:
                        t = (target_ch - ch1) / d
                        return w1 + t * (w2 - w1)
                    return w1
        
        # 3. Fallback to start/end boundaries
        if sorted_sections:
            first_ch = sorted_sections[0].get('from_ch', sorted_sections[0].get('from_chainage', 0))
            last_ch = sorted_sections[-1].get('to_ch', sorted_sections[-1].get('to_chainage', 0))
            
            if target_ch < first_ch:
                return float(sorted_sections[0].get('width', 10.0))
            if target_ch > last_ch:
                return float(sorted_sections[-1].get('width', 10.0))
            
        return float(config.get('width', 10.0))

