    def show_graph_section(self, category):
        """
        Prepares the design graph controls without forcing the graph or scale visible.

        The graph and scale are shown only from the design eye-open path.
        """
        # ── Check current app mode ─────────────────────────────────────────
        current_app_mode = getattr(self, 'app_mode', 'Design')

        # 1. Keep the entire bottom section hidden until a design layer is opened.
        if hasattr(self, 'bottom_section'):
            self.bottom_section.setVisible(False)

        # 2. Keep scale hidden until a layer is opened from the eye button.
        if hasattr(self, 'scale_section'):
            self.scale_section.setVisible(False)

        # 7. Force redraw of matplotlib canvas
        if hasattr(self, 'canvas'):
            self.canvas.draw_idle()

        # 8. Force layout update
        QApplication.processEvents()

