    def show_feedback_dialog(self):
        """Open the Feedback Dialog when Feedback button is clicked and handle submission."""
        dialog = FeedbackDialog(self)
        if dialog.exec_() == QDialog.Accepted:
            message = dialog.get_feedback().strip()
            if not message:
                QMessageBox.warning(self, "Empty Feedback", "Please write a message before sending.")
                return

            # Prepare data: user_id from self.current_user_id, user_type: 1 (Road)
            user_id = self.current_user_id
            user_type = 1 # Road as per request
            
            # Call API
            result = WorksheetAPI.send_feedback(user_id, user_type, message)
            
            if result.get("success"):
                QMessageBox.information(self, "Success", "Thank you for your feedback!")
            else:
                QMessageBox.critical(self, "Error", f"Failed to send feedback: {result.get('message')}")

    def show_buy_files_dialog(self):
        """Open the Buy 3D Files Dialog"""
        print(f"DEBUG: show_buy_files_dialog() called")
        print(f"  self.current_user_id (euh_id)={self.current_user_id}")
        print(f"  self.current_api_user_id (API id)={self.current_api_user_id}")
        dialog = Buy3DFilesDialog(self.current_api_user_id, euh_id=self.current_user_id, parent=self)
        dialog.exec_()

