    def clear_baseline_planes(self):
        """Clear all baseline plane actors from the 3D view"""
        if hasattr(self, 'renderer') and self.renderer:
            for actor in self.baseline_plane_actors:
                if self.renderer.HasViewProp(actor):
                    self.renderer.RemoveActor(actor)

            if hasattr(self, 'road_surface_plane_actors'):
                for actor in self.road_surface_plane_actors:
                    if self.renderer.HasViewProp(actor):
                        self.renderer.RemoveActor(actor)
                self.road_surface_plane_actors = []
            
            # Clear chainage markers added to surface/road_surface baselines
            if hasattr(self, 'chainage_marker_actors'):
                for actor in self.chainage_marker_actors:
                    if self.renderer.HasViewProp(actor):
                        self.renderer.RemoveActor(actor)
                self.chainage_marker_actors = []
                
        self.baseline_plane_actors = []
        if hasattr(self, 'vtk_widget') and self.vtk_widget:
            self.vtk_widget.GetRenderWindow().Render()

