    def focus_camera_on_full_cloud(self):
        """Focus camera on the entire point cloud"""
        if not self.point_cloud or not self.point_cloud_actor:
            return
        try:
            bounds = self.point_cloud_actor.GetBounds()
            if bounds[0] >= bounds[1]:  # Invalid bounds
                return
            center = [(bounds[0] + bounds[1]) / 2,
                      (bounds[2] + bounds[3]) / 2,
                      (bounds[4] + bounds[5]) / 2]
            size_x = bounds[1] - bounds[0]
            size_y = bounds[3] - bounds[2]
            size_z = bounds[5] - bounds[4]
            avg_size = (size_x + size_y + size_z) / 3.0

            camera = self.renderer.GetActiveCamera()
            camera.SetFocalPoint(*center)
            offset = avg_size * 1.8  # Slightly farther for full view
            camera.SetPosition(center[0] + offset, center[1], center[2] + offset * 0.2)
            camera.SetViewUp(0, 0, 1)
            camera.SetViewAngle(15.0)
            self.renderer.ResetCameraClippingRange()
            self.vtk_widget.GetRenderWindow().Render()
        except Exception as e:
            print(f"Error in full cloud focus: {e}")

    def _focus_camera_to_bbox(self, min_pt, max_pt):
        """Position the camera to frame the given axis-aligned bbox (min_pt, max_pt)."""
        try:
            center = [(min_pt[0] + max_pt[0]) / 2.0,
                      (min_pt[1] + max_pt[1]) / 2.0,
                      (min_pt[2] + max_pt[2]) / 2.0]

            size_x = max_pt[0] - min_pt[0]
            size_y = max_pt[1] - min_pt[1]
            size_z = max_pt[2] - min_pt[2]
            max_dim = max(size_x, size_y, size_z, 1.0)

            # offset distance: scale with bbox size, but stay closer for stronger zoom
            offset = max_dim * 1.15

            camera = self.renderer.GetActiveCamera()
            camera.SetFocalPoint(*center)
            # position camera obliquely: offset along X and above Z
            camera.SetPosition(center[0] + offset, center[1], center[2] + offset * 0.25)
            camera.SetViewUp(0, 0, 1)
            try:
                camera.SetViewAngle(12.0)
            except Exception:
                pass
            self.renderer.ResetCameraClippingRange()
            if hasattr(self, 'vtk_widget') and self.vtk_widget:
                self.vtk_widget.GetRenderWindow().Render()
        except Exception as e:
            print(f"Error in _focus_camera_to_bbox: {e}")

