    def update_camera_view(self, slider_value):
        """Update camera to track the current slider marker (red sphere).
        If a view mode (TOP / LEFT / Right) is locked via the view buttons, that
        orientation is preserved while the focal point follows the slider marker.
        Only in FREE mode does the camera switch to the default perpendicular side view.
        # ======= Aniket Fixed on 08-05-2026: respect _active_view_mode =======
        """
        if not self.zero_line_set or not self.point_cloud:
            self.focus_camera_on_full_cloud()
            return

        try:
            # ── Calculate marker world position along the zero line ──────────────
            max_slider = self.volume_slider.maximum() if hasattr(self, 'volume_slider') else 100
            if max_slider <= 0:
                max_slider = 100

            fraction  = slider_value / max_slider
            dir_vec   = self.zero_end_point - self.zero_start_point
            unit_dir  = dir_vec / np.linalg.norm(dir_vec)
            pos_along = self.zero_start_point + fraction * dir_vec
            marker_pos = np.array([pos_along[0], pos_along[1], self.zero_start_z])

            # Place / move the red sphere marker
            self.add_or_update_slider_marker(marker_pos)

            # ── Decide which camera orientation to apply ──────────────────────────
            # _active_view_mode is set by on_view_top/left/right_clicked in application_ui.py
            # Values: 'free' (default) | 'top' | 'left' | 'right'
            view_mode = getattr(self, '_active_view_mode', 'free')

            camera          = self.renderer.GetActiveCamera()
            camera_distance = max(self.total_distance * 0.6, 30.0)

            if view_mode == 'top':
                # ── TOP view: camera directly above the marker, looking straight down ──
                camera.SetFocalPoint(marker_pos[0], marker_pos[1], marker_pos[2])
                camera.SetPosition(marker_pos[0], marker_pos[1], marker_pos[2] + camera_distance)
                camera.SetViewUp(0.0, 1.0, 0.0)
                camera.SetViewAngle(10.0)

            elif view_mode == 'left':
                # ── LEFT view: camera offset to the left along the perpendicular (−X world) ──
                zero_horizontal = np.array([unit_dir[0], unit_dir[1], 0.0])
                h_len = np.linalg.norm(zero_horizontal)
                if h_len < 1e-6:
                    perp = np.array([0.0, -1.0, 0.0])
                else:
                    # Perpendicular rotated 90° counter-clockwise → left of travel direction
                    perp = np.array([zero_horizontal[1], -zero_horizontal[0], 0.0]) / h_len
                camera_pos = marker_pos + perp * camera_distance
                camera.SetFocalPoint(marker_pos[0], marker_pos[1], marker_pos[2])
                camera.SetPosition(camera_pos[0], camera_pos[1], camera_pos[2])
                camera.SetViewUp(0.0, 0.0, 1.0)
                camera.SetViewAngle(10.0)

            elif view_mode == 'right':
                # ── RIGHT view: camera offset to the right along the perpendicular (+X world) ──
                zero_horizontal = np.array([unit_dir[0], unit_dir[1], 0.0])
                h_len = np.linalg.norm(zero_horizontal)
                if h_len < 1e-6:
                    perp = np.array([0.0, 1.0, 0.0])
                else:
                    # Perpendicular rotated 90° clockwise → right of travel direction
                    perp = np.array([-zero_horizontal[1], zero_horizontal[0], 0.0]) / h_len
                camera_pos = marker_pos + perp * camera_distance
                camera.SetFocalPoint(marker_pos[0], marker_pos[1], marker_pos[2])
                camera.SetPosition(camera_pos[0], camera_pos[1], camera_pos[2])
                camera.SetViewUp(0.0, 0.0, 1.0)
                camera.SetViewAngle(10.0)

            else:
                # ── FREE mode (default): original perpendicular side view behaviour ──
                elevation_offset = camera_distance * 0.2
                zero_horizontal  = np.array([unit_dir[0], unit_dir[1], 0.0])
                h_len = np.linalg.norm(zero_horizontal)
                if h_len < 1e-6:
                    perp = np.array([0.0, 1.0, 0.0])
                else:
                    perp = np.array([-zero_horizontal[1], zero_horizontal[0], 0.0]) / h_len
                camera_pos    = marker_pos + perp * camera_distance
                camera_pos[2] += elevation_offset
                camera.SetFocalPoint(marker_pos[0], marker_pos[1], marker_pos[2])
                camera.SetPosition(camera_pos[0], camera_pos[1], camera_pos[2])
                camera.SetViewUp(0.0, 0.0, 1.0)
                camera.SetViewAngle(10.0)

            self.renderer.ResetCameraClippingRange()
            self.vtk_widget.GetRenderWindow().Render()

        except Exception as e:
            print(f"Error updating camera view: {e}")
            self.focus_camera_on_full_cloud()

