    def open_zero_line_dialog(self, auto_opened=False):
        """
        Open Zero Line Configuration Dialog â€” called manually or automatically.
        Stores exactly what the user entered in the dialog.
        """
        # Pass current values if already set (for editing existing zero line)
        p1 = self.zero_start_point if self.zero_line_set else None
        p2 = self.zero_end_point if self.zero_line_set else None

        km1      = getattr(self, 'zero_start_km',       None)
        km2      = getattr(self, 'zero_end_km',         None)
        interval = getattr(self, 'zero_interval',       20.0)

        dialog = ZeroLineDialog(
            point1   = p1,
            point2   = p2,
            km1      = km1,
            km2      = km2,
            interval = interval,
            parent   = self
        )

        if dialog.exec_() == QDialog.Accepted:
            p1, p2 = dialog.get_points()
            if p1 is None or p2 is None:
                QMessageBox.warning(self, "Invalid Input", "Please enter valid numeric coordinates.")
                if auto_opened:
                    self.zero_line.setChecked(False)
                return

           # ======================================================================
            # VERY IMPORTANT: Get configuration and debug what we actually got
           # ======================================================================
            config = dialog.get_configuration()

            # Debug print (remove later if you want)
            print("DEBUG: Dialog returned configuration:")
            print(f"  km1         = {config.get('km1')}")
            print(f"  chainage1   = {config.get('chainage1')}")
            print(f"  km2         = {config.get('km2')}")
            print(f"  chainage2   = {config.get('chainage2')}")
            print(f"  interval    = {config.get('interval')}")

            # Store EXACTLY what came from the dialog
            self.zero_start_km       = config['km1']
            self.zero_start_chainage = config['chainage1']
            self.zero_end_km         = config['km2']
            self.zero_end_chainage   = config['chainage2']
            self.zero_interval       = config['interval']

            # Store the actual coordinate points (numpy arrays)
            self.zero_start_point = p1
            self.zero_end_point   = p2
            self.zero_start_z     = float(p1[2]) if p1 is not None and len(p1) >= 3 else None
            self.zero_line_set    = True

            # Calculate displayed / used distance from CHAINAGE values (what user sees)
            total_m1 = (self.zero_start_km or 0) * 1000 + (self.zero_start_chainage or 0.0)
            total_m2 = (self.zero_end_km   or 0) * 1000 + (self.zero_end_chainage   or 0.0)
            self.total_distance = total_m2 - total_m1
            self.original_total_distance = self.total_distance

            # Update graph axis and ticks based on chainage distance
            self.update_chainage_ticks()
            self.update_scale_ticks()

            if hasattr(self, 'scale_section'):
                self.scale_section.setVisible(True)

            # Redraw zero line on 2D plot (from 0 to chainage distance)
            if hasattr(self, 'zero_graph_line') and self.zero_graph_line is not None:
                self.zero_graph_line.remove()

            self.zero_graph_line, = self.ax.plot(
                [0, self.total_distance],
                [0, 0],
                color='purple',
                linewidth=3,
                label='Zero Line'
            )
            self.canvas.draw_idle()   # more efficient redraw

            # Refresh 3D view if available
            if hasattr(self, 'vtk_widget') and self.vtk_widget is not None:
                self.vtk_widget.GetRenderWindow().Render()

            # Save to JSON â€” should now use the exact chainage values
            success = self.save_zero_line_config_to_current_layer()
            if success:
                self.message_text.append("Zero line successfully configured and saved to current layer!")
            else:
                self.message_text.append("Warning: Zero line configured but save failed.")

            # Feedback to user â€” show what was actually stored
            feedback = [
                "Zero Line Set Successfully!",
                f"   â€¢ Length (chainage-based): {self.total_distance:.2f} m",
                f"   â€¢ Interval: {self.zero_interval:.1f} m",
            ]
            if self.zero_start_km is not None:
                feedback.append(f"   â€¢ Start: {self.zero_start_km}+{self.zero_start_chainage:06.3f}")
            if self.zero_end_km is not None:
                feedback.append(f"   â€¢ End:   {self.zero_end_km}+{self.zero_end_chainage:06.3f}")

            for line in feedback:
                self.message_text.append(line)
        else:
            # Canceled
            if auto_opened and not self.zero_line_set:
                self.zero_line.setChecked(False)
            self.message_text.append("Zero line configuration canceled.")



