    def start_editing_line(self, ltype):
        """Enter edit mode for a specific line type."""
        if getattr(self, 'edit_mode_active', False):
            self.cancel_editing()

        self.is_edited = True

        # Reset elevation angle for road_surface
        if ltype == 'road_surface':
            self.elevation_angle_active = False
            if hasattr(self, 'elevation_angle_label') and self.elevation_angle_label:
                try: self.elevation_angle_label.remove()
                except: pass
                self.elevation_angle_label = None

        # Ensure artists exist (recreate from polylines if needed)
        if not self.line_types[ltype]['artists'] and self.line_types[ltype]['polylines']:
            color = self.line_types[ltype]['color']
            for poly in self.line_types[ltype]['polylines']:
                xs = [p[0] for p in poly]
                ys = [p[1] for p in poly]
                line, = self.ax.plot(xs, ys, color=color, linewidth=2.5)
                self.line_types[ltype]['artists'].append(line)

        # Store original polylines
        import copy
        if not hasattr(self, 'original_line_data'):
            self.original_line_data = {}
        self.original_line_data[ltype] = copy.deepcopy(self.line_types[ltype]['polylines'])

        # Turn existing line(s) dotted
        for artist in self.line_types[ltype]['artists']:
            artist.set_linestyle('--')

        print(f"Editing {ltype}: {len(self.line_types[ltype]['artists'])} artists turned dotted")

        # Prepare for new drawing
        self.editing_line_type = ltype
        self.edit_mode_active = True
        self.active_line_type = ltype
        self.current_points = []
        self.current_artist = None
        if hasattr(self, 'redo_stack'): self.redo_stack.clear()
        if hasattr(self, 'current_redo_points'): self.current_redo_points.clear()

        if hasattr(self, 'save_button'): self.save_button.setVisible(True)
        if hasattr(self, 'final_save_button'): self.final_save_button.setVisible(True)
        if hasattr(self, 'threed_map_button'): self.threed_map_button.setVisible(True)

        if hasattr(self, 'disable_other_checkboxes'):
            self.disable_other_checkboxes(ltype)

        self.message_text.append(f"Editing {ltype}  click points to draw new line. Use Save when done.")
        self.canvas.draw_idle()

    def cancel_editing(self):
        """Cancel edit mode safely."""
        if not getattr(self, 'edit_mode_active', False):
            return
            
        ltype = self.editing_line_type
        if ltype and ltype in getattr(self, 'original_line_data', {}):
            import copy
            self.line_types[ltype]['polylines'] = copy.deepcopy(self.original_line_data[ltype])
            color = self.line_types[ltype]['color']
            for artist in self.line_types[ltype]['artists']:
                try: artist.remove()
                except: pass
            self.line_types[ltype]['artists'].clear()
            for poly in self.line_types[ltype]['polylines']:
                xs = [p[0] for p in poly]
                ys = [p[1] for p in poly]
                line, = self.ax.plot(xs, ys, color=color, linewidth=2.5)
                self.line_types[ltype]['artists'].append(line)
                
        self.edit_mode_active = False
        self.active_line_type = None
        self.current_points = []
        if getattr(self, 'current_artist', None):
            try: self.current_artist.remove()
            except: pass
            self.current_artist = None
            
        self.message_text.append("Editing cancelled.")
        self.canvas.draw_idle()

    def exit_edit_mode(self, cancel=False):
        """Exit edit mode safely, either by cancelling or preserving changes."""
        if not getattr(self, 'edit_mode_active', False):
            return
            
        if cancel:
            self.cancel_editing()
            return
            
        self.edit_mode_active = False
        self.editing_line_type = None
        self.active_line_type = None
        self.current_points = []
        if getattr(self, 'current_artist', None):
            try: self.current_artist.remove()
            except: pass
            self.current_artist = None
            
        self.message_text.append("Editing finished. Use Save to persist changes.")
        self.canvas.draw_idle()

