    # New/Updated unified handler (add to class)
    def on_graph_click(self, event):
        """Unified mouse click handler for all drawing modes"""
        if event.inaxes != self.ax:
            return

        x, y = event.xdata, event.ydata
        if x is None or y is None:
            return

        if not self.zero_line_set:
            self.message_text.append("Set zero line first before drawing points.")
            return

        if not (0 <= x <= self.total_distance):
            self.message_text.append(f"Click outside chainage range (0-{self.total_distance:.1f}m).")
            return

        # === SNAP TO NEAREST CHAINAGE INTERVAL ===
        # Default to raw click
        final_x, final_y = x, y
        
        # Only snap if zero line is set and we have a valid interval
        if hasattr(self, 'zero_interval') and self.zero_interval > 0:
            # Calculate snapped X
            snapped_x = round(x / self.zero_interval) * self.zero_interval
            
            # Optional: Clamp to range (0 to total_distance)
            if snapped_x < 0: snapped_x = 0
            if snapped_x > self.total_distance: snapped_x = self.total_distance
            
            final_x = snapped_x
            # Y remains unchanged (unless you want to snap Y too, but usually it's just chainage)
            
            # Show snapped feedback
            # self.message_text.append(f"Snapped: {x:.2f} -> {final_x:.2f}")

        if self.active_line_type == 'construction':
            self.on_construction_click(event, override_x=final_x, override_y=final_y)
        elif self.active_line_type == 'material' and self.active_material_index is not None:
            self.on_material_draw_click(event, override_x=final_x, override_y=final_y) 
        else:
            self.message_text.append("No active drawing mode selected.")

