    # Define function for the load baseline from design layer:    
    def _get_single_layer_profile(self, target_name):
        import os
        import json
        selected_display_name = str(target_name).strip()
        if not selected_display_name or selected_display_name.lower() in ("", "none"):
            return None, None
        if not hasattr(self, 'current_construction_layer_path') or not self.current_construction_layer_path:
            return None, None
        
        worksheet_root = os.path.abspath(os.path.join(self.current_construction_layer_path, "..", ".."))
        config_path = os.path.join(self.current_construction_layer_path, "Construction_Layer_config.txt")
        ref_layer_2d = None
        if os.path.exists(config_path):
            try:
                with open(config_path, 'r', encoding='utf-8') as f:
                    ref_layer_2d = json.load(f).get("reference_layer_2d")
            except: pass

        if ref_layer_2d:
            unified_file_path = os.path.join(worksheet_root, "designs", ref_layer_2d, 'design_construction_config.json')
        else:
            unified_file_path = os.path.join(worksheet_root, 'design_construction_config.json')
        
        if not os.path.exists(unified_file_path):
            return None, None

        try:
            with open(unified_file_path, 'r', encoding='utf-8') as f:
                full_data = json.load(f)
            design_data = full_data.get('design', {})
            baseline_mapping = {
                'surface': 'surface_baseline',
                'construction': 'construction_baseline',
                'road surface': 'road_surface_baseline'
            }
            baseline_key = baseline_mapping.get(selected_display_name.lower(), selected_display_name.lower() + '_baseline')
            baseline_data = design_data.get(baseline_key, {})
            
            if not baseline_data:
                mat_cfg_path = os.path.join(self.current_construction_layer_path, 'material_construction_config.json')
                if os.path.exists(mat_cfg_path):
                    try:
                        with open(mat_cfg_path, 'r', encoding='utf-8') as f:
                            mat_full_data = json.load(f)
                        for mat in mat_full_data.get('materials', []):
                            if mat.get('name', '').lower() == selected_display_name.lower() or mat.get('material_line_folder', '').lower() == selected_display_name.lower():
                                all_points = []
                                for seg in mat.get("segments", []):
                                    all_points.extend(seg.get("polyline_points", []))
                                if all_points:
                                    all_points.sort(key=lambda p: p.get("chainage_m", 0))
                                    xs = [p.get("chainage_m") for p in all_points]
                                    ys = [p.get("relative_elevation_m") for p in all_points]
                                    return xs, ys
                    except: pass
                return None, None
            
            polylines = baseline_data.get("polylines", [])
            all_points = []
            for poly in polylines:
                all_points.extend(poly.get("points", []))
            if not all_points:
                return None, None
            all_points.sort(key=lambda p: p.get("chainage_m", 0))
            xs = [p.get("chainage_m") for p in all_points]
            ys = [p.get("relative_elevation_m") for p in all_points]
            return xs, ys
        except Exception as e:
            return None, None

    def _get_design_unified_file_path(self):
        """Return design_construction_config.json path for referenced 2D design layer."""
        if not hasattr(self, 'current_construction_layer_path') or not self.current_construction_layer_path:
            return None

        import os
        import json

        worksheet_root = os.path.abspath(os.path.join(self.current_construction_layer_path, "..", ".."))
        config_path = os.path.join(self.current_construction_layer_path, "Construction_Layer_config.txt")

        ref_layer_2d = None
        if os.path.exists(config_path):
            try:
                with open(config_path, 'r', encoding='utf-8') as f:
                    ref_layer_2d = json.load(f).get("reference_layer_2d")
            except Exception:
                ref_layer_2d = None

        if ref_layer_2d:
            return os.path.join(worksheet_root, "designs", ref_layer_2d, 'design_construction_config.json')
        return os.path.join(worksheet_root, 'design_construction_config.json')

    def _load_design_curve_angle_points(self):
        """Read all saved curve-angle points from design_construction_config.json."""
        import os
        import json

        unified_file_path = self._get_design_unified_file_path()
        if not unified_file_path or not os.path.exists(unified_file_path):
            return []

        try:
            with open(unified_file_path, 'r', encoding='utf-8') as f:
                full_data = json.load(f)
            design_data = full_data.get('design', {})
        except Exception:
            return []

        baseline_keys = ['surface_baseline', 'construction_baseline', 'road_surface_baseline']
        out = {}

        for bkey in baseline_keys:
            bdata = design_data.get(bkey) or {}
            for poly in bdata.get('polylines', []) or []:
                for pt in poly.get('points', []) or []:
                    if 'angle_deg' not in pt:
                        continue
                    ch = float(pt.get('chainage_m', 0.0) or 0.0)
                    ch_key = round(ch, 3)
                    out[ch_key] = {
                        'chainage_m': ch_key,
                        'angle_deg': float(pt.get('angle_deg', 0.0) or 0.0),
                        'inner_curve': bool(pt.get('inner_curve', False)),
                        'outer_curve': bool(pt.get('outer_curve', False)),
                        'source_baseline': bkey
                    }

        return [out[k] for k in sorted(out.keys())]

    def _get_curve_points_for_range(self, from_m, to_m, tolerance=0.25):
        """Return curve-angle points inside a chainage range."""
        try:
            a = float(from_m)
            b = float(to_m)
        except Exception:
            return []

        lo, hi = (a, b) if a <= b else (b, a)
        points = self._load_design_curve_angle_points()
        return [p for p in points if (lo - tolerance) <= p['chainage_m'] <= (hi + tolerance)]

    def _build_curved_path_from_segments(self, material_config, from_ch, to_ch):
        """
        Build curved reference path from material segment data.
        Fallback when unified design file is not available.
        Extracts absolute coordinates from polyline_points in segments.
        """
        import numpy as np

        segments = material_config.get('segments', [])
        if not segments:
            return None

        all_points = []
        for seg in segments:
            seg_from = seg.get('from_chainage_m')
            seg_to = seg.get('to_chainage_m')

            # Skip segments outside requested range
            if seg_to is not None and seg_from is not None:
                if seg_to < from_ch or seg_from > to_ch:
                    continue

            # Extract polyline points with absolute coordinates
            polyline_pts = seg.get('polyline_points', [])
            for pt in polyline_pts:
                ch = pt.get('chainage_m')
                abs_coords = pt.get('absolute_coordinates')
                if ch is not None and abs_coords and len(abs_coords) == 3:
                    all_points.append({
                        'chainage': float(ch),
                        'x': float(abs_coords[0]),
                        'y': float(abs_coords[1]),
                        'z': float(abs_coords[2])
                    })

        if len(all_points) < 2:
            return None

        # Sort by chainage
        all_points_sorted = sorted(all_points, key=lambda p: p['chainage'])

        # Convert to arrays
        chs = np.array([p['chainage'] for p in all_points_sorted])
        xs = np.array([p['x'] for p in all_points_sorted])
        ys = np.array([p['y'] for p in all_points_sorted])
        zs = np.array([p['z'] for p in all_points_sorted])

        return {
            'chainage': chs,
            'x': xs,
            'y': ys,
            'z': zs,
        }

    def _load_reference_absolute_path(self, material_config):
        """Load absolute XYZ path for selected reference baseline from design config."""
        import os
        import json
        import numpy as np

        ref_layer = material_config.get('ref_layer') or material_config.get('reference_baseline') or material_config.get('reference_layer') or 'Construction'
        if isinstance(ref_layer, list):
            ref_layer = ref_layer[0] if ref_layer else 'Construction'

        baseline_mapping = {
            'surface': 'surface_baseline',
            'construction': 'construction_baseline',
            'road surface': 'road_surface_baseline'
        }
        bkey = baseline_mapping.get(str(ref_layer).strip().lower(), str(ref_layer).strip().lower() + '_baseline')

        unified_file_path = self._get_design_unified_file_path()
        if not unified_file_path or not os.path.exists(unified_file_path):
            return None

        try:
            with open(unified_file_path, 'r', encoding='utf-8') as f:
                full_data = json.load(f)

            baseline_data = (full_data.get('design') or {}).get(bkey) or {}
            all_points = []
            for poly in baseline_data.get('polylines', []) or []:
                all_points.extend(poly.get('points', []) or [])

            chs, xs, ys, zs = [], [], [], []
            for pt in all_points:
                ch = pt.get('chainage_m')
                abs_xyz = pt.get('absolute_coordinates')
                if ch is None or not isinstance(abs_xyz, list) or len(abs_xyz) != 3:
                    continue
                chs.append(float(ch))
                xs.append(float(abs_xyz[0]))
                ys.append(float(abs_xyz[1]))
                zs.append(float(abs_xyz[2]))

            if len(chs) < 2:
                return None

            sort_idx = np.argsort(chs)
            return {
                'chainage': np.array(chs, dtype=float)[sort_idx],
                'x': np.array(xs, dtype=float)[sort_idx],
                'y': np.array(ys, dtype=float)[sort_idx],
                'z': np.array(zs, dtype=float)[sort_idx],
            }
        except Exception:
            return None

    def _load_baseline_from_design_layer(self, material_config):
        import numpy as np
        
        def parse_chainage(ch_str):
            ch_str = str(ch_str).strip()
            val = None
            if '+' in ch_str:
                parts = ch_str.split('+')
                if len(parts) == 2:
                    try: val = int(parts[0]) * 1000 + float(parts[1])
                    except: pass
            if val is None:
                try: val = float(ch_str)
                except: return None
            
            # Convert to relative chainage if it's absolute
            start_abs_m = (getattr(self, 'zero_start_km', 0) or 0) * 1000 + (getattr(self, 'zero_start_chainage', 0.0) or 0.0)
            if start_abs_m > 0 and val >= start_abs_m - 1000:
                val = val - start_abs_m
            return val
            
        segments = material_config.get('dialog_segments', material_config.get('segments', []))
        
        # Only do hybrid stitching if multiple segments exist
        if segments and len(segments) > 0:
            profiles = {}
            min_ch = float('inf')
            max_ch = float('-inf')
            valid_segments = []
            
            for seg in segments:
                ref_layer = seg.get('ref_layer', 'Construction')
                from_m = parse_chainage(seg.get('from_chainage'))
                to_m = parse_chainage(seg.get('to_chainage'))
                if from_m is not None and to_m is not None:
                    valid_segments.append({'ref': ref_layer, 'from': from_m, 'to': to_m})
                    min_ch = min(min_ch, from_m)
                    max_ch = max(max_ch, to_m)
                    if ref_layer not in profiles:
                        px, py = self._get_single_layer_profile(ref_layer)
                        if px and py:
                            profiles[ref_layer] = (px, py)
            
            if valid_segments and min_ch < max_ch and len(profiles) > 0:
                # Create a dense sampled baseline across the whole material range
                num_pts = max(100, int((max_ch - min_ch) * 10))
                stitched_xs = np.linspace(min_ch, max_ch, num=num_pts)
                stitched_ys = []
                for x in stitched_xs:
                    # Find which segment this x belongs to
                    active_ref = 'Construction'
                    for seg in valid_segments:
                        if seg['from'] - 0.001 <= x <= seg['to'] + 0.001:
                            active_ref = seg['ref']
                            break
                    
                    if active_ref in profiles:
                        px, py = profiles[active_ref]
                        y = np.interp(x, px, py, left=py[0], right=py[-1])
                    else:
                        px, py = list(profiles.values())[0]
                        y = np.interp(x, px, py, left=py[0], right=py[-1])
                    stitched_ys.append(y)
                
                self.message_text.append(f" Hybrid reference baseline loaded for multiple segments ({len(stitched_xs)} pts)")
                return list(stitched_xs), list(stitched_ys)

        # Fallback to single layer parsing
        ref_layer = material_config.get('ref_layer') or material_config.get('reference_baseline') or material_config.get('reference_layer') or 'Construction'
        if isinstance(ref_layer, list): ref_layer = ref_layer[0] if ref_layer else 'Construction'
        xs, ys = self._get_single_layer_profile(ref_layer)
        if xs and ys:
            self.message_text.append(f" Reference baseline '{ref_layer}' loaded ({len(xs)} points)")
            return xs, ys
        
        self.message_text.append("No valid reference baseline found.")
        return None, None

        
        worksheet_root = os.path.abspath(os.path.join(self.current_construction_layer_path, "..", ".."))

        # Try to read Construction_Layer_config.txt to find reference_layer_2d
        config_path = os.path.join(self.current_construction_layer_path, "Construction_Layer_config.txt")
        ref_layer_2d = None
        if os.path.exists(config_path):
            try:
                with open(config_path, 'r', encoding='utf-8') as f:
                    config_data = json.load(f)
                    ref_layer_2d = config_data.get("reference_layer_2d")
            except Exception:
                pass

        # Load from UNIFIED file in the designs folder
        if ref_layer_2d:
            unified_file_path = os.path.join(worksheet_root, "designs", ref_layer_2d, 'design_construction_config.json')
        else:
            # Fallback (may not exist)
            unified_file_path = os.path.join(worksheet_root, 'design_construction_config.json')
        
        if not os.path.exists(unified_file_path):
            self.message_text.append(f"Unified config not found: {unified_file_path}")
            return None, None

        try:
            with open(unified_file_path, 'r', encoding='utf-8') as f:
                full_data = json.load(f)
            
            design_data = full_data.get('design', {})
            
            # Map display names to keys in unified file
            baseline_mapping = {
                'surface': 'surface_baseline',
                'construction': 'construction_baseline',
                'road surface': 'road_surface_baseline'
            }
            
            baseline_key = baseline_mapping.get(selected_display_name.lower(), selected_display_name.lower() + '_baseline')
            baseline_data = design_data.get(baseline_key, {})
            
            if not baseline_data:
                # IT MIGHT BE A MATERIAL!
                mat_cfg_path = os.path.join(self.current_construction_layer_path, 'material_construction_config.json')
                if os.path.exists(mat_cfg_path):
                    try:
                        with open(mat_cfg_path, 'r', encoding='utf-8') as f:
                            mat_full_data = json.load(f)
                        for mat in mat_full_data.get('materials', []):
                            if mat.get('name', '').lower() == selected_display_name.lower() or mat.get('material_line_folder', '').lower() == selected_display_name.lower():
                                all_points = []
                                for seg in mat.get("segments", []):
                                    all_points.extend(seg.get("polyline_points", []))
                                if all_points:
                                    all_points.sort(key=lambda p: p.get("chainage_m", 0))
                                    xs = [p.get("chainage_m") for p in all_points]
                                    ys = [p.get("relative_elevation_m") for p in all_points]
                                    self.message_text.append(f" Reference material '{selected_display_name}' loaded ({len(xs)} points)")
                                    return xs, ys
                    except Exception as e:
                        pass
                
                self.message_text.append(f"Baseline '{selected_display_name}' not found in unified config or materials.")
                return None, None
            
            # Extract points from baseline
            polylines = baseline_data.get("polylines", [])
            all_points = []
            for poly in polylines:
                all_points.extend(poly.get("points", []))
            
            if not all_points:
                self.message_text.append(f"No points in baseline '{selected_display_name}'.")
                return None, None
            
            # Sort by chainage
            all_points.sort(key=lambda p: p.get("chainage_m", 0))
            
            xs = [p.get("chainage_m") for p in all_points]
            ys = [p.get("relative_elevation_m") for p in all_points]
            
            self.message_text.append(f" Reference baseline '{selected_display_name}' loaded ({len(xs)} points)")
            return xs, ys
            
        except Exception as e:
            self.message_text.append(f"Error loading baseline: {str(e)}")
            return None, None

        try:
            with open(baseline_path, 'r', encoding='utf-8') as f:
                data = json.load(f)

            # Extract points  supports both new and old baseline formats
            all_points = []
            if "polylines" in data and data["polylines"]:
                for poly in data["polylines"]:
                    if "points" in poly:
                        all_points.extend(poly["points"])
            elif "points" in data:
                all_points = data["points"]

            if len(all_points) < 2:
                self.message_text.append(f"Baseline has insufficient points ({len(all_points)}).")
                return None, None

            xs = [pt.get("chainage_m", pt[0] if isinstance(pt, list) else 0) for pt in all_points]
            ys = [pt.get("relative_elevation_m", pt[1] if isinstance(pt, list) else 0) for pt in all_points]

            self.message_text.append(
                f"Baseline loaded: '{selected_display_name}' ({len(xs)} points)"
            )
            return xs, ys

        except Exception as e:
            self.message_text.append(f"Error reading baseline JSON: {str(e)}")
            return None, None

