    def _get_curved_reference_path(self, ref_layer='construction'):
        """FINAL PERFECT VERSION - Exactly matches Deck Slab / Road Surface curve logic"""
        import numpy as np

        self.message_text.append(f" Building curved path for: {ref_layer}")

        # Robust baseline loading (works in both Design and Construction mode)
        try:
            ref_xs, ref_ys = self._load_baseline_from_design_layer({'ref_layer': ref_layer})
            if not ref_xs or len(ref_xs) < 3:
                self.message_text.append(f"  {ref_layer} has too few points  straight fallback")
                return self._straight_fallback()
            self.message_text.append(f" {ref_layer} baseline loaded ({len(ref_xs)} points)")
        except Exception as e:
            self.message_text.append(f"  Failed to load {ref_layer}: {e}")
            return self._straight_fallback()

        # Curve lookup
        curve_lookup = {}
        for item in self.curve_labels:
            ch = float(item['chainage'])
            cfg = item['config']
            curve_lookup[ch] = {
                'angle': float(cfg['angle']),
                'left_turn': bool(cfg.get('inner_curve', True))
            }

        # === GLOBAL CURVED PATH GENERATION (This is what makes green planes curve) ===
        start_pt = np.array(self.zero_start_point, dtype=float)
        current_pos = start_pt.copy()
        current_dir = np.array(self.zero_end_point) - start_pt
        if np.linalg.norm(current_dir) > 0:
            current_dir /= np.linalg.norm(current_dir)

        all_ch, all_x, all_y, all_z = [], [], [], []
        sample_step = 0.5
        applied_curves = set()

        for ch in np.arange(0.0, self.total_distance + sample_step, sample_step):
            # === APPLY CURVE ROTATION WHEN WE REACH CURVE CHAINAGE ===
            for c_ch in sorted(curve_lookup.keys()):
                if c_ch not in applied_curves and abs(ch - c_ch) <= sample_step:
                    applied_curves.add(c_ch)
                    cfg = curve_lookup[c_ch]
                    angle_rad = np.deg2rad(cfg['angle'])
                    if not cfg['left_turn']:
                        angle_rad = -angle_rad
                    rot = np.array([[np.cos(angle_rad), -np.sin(angle_rad), 0],
                                    [np.sin(angle_rad),  np.cos(angle_rad), 0],
                                    [0, 0, 1]])
                    current_dir = rot @ current_dir
                    norm = np.linalg.norm(current_dir)
                    if norm > 0:
                        current_dir /= norm
                    self.message_text.append(f"ðŸ”„ Applied {cfg['angle']}° curve at {ch:.1f}m")

            # Advance position
            if len(all_ch) > 0:
                current_pos += current_dir * sample_step

            # Get elevation from reference baseline
            rel_z = np.interp(ch, ref_xs, ref_ys, left=ref_ys[0], right=ref_ys[-1])
            abs_z = (getattr(self, 'zero_start_z', self.zero_start_point[2])) + rel_z

            all_ch.append(ch)
            all_x.append(current_pos[0])
            all_y.append(current_pos[1])
            all_z.append(abs_z)

        self.message_text.append(f" SUCCESS: Curved path created with {len(all_ch)} points")
        return {
            'chainage': np.array(all_ch),
            'x': np.array(all_x),
            'y': np.array(all_y),
            'z': np.array(all_z)
        }

    def _straight_fallback(self):
        """Simple straight fallback"""
        import numpy as np
        chs = np.linspace(0, self.total_distance, 300)
        xs = np.zeros_like(chs, dtype=float)
        ys = np.zeros_like(chs, dtype=float)
        zs = np.full_like(chs, self.zero_start_point[2])
        for i, ch in enumerate(chs):
            X, Y, Z = self.get_real_coordinates_from_chainage(ch)
            if X is None:
                X, Y, Z = self.interpolate_xyz(ch)
            xs[i], ys[i], zs[i] = X, Y, Z
        return {'chainage': chs, 'x': xs, 'y': ys, 'z': zs}
