    def _hex_to_rgb(self, hex_color):
        """Convert hex color to RGB (0.0-1.0)"""
        hex_color = hex_color.lstrip('#')
        return tuple(int(hex_color[i:i+2], 16) / 255.0 for i in (0, 2, 4))

    @staticmethod
    def _normalize_material_key(value):
        return str(value).strip().lower() if value is not None else ""

    def _material_match_candidates(self, material_config=None, material_item=None, fallback_name=None):
        candidates = []

        def add(value):
            normalized = self._normalize_material_key(value)
            if normalized and normalized not in candidates:
                candidates.append(normalized)

        if material_item:
            add(material_item.get('folder'))
            add(material_item.get('name'))
            add(material_item.get('label'))
            item_data = material_item.get('data', {}) if isinstance(material_item.get('data', {}), dict) else {}
            add(item_data.get('folder_name'))
            add(item_data.get('name'))

        if isinstance(material_config, dict):
            for key in (
                'folder_name',
                'name',
                'material_line_name',
                'material_line_folder',
                'material_line_id',
                'material_line',
                'reference_baseline',
                'ref_layer',
                'reference_layer',
            ):
                add(material_config.get(key))

        add(fallback_name)
        return candidates

    def _find_material_record(self, materials, candidates):
        if not isinstance(materials, list):
            return None

        candidate_set = {self._normalize_material_key(candidate) for candidate in candidates if self._normalize_material_key(candidate)}
        if not candidate_set:
            return None

        for material in materials:
            if not isinstance(material, dict):
                continue
            material_values = [
                self._normalize_material_key(material.get('material_line_folder')),
                self._normalize_material_key(material.get('material_line_name')),
                self._normalize_material_key(material.get('material_line_id')),
                self._normalize_material_key(material.get('folder_name')),
                self._normalize_material_key(material.get('name')),
            ]
            if any(value in candidate_set for value in material_values if value):
                return material

        return None

