    def resizeEvent(self, event):
        """Handle window resize to adjust menu panel position"""
        super(PointCloudViewer, self).resizeEvent(event)
        
        # If menu is visible, reposition it correctly below the top toolbar
        if hasattr(self, 'menu_panel') and self.menu_panel.isVisible():
            content_rect = self.content_widget.geometry()
            panel_width  = self.menu_panel.width()
            top_y        = self._menu_panel_top_y()
            panel_height = content_rect.height() - top_y

            # Position menu at right edge of content widget, below toolbar
            self.menu_panel.setGeometry(
                content_rect.right() - panel_width,
                top_y,
                panel_width,
                panel_height
            )
            
        if hasattr(self, 'play_simulation_btn') and self.play_simulation_btn.isVisible():
            self._update_floating_button_position()
            
        if self.vtk_widget:
            self.vtk_widget.GetRenderWindow().Render()

    def _update_floating_button_position(self):
        if hasattr(self, 'play_simulation_btn') and hasattr(self, 'content_widget'):
            btn_w = self.play_simulation_btn.width()
            btn_h = self.play_simulation_btn.height()
            
            # Position it at the bottom right corner of the window
            cw = self.centralWidget()
            if cw:
                cw_rect = cw.geometry()
                x_pos = cw_rect.width() - btn_w - 30 # 30px offset from the right
                y_pos = cw_rect.height() - btn_h - 30 # 30px offset from the bottom
                self.play_simulation_btn.move(x_pos, y_pos)
                self.play_simulation_btn.raise_() # Bring to front

