    def restore_interactor_events(self):
        """Restore VTK interactor events after they were disabled."""
        if hasattr(self, 'vtk_widget') and self.vtk_widget:
            interactor = self.vtk_widget.GetRenderWindow().GetInteractor()
            if not interactor:
                return
            
            if not hasattr(self, '_left_click_observer'):
                self._left_click_observer = interactor.AddObserver(
                    "LeftButtonPressEvent", self.on_click
                )

            interactor.SetInteractorStyle(vtk.vtkInteractorStyleTrackballCamera())
                
            # Force interactor to reset its state
            interactor.ReInitialize()

