    def extract_and_show_tunnel_cut(self):
        """Extract points within marked polygon, remove them from main cloud, and show in a new window."""
        polygon_to_use = None

        if hasattr(self, 'measurement_points') and len(self.measurement_points) >= 3:
            polygon_to_use = self.measurement_points
        else:
            # Check if saved in design layer
            if hasattr(self, 'current_worksheet_name') and self.current_worksheet_name and \
               hasattr(self, 'current_layer_name') and self.current_layer_name:
                layer_folder = os.path.join(
                    self.WORKSHEETS_BASE_DIR,
                    self.current_worksheet_name,
                    "designs",
                    self.current_layer_name
                )
                if os.path.exists(layer_folder):
                    try:
                        from json_manager import DesignConstructionManager
                        saved_points = DesignConstructionManager.get_design_polygon_points(layer_folder)
                        if saved_points and len(saved_points) >= 3:
                            import numpy as np
                            polygon_to_use = [np.array(p) for p in saved_points]
                    except Exception as e:
                        print(f"Error loading polygon points: {e}")

        if not polygon_to_use or len(polygon_to_use) < 3:
            if hasattr(self, 'output_list'):
                self.output_list.addItem("Please mark a polygon first or load a layer with a saved polygon.")
            return
            
        if not hasattr(self, 'point_cloud') or self.point_cloud is None:
            if hasattr(self, 'output_list'):
                self.output_list.addItem("No point cloud data to cut.")
            return
            
        try:
            import numpy as np
            import open3d as o3d
            import matplotlib.path
            
            # Get all points and colors from the point cloud
            points = np.asarray(self.point_cloud.points)
            colors = np.asarray(self.point_cloud.colors) if self.point_cloud.has_colors() else None
            
            # Create a polygon path from polygon_to_use (projected to XY plane)
            # matplotlib path implicitly closes the polygon
            polygon_path = matplotlib.path.Path([(p[0], p[1]) for p in polygon_to_use])
            
            # Find points inside the polygon
            inside = polygon_path.contains_points(points[:, :2])
            
            if not np.any(inside):
                if hasattr(self, 'output_list'):
                    self.output_list.addItem("No points found inside the marked polygon.")
                return
            
            # 1. Create cropped cloud (the part that is cut out)
            self.cropped_cloud = o3d.geometry.PointCloud()
            self.cropped_cloud.points = o3d.utility.Vector3dVector(points[inside])
            if colors is not None:
                self.cropped_cloud.colors = o3d.utility.Vector3dVector(colors[inside])
                
            # 2. Update the main point cloud to remove the cut part
            outside_points = points[~inside]
            new_cloud = o3d.geometry.PointCloud()
            new_cloud.points = o3d.utility.Vector3dVector(outside_points)
            if colors is not None:
                outside_colors = colors[~inside]
                new_cloud.colors = o3d.utility.Vector3dVector(outside_colors)
                
            self.point_cloud = new_cloud
            
            # Redraw the main point cloud
            if hasattr(self, 'display_point_cloud'):
                self.display_point_cloud()
                
            # 3. Display the cut part in a new window
            if hasattr(self, 'display_cropped_cloud'):
                self.display_cropped_cloud()
                
            # Clear the measurement polygon without calling reset_action (which would close the new window)
            if hasattr(self, 'measurement_actors'):
                for actor in list(self.measurement_actors):
                    if not hasattr(self, 'baseline_actors') or actor not in self.baseline_actors:
                        self.renderer.RemoveActor(actor)
                        self.measurement_actors.remove(actor)
            self.measurement_points = []
            
            interactor = self.vtk_widget.GetRenderWindow().GetInteractor()
            interactor.SetInteractorStyle(o3d.visualization.rendering.MaterialRecord() if False else __import__('vtk').vtkInteractorStyleTrackballCamera())
            
            if hasattr(self, 'output_list'):
                self.output_list.addItem(f"Tunnel cut surface - extracted {np.sum(inside)} points")
            
        except Exception as e:
            if hasattr(self, 'output_list'):
                self.output_list.addItem(f"Error cutting area: {str(e)}")
            from PyQt5.QtWidgets import QMessageBox
            QMessageBox.critical(self, "Cut Error", f"An error occurred while cutting the surface:\n{str(e)}")     

