    def undo_last_tunnel_light(self):
        """Undo the most recently placed tunnel light (LIFO)."""
        if not hasattr(self, 'tunnel_light_groups') or not self.tunnel_light_groups:
            return False
            
        last_group = self.tunnel_light_groups.pop()
        
        # Remove actors
        for actor in last_group.get('actors', []):
            if actor:
                self.renderer.RemoveActor(actor)
                if hasattr(self, 'tunnel_light_actors') and actor in self.tunnel_light_actors:
                    self.tunnel_light_actors.remove(actor)
                    
        # Remove vtk lights (if any)
        for vtk_light in last_group.get('lights', []):
            if vtk_light:
                self.renderer.RemoveLight(vtk_light)
                if hasattr(self, 'tunnel_light_vtk_lights') and vtk_light in self.tunnel_light_vtk_lights:
                    self.tunnel_light_vtk_lights.remove(vtk_light)
                    
        self.vtk_widget.GetRenderWindow().Render()
        
        if hasattr(self, 'output_list'):
            self.output_list.addItem("↩️ Undo: Removed last placed Tunnel Light.")
         #### Mayur Wakhare 3-7-2026 Tunnel light json   
        self._sync_tunnel_lights_to_json()
        ############################################################
        return True

    def undo_last_multiple_tunnel_light(self):
        """Undo the most recently placed tunnel light from the current Multiple Lights batch (LIFO)."""
        if not hasattr(self, 'multiple_tunnel_light_batches') or not self.multiple_tunnel_light_batches:
            return False
            
        last_batch = self.multiple_tunnel_light_batches[-1]
        if not last_batch:
            self.multiple_tunnel_light_batches.pop()
            return False
            
        last_group = last_batch.pop()
        
        # Remove actors
        for actor in last_group.get('actors', []):
            if actor:
                self.renderer.RemoveActor(actor)
                if hasattr(self, 'tunnel_light_actors') and actor in self.tunnel_light_actors:
                    self.tunnel_light_actors.remove(actor)
                    
        # Remove vtk lights (if any)
        for vtk_light in last_group.get('lights', []):
            if vtk_light:
                self.renderer.RemoveLight(vtk_light)
                if hasattr(self, 'tunnel_light_vtk_lights') and vtk_light in self.tunnel_light_vtk_lights:
                    self.tunnel_light_vtk_lights.remove(vtk_light)
                    
        if not last_batch:
            self.multiple_tunnel_light_batches.pop()
            
        self.vtk_widget.GetRenderWindow().Render()
        
        if hasattr(self, 'output_list'):
            self.output_list.addItem("↩️ Undo Once: Removed 1 Multiple Tunnel Light.")
         ### Mayur Wakhare 3-7-2026 Tunnel light json   
        self._sync_tunnel_lights_to_json()
        ####################################################
        return True

    def undo_all_multiple_tunnel_lights(self):
        """Undo ALL tunnel lights placed during the most recent Multiple Lights operation."""
        if not hasattr(self, 'multiple_tunnel_light_batches') or not self.multiple_tunnel_light_batches:
            return False
            
        last_batch = self.multiple_tunnel_light_batches.pop()
        count = len(last_batch)
        
        for group in reversed(last_batch):
            # Remove actors
            for actor in group.get('actors', []):
                if actor:
                    self.renderer.RemoveActor(actor)
                    if hasattr(self, 'tunnel_light_actors') and actor in self.tunnel_light_actors:
                        self.tunnel_light_actors.remove(actor)
                        
            # Remove vtk lights (if any)
            for vtk_light in group.get('lights', []):
                if vtk_light:
                    self.renderer.RemoveLight(vtk_light)
                    if hasattr(self, 'tunnel_light_vtk_lights') and vtk_light in self.tunnel_light_vtk_lights:
                        self.tunnel_light_vtk_lights.remove(vtk_light)
                        
        self.vtk_widget.GetRenderWindow().Render()
        
        if hasattr(self, 'output_list'):
            self.output_list.addItem(f"↩️ Undo All: Removed {count} Multiple Tunnel Lights.")
          ### Mayur Wakhare 3-7-2026 Tunnel light json  
        self._sync_tunnel_lights_to_json()
        ############################################################
        return True

