    def _create_fire_extinguisher_actor(self, pos, normal, dir_vec):
        import vtk
        import numpy as np
        
        append_filter = vtk.vtkAppendPolyData()
        
        def add_part(source, color, tx, ty, tz, rx=0, ry=0, rz=0):
            source.Update()
            polydata = vtk.vtkPolyData()
            polydata.DeepCopy(source.GetOutput())
            
            colors = vtk.vtkUnsignedCharArray()
            colors.SetNumberOfComponents(3)
            colors.SetName("Colors")
            num_points = polydata.GetNumberOfPoints()
            r, g, b = color
            for _ in range(num_points):
                colors.InsertNextTuple3(int(r*255), int(g*255), int(b*255))
            polydata.GetPointData().SetScalars(colors)
            
            transform = vtk.vtkTransform()
            transform.PostMultiply()
            if rx: transform.RotateX(rx)
            if ry: transform.RotateY(ry)
            if rz: transform.RotateZ(rz)
            transform.Translate(tx, ty, tz)
            
            transformFilter = vtk.vtkTransformPolyDataFilter()
            transformFilter.SetInputData(polydata)
            transformFilter.SetTransform(transform)
            transformFilter.Update()
            
            append_filter.AddInputData(transformFilter.GetOutput())

        # Colors (RGB)
        RED = (0.85, 0.1, 0.1)
        SILVER = (0.7, 0.7, 0.75)
        BLACK = (0.1, 0.1, 0.1)
        YELLOW = (0.9, 0.8, 0.1)
        DARK = (0.2, 0.2, 0.2)

        # 1. Main Body (Red Cylinder)
        body = vtk.vtkCylinderSource()
        body.SetRadius(0.1)
        body.SetHeight(0.6)
        body.SetResolution(30)
        add_part(body, RED, 0, 0, 0.3, rx=90)

        # 2. Top Dome (Red Sphere)
        top = vtk.vtkSphereSource()
        top.SetRadius(0.1)
        top.SetThetaResolution(20)
        top.SetPhiResolution(20)
        add_part(top, RED, 0, 0, 0.6)

        # 3. Bottom Base (Red Sphere)
        bot = vtk.vtkSphereSource()
        bot.SetRadius(0.1)
        bot.SetThetaResolution(20)
        bot.SetPhiResolution(20)
        add_part(bot, RED, 0, 0, 0.0)

        # 4. Label (Thin Cylinder)
        label = vtk.vtkCylinderSource()
        label.SetRadius(0.102)
        label.SetHeight(0.25)
        label.SetResolution(30)
        add_part(label, YELLOW, 0, 0, 0.3, rx=90)

        # 5. Valve/Neck (Silver Cylinder)
        neck = vtk.vtkCylinderSource()
        neck.SetRadius(0.03)
        neck.SetHeight(0.08)
        neck.SetResolution(20)
        add_part(neck, SILVER, 0, 0, 0.7, rx=90)

        # 6. Lever / Handle (Black Box)
        lever = vtk.vtkCubeSource()
        lever.SetXLength(0.02)
        lever.SetYLength(0.15)
        lever.SetZLength(0.02)
        add_part(lever, BLACK, 0, 0.05, 0.74)

        # 7. Pressure Gauge (Silver Cylinder)
        gauge = vtk.vtkCylinderSource()
        gauge.SetRadius(0.02)
        gauge.SetHeight(0.02)
        gauge.SetResolution(20)
        add_part(gauge, SILVER, 0.04, 0, 0.7, rz=90)

        # 8. Hose (Black Cylinder)
        hose = vtk.vtkCylinderSource()
        hose.SetRadius(0.015)
        hose.SetHeight(0.55)
        hose.SetResolution(10)
        add_part(hose, BLACK, -0.115, 0, 0.3, rx=90)

        # 9. Wall Bracket (Dark Box)
        bracket = vtk.vtkCubeSource()
        bracket.SetXLength(0.05)
        bracket.SetYLength(0.08)
        bracket.SetZLength(0.15)
        add_part(bracket, DARK, 0, -0.12, 0.4)

        append_filter.Update()

        # Global Transformation
        Z = np.array([0.0, 0.0, 1.0])
        Y = normal
        Y = Y - np.dot(Y, Z) * Z
        if np.linalg.norm(Y) > 1e-6:
            Y = Y / np.linalg.norm(Y)
        else:
            Y = np.array([0.0, 1.0, 0.0])
        X = np.cross(Y, Z)
        
        mat = vtk.vtkMatrix4x4()
        for i in range(3):
            mat.SetElement(i, 0, X[i])
            mat.SetElement(i, 1, Y[i])
            mat.SetElement(i, 2, Z[i])
            
        final_transform = vtk.vtkTransform()
        final_transform.PostMultiply()
        final_transform.Scale(1.5, 1.5, 1.5)
        final_transform.Concatenate(mat)
        final_transform.Translate(pos[0], pos[1], pos[2])
        
        transformFilter = vtk.vtkTransformPolyDataFilter()
        transformFilter.SetInputData(append_filter.GetOutput())
        transformFilter.SetTransform(final_transform)
        transformFilter.Update()
        
        mapper = vtk.vtkPolyDataMapper()
        mapper.SetInputConnection(transformFilter.GetOutputPort())
        # Disable lighting calculation on colors or ensure scalars are mapped directly
        mapper.SetScalarModeToUsePointData()
        
        actor = vtk.vtkActor()
        actor.SetMapper(mapper)
        
        return actor
