    def open_tunnel_config_dialog(self):
        """Open the tunnel configuration dialog."""
        layer_folder = getattr(self, 'current_design_layer_path', None)
        if not layer_folder or not os.path.exists(layer_folder):
            from PyQt5.QtWidgets import QMessageBox
            QMessageBox.warning(self, "No Design Layer", "Please load a design layer first.")
            return

        dialog = TunnelConfigDialog(self)
        
        # Pre-fill if there is already a saved tunnel in the design layer
        from json_manager import DesignConstructionManager
        master_data = DesignConstructionManager.load_master(layer_folder)
        tunnel_saved = master_data.get("design", {}).get("tunnel")
        if tunnel_saved:
            dialog.start_km.setText(str(tunnel_saved.get("start_km", "")))
            dialog.start_ch.setText(str(tunnel_saved.get("start_chainage", "")))
            dialog.end_km.setText(str(tunnel_saved.get("end_km", "")))
            dialog.end_ch.setText(str(tunnel_saved.get("end_chainage", "")))
            dialog.thickness.setText(str(tunnel_saved.get("wall_thickness", "0.5")))
            dialog.set_arc_points([np.array(pt) for pt in tunnel_saved.get("arc_points", [])])
            
            # Preserve existing ID if it exists
            existing_id = tunnel_saved.get("tunnel_id") or tunnel_saved.get("id")
            if existing_id:
                dialog.tunnel_id = existing_id

        else:
            # Default to the entire road surface baseline length
            pts_3d = self.get_road_baseline_points_3d()
            if pts_3d:
                min_ch = min(p[0] for p in pts_3d)
                max_ch = max(p[0] for p in pts_3d)
                dialog.start_km.setText(str(int(min_ch // 1000)))
                dialog.start_ch.setText(f"{(min_ch % 1000):.3f}")
                dialog.end_km.setText(str(int(max_ch // 1000)))
                dialog.end_ch.setText(f"{(max_ch % 1000):.3f}")

        self.active_tunnel_dialog = dialog
        dialog.setModal(True)

        def on_accepted():
            tunnel_data = dialog.get_data()
            
            # Save to unified config file
            master_data = DesignConstructionManager.load_master(layer_folder)
            if "design" not in master_data:
                master_data["design"] = {}
            master_data["design"]["tunnel"] = tunnel_data
            DesignConstructionManager.save_master(layer_folder, master_data)
            
            if hasattr(self, 'output_list'):
                self.output_list.addItem("Tunnel configuration saved to design layer successfully.")
            
            # Draw the 3D hollow pipe
            self.draw_tunnel_actor(tunnel_data)

        dialog.accepted.connect(on_accepted)
        dialog.show()

    def open_tunnel_arc_marking_directly(self):
        """Allow starting ARC marking directly from the menu."""
        self.start_arc_marking(None)
        
    def start_arc_marking(self, dialog=None):
        """Activate the arc points marking on the point cloud."""
        self.current_measurement = 'tunnel_arc'
        self.measurement_active = True
        self.tunnel_arc_points = []
        
        # Remove previous temp actors if any
        if hasattr(self, 'temp_tunnel_arc_actors'):
            for actor in self.temp_tunnel_arc_actors:
                self.renderer.RemoveActor(actor)
            self.temp_tunnel_arc_actors.clear()
        else:
            self.temp_tunnel_arc_actors = []
            
        self.active_tunnel_dialog = dialog
        self.message_text.append("ℹ️ ARC Marking Mode: Click 3 points on the point cloud to define the tunnel arch.")
        if hasattr(self, 'output_list'):
            self.output_list.addItem("ARC Marking Mode: Click 3 points on the point cloud.")
        self.vtk_widget.GetRenderWindow().Render()

    def get_road_baseline_points_3d(self, target_layer=None):
        """Loads and returns sorted list of (chainage, X, Y, Z) points from road_surface_baseline in design layer."""
        layer_folder = target_layer or getattr(self, 'current_design_layer_path', None)
        if not layer_folder or not os.path.exists(layer_folder):
            return []
        try:
            from json_manager import DesignConstructionManager
            j = DesignConstructionManager.load_baseline_from_unified(layer_folder, 'road_surface_baseline')
            if not j:
                j = DesignConstructionManager.load_baseline_from_unified(layer_folder, 'surface_baseline')
            if not j:
                return []
                
            global_start_offset = self._get_global_start_offset(layer_folder)
            pts_3d = []
            for poly in j.get("polylines", []):
                for pt in poly.get("points", []):
                    ch = pt.get("chainage_m")
                    if ch is None:
                        continue
                    coords = pt.get("world_coordinates") or pt.get("absolute_coordinates") or []
                    if len(coords) >= 3:
                        pts_3d.append((float(ch) + global_start_offset, float(coords[0]), float(coords[1]), float(coords[2])))
            pts_3d.sort(key=lambda x: x[0])
            return pts_3d
        except Exception as e:
            print(f"Error loading 3D baseline points: {e}")
            return []
