    def get_curve_aware_path(self, start_ch, end_ch, step=0.5, target_layer=None):
        """Calculates a list of (ch, pos_xyz, perp, dir_vec) samples from start_ch to end_ch
        by directly sub-sampling from curved_path_samples which already contain
        the accurate curve-rotated positions and perpendicular vectors from the road
        surface baseline.
        """
        import numpy as np

        # ------------------------------------------------------------------
        # PRIMARY PATH: use curved_path_samples (curve-accurate)
        # ------------------------------------------------------------------
        try:
            import os
            samples_to_use = None
            if target_layer and hasattr(self, 'layer_path_samples'):
                norm_target = os.path.normcase(os.path.normpath(target_layer))
                print(f"[get_curve_aware_path] Looking for target_layer: {target_layer} (norm: {norm_target})")
                print(f"[get_curve_aware_path] Available keys: {list(self.layer_path_samples.keys())}")
                for k, v in self.layer_path_samples.items():
                    norm_k = os.path.normcase(os.path.normpath(k))
                    print(f"   - comparing with key: {k} (norm: {norm_k})")
                    # Match if they are exactly the same, or if one ends with the other (to handle absolute vs relative paths)
                    if norm_k == norm_target or norm_k.endswith(os.sep + norm_target) or norm_target.endswith(os.sep + norm_k):
                        print(f"[get_curve_aware_path] MATCH FOUND!")
                        samples_to_use = v
                        break
            
            if not samples_to_use and hasattr(self, 'master_curved_path_samples') and self.master_curved_path_samples:
                print(f"Warning: Falling back to master_curved_path_samples for target layer {target_layer}")
                samples_to_use = self.master_curved_path_samples
                
            if not samples_to_use:
                raise Exception("curved_path_samples is missing.")

            master_samples = samples_to_use
            
            # Simple bounding box / range check
            # if start_ch < master_samples[0]['ch'] or end_ch > master_samples[-1]['ch']:
            #    print("Warning: requested chainage out of bounds for master samples")

            master_chs = [s['ch'] for s in master_samples]
            master_xs  = [s['center'][0] for s in master_samples]
            master_ys  = [s['center'][1] for s in master_samples]
            master_zs  = [s['center'][2] for s in master_samples]
            
            master_px = [s['perp'][0] for s in master_samples]
            master_py = [s['perp'][1] for s in master_samples]
            master_pz = [s['perp'][2] for s in master_samples]

            path_samples = []
            cur_ch = float(start_ch)
            target_ch = float(end_ch)

            while cur_ch <= target_ch + 0.01:
                # Interpolate center point XYZ
                x = float(np.interp(cur_ch, master_chs, master_xs))
                y = float(np.interp(cur_ch, master_chs, master_ys))
                z = float(np.interp(cur_ch, master_chs, master_zs))
                pos_xyz = np.array([x, y, z])

                # Interpolate perpendicular vector
                px = float(np.interp(cur_ch, master_chs, master_px))
                py = float(np.interp(cur_ch, master_chs, master_py))
                pz = float(np.interp(cur_ch, master_chs, master_pz))
                perp = np.array([px, py, pz])
                p_len = np.linalg.norm(perp)
                if p_len > 1e-9:
                    perp /= p_len

                # Approximate forward direction as cross product of UP [0,0,1] and PERP
                # This ensures the camera aligns exactly with the curve sweep
                d_vec = np.cross(perp, np.array([0.0, 0.0, 1.0]))
                d_len = np.linalg.norm(d_vec)
                if d_len > 1e-9:
                    d_vec /= d_len

                path_samples.append((cur_ch, pos_xyz, perp, d_vec))
                cur_ch += step

            print(f"[Tunnel] get_curve_aware_path: generated {len(path_samples)} samples "
                  f"from curved_path_samples (curve-accurate)")
            return path_samples

        except Exception as e:
            print(f"[Tunnel] get_curve_aware_path: accurate path unavailable ({e}), "
                  f"using fallback baseline interpolation")

        # ------------------------------------------------------------------
        # FALLBACK PATH: use raw baseline points (straight-line interpolation)
        # ------------------------------------------------------------------
        pts_3d = self.get_road_baseline_points_3d(target_layer)
        if not pts_3d:
            if hasattr(self, 'zero_start_point') and self.zero_start_point is not None:
                p0 = np.array(self.zero_start_point, dtype=float)
                p1 = np.array(self.zero_end_point, dtype=float)
                dist = np.linalg.norm(p1 - p0)
                pts_3d = [
                    (0.0, p0[0], p0[1], p0[2]),
                    (dist, p1[0], p1[1], p1[2])
                ]
        if not pts_3d:
            return []

        all_chs = [p[0] for p in pts_3d]
        all_xs  = [p[1] for p in pts_3d]
        all_ys  = [p[2] for p in pts_3d]
        all_zs  = [p[3] for p in pts_3d]

        path_samples = []
        cur_ch = float(start_ch)
        target_ch = float(end_ch)

        while cur_ch <= target_ch + 0.01:
            x = float(np.interp(cur_ch, all_chs, all_xs))
            y = float(np.interp(cur_ch, all_chs, all_ys))
            z = float(np.interp(cur_ch, all_chs, all_zs))
            pos_xyz = np.array([x, y, z])

            # Direction from sparse pts_3d
            idx = 0
            for i in range(len(pts_3d) - 1):
                if pts_3d[i][0] <= cur_ch <= pts_3d[i + 1][0]:
                    idx = i
                    break
            else:
                if cur_ch < pts_3d[0][0]:
                    idx = 0
                else:
                    idx = len(pts_3d) - 2

            seg_p0 = np.array(pts_3d[idx][1:4])
            seg_p1 = np.array(pts_3d[idx + 1][1:4])
            d_vec = seg_p1 - seg_p0
            d_len = np.linalg.norm(d_vec)
            if d_len > 0:
                d_vec /= d_len
            else:
                d_vec = np.array([1.0, 0.0, 0.0])

            perp = np.array([-d_vec[1], d_vec[0], 0.0])
            p_len = np.linalg.norm(perp)
            if p_len > 1e-9:
                perp /= p_len
            else:
                perp = np.array([0.0, 1.0, 0.0])

            path_samples.append((cur_ch, pos_xyz, perp, d_vec))
            cur_ch += step

        return path_samples
        ###############################################################################################

    # Define the function for the curve the tunnel 
    def get_curve_aware_path_old(self, start_ch, end_ch, step=0.5):
        """Calculates a list of (ch, pos_xyz, perp, dir_vec) samples from start_ch to end_ch
        by directly sub-sampling from master_curved_path_samples which already contain
        the accurate curve-rotated positions and perpendicular vectors from the road
        surface baseline.

        The key insight: master_curved_path_samples are generated by walking the
        baseline with incremental rotation matrices at curve points (see
        map_baselines_to_3d_planes_from_data STEP 3).  Each sample already has
        the correct XY position and perpendicular vector that follows the curve.
        We interpolate *between* those dense samples rather than between sparse
        baseline polyline vertices, so the tunnel follows every curve accurately.
        """
        import numpy as np

        # ------------------------------------------------------------------
        # PRIMARY PATH: use master_curved_path_samples (curve-accurate)
        # ------------------------------------------------------------------
        try:
            if not hasattr(self, 'master_curved_path_samples') or not self.master_curved_path_samples:
                raise Exception("master_curved_path_samples is missing.")

            master_samples = self.master_curved_path_samples

            # Compute the global chainage offset once
            global_start_offset = 0.0
            if hasattr(self, 'zero_start_km') and self.zero_start_km is not None:
                global_start_offset = (float(self.zero_start_km) * 1000.0
                                       + float(getattr(self, 'zero_start_chainage', 0.0)))

            # ── SORT MASTER SAMPLES BY CHAINAGE ──
            # In Merged Layer mode, samples might be appended in reverse order.
            # np.interp strictly requires the x-coordinates (chainage) to be increasing.
            sorted_samples = sorted(master_samples, key=lambda s: s['ch'])

            # Build arrays of absolute chainage and XY from sorted samples
            m_chs  = np.array([s['ch'] + global_start_offset for s in sorted_samples], dtype=float)
            m_xs   = np.array([s['center'][0] for s in sorted_samples], dtype=float)
            m_ys   = np.array([s['center'][1] for s in sorted_samples], dtype=float)
            m_perp_xs = np.array([s['perp'][0] for s in sorted_samples], dtype=float)
            m_perp_ys = np.array([s['perp'][1] for s in sorted_samples], dtype=float)

            # Load Z elevation profile directly from the baseline points
            # (bypassing _load_baseline_from_design_layer which fails in design layers)
            pts_3d_z = self.get_road_baseline_points_3d()
            if not pts_3d_z:
                raise Exception("No Z profile found (get_road_baseline_points_3d returned empty).")
                
            ref_chs_arr = np.array([p[0] for p in pts_3d_z], dtype=float)
            ref_zs_arr = np.array([p[3] for p in pts_3d_z], dtype=float)

            # Build Z array aligned with master samples
            m_zs = np.array([
                float(np.interp(ch, ref_chs_arr, ref_zs_arr))
                for ch in m_chs
            ], dtype=float)

            # ----------------------------------------------------------
            # Generate tunnel path samples by interpolating the dense
            # master curve data.  Because master samples are ~0.5 m apart
            # and already follow every curve rotation, interpolation
            # between them is highly accurate.
            # ----------------------------------------------------------
            path_samples = []
            cur_ch = float(start_ch)
            target_ch = float(end_ch)
            eps = step * 0.1  # small epsilon for tangent computation

            while cur_ch <= target_ch + 0.01:
                # Interpolate curved position from master samples
                x = float(np.interp(cur_ch, m_chs, m_xs))
                y = float(np.interp(cur_ch, m_chs, m_ys))
                z = float(np.interp(cur_ch, m_chs, m_zs))
                pos_xyz = np.array([x, y, z])

                # Interpolate the perpendicular vector from master samples
                # (these are already curve-rotated in the master data)
                px = float(np.interp(cur_ch, m_chs, m_perp_xs))
                py = float(np.interp(cur_ch, m_chs, m_perp_ys))
                perp = np.array([px, py, 0.0])
                perp_len = np.linalg.norm(perp)
                if perp_len > 1e-9:
                    perp /= perp_len
                else:
                    perp = np.array([0.0, 1.0, 0.0])

                # Compute tangent direction from nearby interpolated points
                # so it reflects the actual curve direction, not a sparse segment
                ch_lo = max(cur_ch - eps, float(m_chs[0]))
                ch_hi = min(cur_ch + eps, float(m_chs[-1]))
                if abs(ch_hi - ch_lo) < 1e-9:
                    # At the very edge — use perp rotated 90°
                    d_vec = np.array([perp[1], -perp[0], 0.0])
                else:
                    x_lo = float(np.interp(ch_lo, m_chs, m_xs))
                    y_lo = float(np.interp(ch_lo, m_chs, m_ys))
                    z_lo = float(np.interp(ch_lo, m_chs, m_zs))
                    x_hi = float(np.interp(ch_hi, m_chs, m_xs))
                    y_hi = float(np.interp(ch_hi, m_chs, m_ys))
                    z_hi = float(np.interp(ch_hi, m_chs, m_zs))
                    d_vec = np.array([x_hi - x_lo, y_hi - y_lo, z_hi - z_lo])
                    d_len = np.linalg.norm(d_vec)
                    if d_len > 1e-9:
                        d_vec /= d_len
                    else:
                        d_vec = np.array([perp[1], -perp[0], 0.0])

                path_samples.append((cur_ch, pos_xyz, perp, d_vec))
                cur_ch += step

            print(f"[Tunnel] get_curve_aware_path: {len(path_samples)} samples "
                  f"from master_curved_path_samples (curve-accurate)")
            return path_samples

        except Exception as e:
            print(f"[Tunnel] get_curve_aware_path: master path unavailable ({e}), "
                  f"using fallback baseline interpolation")

        # ------------------------------------------------------------------
        # FALLBACK PATH: use raw baseline points (straight-line interpolation)
        # ------------------------------------------------------------------
        pts_3d = self.get_road_baseline_points_3d()
        if not pts_3d:
            if hasattr(self, 'zero_start_point') and self.zero_start_point is not None:
                p0 = np.array(self.zero_start_point, dtype=float)
                p1 = np.array(self.zero_end_point, dtype=float)
                dist = np.linalg.norm(p1 - p0)
                pts_3d = [
                    (0.0, p0[0], p0[1], p0[2]),
                    (dist, p1[0], p1[1], p1[2])
                ]
        if not pts_3d:
            return []

        all_chs = [p[0] for p in pts_3d]
        all_xs  = [p[1] for p in pts_3d]
        all_ys  = [p[2] for p in pts_3d]
        all_zs  = [p[3] for p in pts_3d]

        path_samples = []
        cur_ch = float(start_ch)
        target_ch = float(end_ch)

        while cur_ch <= target_ch + 0.01:
            x = float(np.interp(cur_ch, all_chs, all_xs))
            y = float(np.interp(cur_ch, all_chs, all_ys))
            z = float(np.interp(cur_ch, all_chs, all_zs))
            pos_xyz = np.array([x, y, z])

            # Direction from sparse pts_3d
            idx = 0
            for i in range(len(pts_3d) - 1):
                if pts_3d[i][0] <= cur_ch <= pts_3d[i + 1][0]:
                    idx = i
                    break
            else:
                if cur_ch < pts_3d[0][0]:
                    idx = 0
                else:
                    idx = len(pts_3d) - 2

            seg_p0 = np.array(pts_3d[idx][1:4])
            seg_p1 = np.array(pts_3d[idx + 1][1:4])
            d_vec = seg_p1 - seg_p0
            d_len = np.linalg.norm(d_vec)
            if d_len > 0:
                d_vec /= d_len
            else:
                d_vec = np.array([1.0, 0.0, 0.0])

            perp = np.array([-d_vec[1], d_vec[0], 0.0])
            p_len = np.linalg.norm(perp)
            if p_len > 1e-9:
                perp /= p_len
            else:
                perp = np.array([0.0, 1.0, 0.0])

            path_samples.append((cur_ch, pos_xyz, perp, d_vec))
            cur_ch += step

        return path_samples
