    def open_bridge_construction_dialog(self, chainage_km, chainage_m, chainage_label, point_3d, construction_dot_name=None, loaded_data=None):
        """
        Open ConstructionConfigDialog for bridge component configuration.
        Extract bridge configuration and create 3D components.
        Also auto-creates next deck label (D1 after P2, D2 after P3, etc.) after save.
        
        Args:
            chainage_km: KM value
            chainage_m: Meters within KM
            chainage_label: Display label
            point_3d: 3D coordinate
            construction_dot_name: Construction dot name (e.g., "P1", "P2")
            loaded_data: Previously saved component data from JSON (for editing)
        """
        # Verify current context
        if not hasattr(self, 'current_layer_name') or not self.current_layer_name:
            QMessageBox.warning(self, "Error", "No active layer. Please open a worksheet first.")
            self.message_text.append("ERROR: Attempting to open bridge dialog without active layer")
            return
        
        if not hasattr(self, 'current_worksheet_name') or not self.current_worksheet_name:
            QMessageBox.warning(self, "Error", "No active worksheet. Please open a worksheet first.")
            self.message_text.append("ERROR: Attempting to open bridge dialog without active worksheet")
            return
        
        if not hasattr(self, 'current_subfolder_type'):
            self.current_subfolder_type = 'designs'  # Default to designs
        
        # Create chainage_str in format "KM+00M" (e.g., 101+019) using zero_start_km
        zero_start_km = getattr(self, 'zero_start_km', 0)
        chainage_str = f"{int(zero_start_km)}+{int(chainage_m):03d}"
        
        # Pass loaded data to dialog so user can see/edit previous values
        dialog = ConstructionConfigDialog(chainage_label=chainage_label, parent=self, loaded_data=loaded_data)
        
        if dialog.exec_() == QDialog.Accepted:
            config = dialog.get_configuration()
            self.message_text.append(f"Bridge dialog config received: {config}")
            
            # Extract bridge component configuration from dialog
            bridge_config = self.extract_bridge_config_from_dialog(config, chainage_km, chainage_m, point_3d)
            self.message_text.append(f"Bridge config extracted: Chainage {chainage_label}, Type: {bridge_config.get('bridge_type')}")
            
            # Add user-entered pillar name to bridge_config
            bridge_config['pillar_name'] = config.get('pillar_name', 'P ?')

            # ── Capture Path Rotation from the last calculation ──
            # This comes from self.get_3d_coordinate_from_chainage -> self.get_path_transformation_at_chainage
            bridge_config['path_rotation_deg'] = getattr(self, 'last_calculated_path_angle', 0.0)
            self.message_text.append(f"  → Path rotation captured: {bridge_config['path_rotation_deg']:.2f}º")

            # ── Pass material/reinforcement configs into bridge_config ──
            for mat_key in ['u_shape_materials', 'l_shape_materials']:
                if mat_key in config:
                    bridge_config[mat_key] = config[mat_key]
            # For Normal bridge: dialog uses 'component_materials' key
            if 'component_materials' in config:
                bridge_config['materials'] = config['component_materials']
            elif 'materials' in config:
                bridge_config['materials'] = config['materials']
            # =================================================
            
            # If no construction_dot_name provided, generate next one
            if not construction_dot_name:
                construction_dot_name = f"P{len(self.loaded_bridge_components_data) + 1}"
            
            # Save configuration to JSON FIRST (for persistence)
            json_saved = self.save_bridge_component_to_json(bridge_config, construction_dot_name, chainage_str)
            
            if json_saved:
                # Load freshly saved data into memory for quick access
                layer_folder = os.path.join(
                    self.WORKSHEETS_BASE_DIR,
                    self.current_worksheet_name,
                    self.current_subfolder_type,
                    self.current_layer_name
                )
                try:
                    from json_manager import get_config_data
                    bridge_components = get_config_data(layer_folder, "bridge_components.json")
                    if bridge_components:
                        for comp in bridge_components:
                            if comp.get('construction_dot') == construction_dot_name:
                                self.loaded_bridge_components_data[construction_dot_name] = comp
                                break
                except Exception as e:
                    print(f"Error loading bridge components to memory: {e}")
                
                # Create/update 3D bridge components
                self.create_bridge_components(bridge_config)
                self.message_text.append(f"✓ Bridge component created/updated at {construction_dot_name} {chainage_label}")

                # ────────────────────────────────────────────────────────────────
                # AUTO-CREATE NEXT DECK LABEL (D1 after P2, D2 after P3, etc.)
                # ────────────────────────────────────────────────────────────────
                if hasattr(self, 'last_construction_dot') and self.last_construction_dot is not None:
                    # Only create deck between consecutive pillars
                    prev_num = int(self.last_construction_dot[1:]) if self.last_construction_dot.startswith('P') else 0
                    curr_num = int(construction_dot_name[1:]) if construction_dot_name.startswith('P') else 0
                    
                    if curr_num == prev_num + 1:
                        self.add_deck_between_pillars(self.last_construction_dot, construction_dot_name)
                        self.message_text.append(f"→ Auto-created deck label between {self.last_construction_dot} and {construction_dot_name}")
                
                # Remember this pillar for the next one
                self.last_construction_dot = construction_dot_name
                
            else:
                QMessageBox.warning(self, "Save Error", "Failed to save bridge configuration to JSON")
                self.message_text.append(f"✗ Bridge component NOT created - JSON save failed for {construction_dot_name} {chainage_label}")
        else:
            self.message_text.append(f"Bridge construction dialog cancelled")

