    def extract_bridge_config_from_dialog(self, dialog_config, chainage_km, chainage_m, point_3d):
        """
        Extract bridge component configuration from ConstructionConfigDialog
        and convert to bridge component format with validation.
        
        CRITICAL: Pillar dimensions MUST be in nested 'dimensions' dictionary
        to match create_pillar_actor() expectations
        """
        try:
            # Safely convert point_3d to list
            if point_3d is None:
                point_3d = [0.0, 0.0, 0.0]
            elif isinstance(point_3d, np.ndarray):
                point_3d = point_3d.tolist()
            
            # Helper function to safely convert to float
            def safe_float(value, default=0.0):
                try:
                    if value is None or value == '':
                        return default
                    f = float(value)
                    return f if f > 0 else default
                except (ValueError, TypeError):
                    return default
                    
            def parse_color(hex_str, default=(0.5, 0.5, 0.5)):
                try:
                    if hex_str and len(hex_str) == 7 and hex_str.startswith('#'):
                        r = int(hex_str[1:3], 16) / 255.0
                        g = int(hex_str[3:5], 16) / 255.0
                        b = int(hex_str[5:7], 16) / 255.0
                        return (r, g, b)
                except Exception:
                    pass
                return default
            
            # Check if this is a U Shape or L Shape Pillar from Long Bridge
            long_type = dialog_config.get('long_type', '').strip()
            bridge_type_category = 'long' if dialog_config.get('bridge_type') == 'Long Bridge' else 'mini'

            if long_type == 'U Shape Pillar':
                footing_c = parse_color(dialog_config.get('u_shape_footing_color', '#994C00'), (0.6, 0.3, 0.0))
                left_c = parse_color(dialog_config.get('left_pillar_color', '#808080'))
                right_c = parse_color(dialog_config.get('right_pillar_color', '#808080'))
                span_c = parse_color(dialog_config.get('u_shape_span_color', '#808080'))

                bridge_config = {
                    'chainage_km': float(chainage_km),
                    'chainage_m': float(chainage_m),
                    'coordinates_3d': point_3d,
                    'bridge_type': bridge_type_category,
                    'long_type': long_type,
                    'has_footing': dialog_config.get('has_footing', False),
                    'footing': {
                        'type': 'rectangle',
                        'length': safe_float(dialog_config.get('u_shape_footing_length'), 2.5),
                        'width': safe_float(dialog_config.get('u_shape_footing_width'), 2.5),
                        'height': safe_float(dialog_config.get('u_shape_footing_height'), 1.0),
                        'color': footing_c
                    },
                    'left_pillar': {
                        'type': 'rectangle',
                        'dimensions': {
                            'length': safe_float(dialog_config.get('left_pillar_length'), 1.5),
                            'width': safe_float(dialog_config.get('left_pillar_width'), 1.5),
                            'height': safe_float(dialog_config.get('left_pillar_height'), 8.0)
                        },
                        'offset': abs(safe_float(dialog_config.get('left_pillar_offset'), 2.0)),
                        'color': left_c
                    },
                    'right_pillar': {
                        'type': 'rectangle',
                        'dimensions': {
                            'length': safe_float(dialog_config.get('right_pillar_length'), 1.5),
                            'width': safe_float(dialog_config.get('right_pillar_width'), 1.5),
                            'height': safe_float(dialog_config.get('right_pillar_height'), 8.0)
                        },
                        'offset': abs(safe_float(dialog_config.get('right_pillar_offset'), 2.0)),
                        'color': right_c
                    },
                    'span': {
                        'type': 'rectangle',
                        'width': safe_float(dialog_config.get('top_span_length'), 1.2),  # Used for "Along Road" (smaller)
                        'length': safe_float(dialog_config.get('top_span_width'), 1.2), # Used for "Across Road" (larger, auto)
                        'height': safe_float(dialog_config.get('top_span_thickness'), 0.8),
                        'color': span_c
                    },
                    'deck_supporters': [
                        {
                            'type': 'rectangle',
                            'width': safe_float(ds.get('width'), 0.5),
                            'length': safe_float(ds.get('length'), 1.2),
                            'height': safe_float(ds.get('height'), 0.3),
                            'position': ds.get('position', 'Center'),
                            'distance': ds.get('distance', ''),
                            'color': parse_color(dialog_config.get('u_shape_deck_support_color'), (1.0, 1.0, 0.8))
                        } for ds in dialog_config.get('u_shape_deck_supporters', [])
                    ],
                    'cantilever': {
                        'length': safe_float(dialog_config.get('u_shape_cantilever', {}).get('length'), 2.0),
                        'width': safe_float(dialog_config.get('u_shape_cantilever', {}).get('width'), 1.5),
                        'thickness': safe_float(dialog_config.get('u_shape_cantilever', {}).get('thickness'), 0.8),
                        'direction': dialog_config.get('u_shape_cantilever', {}).get('direction', 'Left'),
                        'deck_support': {
                            'width': safe_float(dialog_config.get('u_shape_cantilever', {}).get('deck_support', {}).get('width'), 0.5),
                            'length': safe_float(dialog_config.get('u_shape_cantilever', {}).get('deck_support', {}).get('length'), 2.5),
                            'height': safe_float(dialog_config.get('u_shape_cantilever', {}).get('deck_support', {}).get('height'), 0.3),
                            'position': dialog_config.get('u_shape_cantilever', {}).get('deck_support', {}).get('position', 'Center')
                        } if dialog_config.get('u_shape_cantilever', {}).get('deck_support') else None
                    } if 'u_shape_cantilever' in dialog_config else None
                }
                return bridge_config

            elif long_type == 'L Shape Pillar':
                footing_c = parse_color(dialog_config.get('l_shape_footing_color', '#994C00'), (0.6, 0.3, 0.0))
                vert_c = parse_color(dialog_config.get('vertical_pillar_color', '#808080'))
                canti_c = parse_color(dialog_config.get('cantilever_span_color', '#808080'))

                bridge_config = {
                    'chainage_km': float(chainage_km),
                    'chainage_m': float(chainage_m),
                    'coordinates_3d': point_3d,
                    'bridge_type': bridge_type_category,
                    'long_type': long_type,
                    'l_shape_side': dialog_config.get('l_shape_side', 'Left'),
                    'has_footing': dialog_config.get('has_footing', False),
                    'footing': {
                        'type': 'rectangle',
                        'length': safe_float(dialog_config.get('l_shape_footing_length'), 2.5),
                        'width': safe_float(dialog_config.get('l_shape_footing_width'), 2.5),
                        'height': safe_float(dialog_config.get('l_shape_footing_height'), 1.0),
                        'color': footing_c
                    },
                    'vertical_pillar': {
                        'type': 'rectangle',
                        'dimensions': {
                            'length': safe_float(dialog_config.get('vertical_pillar_length'), 1.5),
                            'width': safe_float(dialog_config.get('vertical_pillar_width'), 1.5),
                            'height': safe_float(dialog_config.get('vertical_pillar_height'), 8.0)
                        },
                        'offset': safe_float(dialog_config.get('vertical_pillar_offset'), 0.0),
                        'color': vert_c
                    },
                    'span': {
                        'type': 'rectangle',
                        'length': safe_float(dialog_config.get('cantilever_span_length'), 1.5),
                        'width': safe_float(dialog_config.get('cantilever_span_width'), 1.5),
                        'height': safe_float(dialog_config.get('cantilever_span_thickness'), 0.8),
                        'direction': dialog_config.get('cantilever_direction', 'Center'),
                        'color': canti_c
                    },
                    'deck_support': {
                        'type': 'rectangle',
                        'width': safe_float(dialog_config.get('l_shape_deck_support_width'), 0.5),
                        'length': safe_float(dialog_config.get('l_shape_deck_support_length'), 1.5),
                        'height': safe_float(dialog_config.get('l_shape_deck_support_height'), 0.3),
                        'color': parse_color(dialog_config.get('l_shape_deck_support_color'), (1.0, 1.0, 0.8))
                    }
                }
                return bridge_config
            
            # Default / original behavior
            bridge_config = {
                'chainage_km': float(chainage_km),
                'chainage_m': float(chainage_m),
                'coordinates_3d': point_3d,
                'bridge_type': bridge_type_category,
                'long_type': long_type,
                'has_footing': dialog_config.get('has_footing', False),
                'base': {
                    'type': dialog_config.get('base_shape', 'rectangle'),
                    'length': safe_float(dialog_config.get('base_length'), 5.0),
                    'width': safe_float(dialog_config.get('base_width'), 3.0),
                    'height': safe_float(dialog_config.get('base_height'), 0.5),
                    'color': parse_color(dialog_config.get('base_color', '#994C00'), (0.6, 0.3, 0.0))
                },
                'pillar': {
                    'type': str(dialog_config.get('pillar_shape', 'circular')),
                    'dimensions': {},  # NESTED dimensions dict
                    'color': parse_color(dialog_config.get('pillar_color', '#808080'), (0.5, 0.5, 0.5))
                },
                'span': {
                    'type': dialog_config.get('span_shape', 'flat'),
                    'length': safe_float(dialog_config.get('span_length'), 5.0),
                    'width': safe_float(dialog_config.get('span_width'), 3.0),
                    'height': safe_float(dialog_config.get('span_height'), 0.3),
                    'color': parse_color(dialog_config.get('span_color', '#808080'), (0.5, 0.5, 0.5))
                },
                'deck_supporters': [
                    {
                        'type': dialog_config.get('deck_support_shape', 'rectangular_box'),
                        'length': safe_float(ds.get('length'), 6.0),
                        'width': safe_float(ds.get('width'), 3.0),
                        'height': safe_float(ds.get('height'), 1.0),
                        'position': ds.get('position', 'Center'),
                        'distance': ds.get('distance', ''),
                        'color': parse_color(dialog_config.get('deck_support_color', '#FFFFCC'), (1.0, 1.0, 0.8))
                    } for ds in dialog_config.get('deck_supporters', [])
                ]
            }
            
            # Handle pillar dimensions based on type - PUT IN NESTED 'dimensions' DICT
            pillar_type_str = str(bridge_config['pillar'].get('type', 'circular')).lower()
            if pillar_type_str == 'circular':
                # CIRCULAR: Only diameter and height (NO width!)
                bridge_config['pillar']['dimensions'] = {
                    'diameter': safe_float(dialog_config.get('pillar_diameter_width'), 2.0),
                    'height': safe_float(dialog_config.get('pillar_height'), 8.0)
                }
            else:
                # RECTANGULAR: length, width, and height
                bridge_config['pillar']['dimensions'] = {
                    'width': safe_float(dialog_config.get('pillar_diameter_width'), 2.0),
                    'length': safe_float(dialog_config.get('pillar_length'), 1.0),
                    'height': safe_float(dialog_config.get('pillar_height'), 8.0)
                }
            
            self.message_text.append(f"✓ Config extracted - Footing: Rectangle, Pillar: {bridge_config['pillar']['type']}, All dimensions nested correctly")
            return bridge_config
            
        except Exception as e:
            error_msg = f"ERROR extracting bridge config: {str(e)}\n{traceback.format_exc()}"
            self.message_text.append(error_msg)
            raise

