    def create_bridge_components(self, bridge_config):
        """Create 3D VTK actors for bridge components aligned to projection line path"""
        try:
            raw_base_point = np.array(bridge_config['coordinates_3d'])
            chainage_key = f"{bridge_config['chainage_km']:.1f}_{bridge_config['chainage_m']:.1f}"
            
            # Use the exact 3D coordinates provided in the config to ensure perfect alignment 
            # with the projection line.
            base_point = np.array([raw_base_point[0], raw_base_point[1], raw_base_point[2]])
            
            # Get the visual render angle exactly as it was preserved in the bridge_config
            path_angle = float(bridge_config.get('path_rotation_deg', 0.0))
            
            if bridge_config.get('long_type') == 'U Shape Pillar':
                self.create_u_shape_components(bridge_config, base_point, chainage_key)
                return
            elif bridge_config.get('long_type') == 'L Shape Pillar':
                self.create_l_shape_components(bridge_config, base_point, chainage_key)
                return
            
            # Create component actors list
            component_actors = []

            # 1. OPTIONAL FOOTING (Base) rendering for Normal Bridge
            has_footing = bridge_config.get('has_footing', False)
            base_top_z = base_point[2]

            if has_footing:
                base_dims = bridge_config['base'].get('dimensions', {}) # Sometimes in 'base' directly
                if not base_dims:
                    base_dims = bridge_config['base']
                
                base_height = base_dims.get('height', 1.0)
                base_top_z += base_height
                
                # Check for footing shape (Standard Normal is Rectangular)
                footing_actor = self.create_footing_actor(
                    bridge_config['base'], 
                    base_point, 
                    bridge_config['bridge_type'],
                    path_angle # Pass path rotation
                )
                if footing_actor:
                    component_actors.append(footing_actor)
                    self.renderer.AddActor(footing_actor)
                    self.message_text.append(f"    • Added Footing (Base) H:{base_height}")
            
            # 2. CREATE PILLAR (Grey, on top of base)
            pillar_dims   = bridge_config['pillar'].get('dimensions', {})
            pillar_height = pillar_dims.get('height', 8.0)   # now reads the real user value (10 m, etc.)
            
            pillar_type_str = str(bridge_config['pillar'].get('type', 'circular')).lower()
            if pillar_type_str == 'circular':
                diameter = pillar_dims.get('diameter', 2.0)
                pillar_desc = f"Circular ∅{diameter} H:{pillar_height}"
            else:
                length = pillar_dims.get('length', 2.0)
                width = pillar_dims.get('width', 1.0)
                pillar_desc = f"Rectangular {length}×{width} H:{pillar_height}"
            
            self.message_text.append(f"    • Pillar: {pillar_desc}")
            
            # ─── CRITICAL: Copy pillar_name into pillar config for label creation ───
            if 'pillar_name' in bridge_config:
                bridge_config['pillar']['pillar_name'] = bridge_config['pillar_name']
                self.message_text.append(f"      → Pillar name set to: {bridge_config['pillar_name']}")
            
            pillar_actor = self.create_pillar_actor(
                bridge_config['pillar'],
                np.array([base_point[0], base_point[1], base_top_z]),
                bridge_config['bridge_type'],
                path_angle # Pass path rotation
            )
            if pillar_actor:
                self.renderer.AddActor(pillar_actor)
                self.message_text.append(f"      ✅ Pillar actor ADDED to 3D renderer")
                component_actors.append(pillar_actor)
            else:
                self.message_text.append(f"      ❌ Pillar actor creation returned None - NOT ADDED")
            
            # Calculate pillar top for span positioning
            pillar_top_z = base_top_z + pillar_height
            
            # 3. CREATE SPAN (Grey, on top of pillar)
            self.message_text.append(f"    • Span: {bridge_config['span']['type']} {bridge_config['span']['length']}×{bridge_config['span']['width']}×{bridge_config['span']['height']}")
            span_actor = self.create_span_actor(
                bridge_config['span'],
                np.array([base_point[0], base_point[1], pillar_top_z]),
                bridge_config['bridge_type'],
                path_angle # Pass path rotation
            )
            if span_actor:
                self.renderer.AddActor(span_actor)
                self.message_text.append(f"      ✅ Span actor ADDED to 3D renderer")
                component_actors.append(span_actor)
            
            # Calculate span top for deck support positioning
            span_top_z = pillar_top_z + bridge_config['span']['height']
            
            # 4. CREATE DECK SUPPORTERS (Light Yellow, on top of span)
            deck_actors = []
            if 'deck_supporters' in bridge_config:
                abs_rad = np.radians(path_angle + 90.0)
                saved_dir_x = np.cos(abs_rad)
                saved_dir_y = np.sin(abs_rad)
                local_perp_xy = np.array([-saved_dir_y, saved_dir_x, 0.0])
                span_w = bridge_config['span'].get('width', 3.0)
                
                for i, ds_cfg in enumerate(bridge_config['deck_supporters']):
                    pos_type = ds_cfg.get('position', 'Center')
                    ds_pos = np.array([base_point[0], base_point[1], span_top_z])
                    
                    d_val = ds_cfg.get('distance', '')
                    ds_dist = float(d_val) if d_val and str(d_val).strip() else (span_w / 4.0)
                    
                    if pos_type == 'Left':
                        ds_pos += local_perp_xy * ds_dist
                    elif pos_type == 'Right':
                        ds_pos -= local_perp_xy * ds_dist
                    
                    self.message_text.append(f"    • Deck Support #{i+1} ({pos_type}): {ds_cfg['length']}×{ds_cfg['width']}×{ds_cfg['height']}")
                    d_actor = self.create_deck_support_actor(ds_cfg, ds_pos, bridge_config['bridge_type'], path_angle)
                    if d_actor:
                        self.renderer.AddActor(d_actor)
                        self.message_text.append(f"      ✅ Deck actor #{i+1} ADDED to 3D renderer")
                        component_actors.append(d_actor)
                        deck_actors.append(d_actor)
            
            # ═══════════════════════════════════════════════════════════════
            # 5. APPLY MATERIAL TRANSPARENCY to component actors
            # ═══════════════════════════════════════════════════════════════
            try:
                mat_configs = bridge_config.get('materials', {})
                
                # Apply transparency from material config to each component actor
                actor_mat_pairs = [
                    (footing_actor if has_footing else None, mat_configs.get('footing', {})),
                    (pillar_actor, mat_configs.get('pillar', {})),
                    (span_actor, mat_configs.get('span', {})),
                ]
                for da in deck_actors:
                    actor_mat_pairs.append((da, mat_configs.get('deck_support', {})))
                for actor_ref, mat_cfg in actor_mat_pairs:
                    if actor_ref and mat_cfg:
                        tp = mat_cfg.get('transparency_percent', 0)
                        if tp > 0:
                            opacity = max(0.1, 1.0 - (tp / 100.0))
                            actor_ref.GetProperty().SetOpacity(opacity)
            except Exception:
                pass

            # ═══════════════════════════════════════════════════════════════
            # 6. CREATE REINFORCEMENT BARS inside bridge components
            # ═══════════════════════════════════════════════════════════════
            try:
                mat_configs = bridge_config.get('materials', {})
                
                # Footing rebar
                if has_footing and mat_configs.get('footing'):
                    self.add_reinforcement_for_rect_component(
                        bridge_config['base'], base_point, bridge_config['base']['color'],
                        mat_configs['footing'], path_angle) # Pass path rotation
                
                # Pillar rebar
                pillar_base_pt = np.array([base_point[0], base_point[1], base_top_z])
                pillar_mat = mat_configs.get('pillar', {})
                if pillar_type_str == 'circular':
                    self.add_reinforcement_for_circular_pillar(
                        bridge_config['pillar'], pillar_base_pt,
                        bridge_config['pillar']['color'], pillar_mat)
                else:
                    # Rectangular pillar - treat dimensions as length/width/height
                    rect_cfg = {
                        'length': pillar_dims.get('length', 2.0),
                        'width': pillar_dims.get('width', 1.0),
                        'height': pillar_height
                    }
                    self.add_reinforcement_for_rect_component(
                        rect_cfg, pillar_base_pt,
                        bridge_config['pillar']['color'], pillar_mat, path_angle) # Pass path rotation
                
                # Span rebar
                if mat_configs.get('span'):
                    span_base_pt = np.array([base_point[0], base_point[1], pillar_top_z])
                    self.add_reinforcement_for_rect_component(
                        bridge_config['span'], span_base_pt,
                        bridge_config['span']['color'], mat_configs['span'], path_angle) # Pass path rotation
                
                # Deck support rebar
                ds_mat = mat_configs.get('deck_support', {})
                if 'deck_supporters' in bridge_config and ds_mat:
                    abs_rad = np.radians(path_angle + 90.0)
                    local_perp_xy = np.array([-np.sin(abs_rad), np.cos(abs_rad), 0.0])
                    span_w = bridge_config['span'].get('width', 3.0)
                    for ds_cfg in bridge_config['deck_supporters']:
                        pos_type = ds_cfg.get('position', 'Center')
                        ds_pos = np.array([base_point[0], base_point[1], span_top_z])
                        if pos_type == 'Left': ds_pos += local_perp_xy * (span_w / 4.0)
                        elif pos_type == 'Right': ds_pos -= local_perp_xy * (span_w / 4.0)
                        self.add_reinforcement_for_rect_component(ds_cfg, ds_pos, ds_cfg['color'], ds_mat, path_angle)
                
                self.message_text.append(f"    • Reinforcement bars: {len(self.reinforcement_actors)} total actors")
            except Exception as re:
                self.message_text.append(f"    ⚠ Rebar creation warning: {str(re)}")
            
            # Store configuration and actors
            self.bridge_components[chainage_key] = {
                'config': bridge_config,
                'actors': component_actors
            }
            self.bridge_component_actors.extend(component_actors)
            
            self.message_text.append(f"  ✓ Created {len(component_actors)} component actors")
            
            # Force render update - try multiple rendering approaches
            self.message_text.append(f"  → Triggering renderer update...")
            self.canvas.draw_idle()  # 2D update
            
            if hasattr(self, 'vtk_widget') and self.vtk_widget:
                try:
                    render_window = self.vtk_widget.GetRenderWindow()
                    if render_window:
                        # Force VTK to re-render everything
                        self.renderer.ResetCameraClippingRange()  # Adjust camera clipping planes
                        render_window.Render()
                        self.message_text.append(f"  ✓ VTK renderer updated and Render() called")
                except Exception as render_error:
                    self.message_text.append(f"  ⚠ Render warning: {str(render_error)}")
            else:
                self.message_text.append(f"  ⚠ VTK widget not available for rendering")
                
        except Exception as e:
            error_msg = f"Failed to create bridge components: {str(e)}\n{traceback.format_exc()}"
            QMessageBox.critical(self, "Error", error_msg)
            self.message_text.append(f"✗ ERROR creating bridge components: {str(e)}")
            self.message_text.append(traceback.format_exc())

    def _get_perpendicular_xy_vector(self):
        start = np.array(self.zero_start_point, dtype=float)
        end = np.array(self.zero_end_point, dtype=float)
        direction = end - start
        forward_xy = np.array([direction[0], direction[1], 0])
        norm = np.linalg.norm(forward_xy)
        if norm == 0:
            return np.array([0, 1, 0])
        forward_xy = forward_xy / norm
        return np.array([-forward_xy[1], forward_xy[0], 0])  # Perpendicular (Left)

    def create_u_shape_components(self, bridge_config, base_point, chainage_key):
        """Create U-Shape bridge components with dedicated actors:
        LEFT footing + LEFT pillar, RIGHT footing + RIGHT pillar, Span (connecting pillar tops).
        Footings are placed at left/right offsets from the projection line.
        Span width is auto-calculated from pillar offsets + pillar widths."""
        try:
            component_actors = []
            
            # --- GET EXACT BASE POINT AND TANGENT ANGLE AT THIS CHAINAGE ---
            # Use the exact 3D coordinates provided in the config to ensure perfect alignment 
            # with the projection line.
            
            # Reconstruct the precise tangent to fix misalignment on curved/angled paths
            ch_x_pos = bridge_config['chainage_km'] * 1000 + bridge_config['chainage_m'] - getattr(self, 'zero_start_chainage', 0.0)
            _, current_dir, _ = self.get_path_transformation_at_chainage(ch_x_pos)

            # Get the visual render angle exactly as it was preserved in the bridge_config
            path_angle = float(bridge_config.get('path_rotation_deg', 0.0))
            
            # We add 90 degrees so that the X-dimension (length) of the actors points across the road (perpendicular)
            # while the Y-dimension (width) points along the road.
            render_angle_deg = path_angle + 90.0

            self.message_text.append(f"    • U-Shape Original angle: {path_angle:.2f}°")

            # Reconstruct the exact left perpendicular vector at this chainage
            path_angle_rad = np.radians(path_angle)
            saved_dir_x = np.cos(path_angle_rad)
            saved_dir_y = np.sin(path_angle_rad)
            local_perp_xy = np.array([-saved_dir_y, saved_dir_x, 0.0])
            
            footing_cfg = bridge_config.get('footing', {})
            has_footing = bridge_config.get('has_footing', False)

            # ── LEFT PILLAR position (Applied to LEFT of project line) ──
            left_offset = abs(bridge_config['left_pillar']['offset'])
            left_dims = bridge_config['left_pillar']['dimensions']
            left_color = bridge_config['left_pillar']['color']
            left_base = base_point.copy() + local_perp_xy * left_offset

            # ── RIGHT PILLAR position (Applied to RIGHT of project line) ──
            right_offset = abs(bridge_config['right_pillar']['offset'])
            right_dims = bridge_config['right_pillar']['dimensions']
            right_color = bridge_config['right_pillar']['color']
            right_base = base_point.copy() - local_perp_xy * right_offset

            current_z_left = base_point[2]
            current_z_right = base_point[2]

            # ═══════════════════════════════════════════════════════════════
            # 1. LEFT FOOTING (at left pillar offset position)
            # ═══════════════════════════════════════════════════════════════
            if has_footing and footing_cfg:
                left_footing_actor = self._create_u_shape_footing_actor(
                    footing_cfg, left_base, current_z_left, render_angle_deg)
                if left_footing_actor:
                    self.renderer.AddActor(left_footing_actor)
                    component_actors.append(left_footing_actor)
                    current_z_left += footing_cfg['height']
                    self.message_text.append(
                        f"    • U-Shape LEFT Footing created at offset={left_offset}, Z={current_z_left:.2f}")

            # ═══════════════════════════════════════════════════════════════
            # 2. RIGHT FOOTING (at right pillar offset position)
            # ═══════════════════════════════════════════════════════════════
            if has_footing and footing_cfg:
                right_footing_actor = self._create_u_shape_footing_actor(
                    footing_cfg, right_base, current_z_right, render_angle_deg)
                if right_footing_actor:
                    self.renderer.AddActor(right_footing_actor)
                    component_actors.append(right_footing_actor)
                    current_z_right += footing_cfg['height']
                    self.message_text.append(
                        f"    • U-Shape RIGHT Footing created at offset={right_offset}, Z={current_z_right:.2f}")

            # ═══════════════════════════════════════════════════════════════
            # 3. LEFT PILLAR (on top of left footing)
            # ═══════════════════════════════════════════════════════════════
            left_pillar_base = left_base.copy()
            left_pillar_base[2] = current_z_left
            left_actor = self._create_u_shape_pillar_actor(left_dims, left_pillar_base, left_color, render_angle_deg)
            if left_actor:
                self.renderer.AddActor(left_actor)
                component_actors.append(left_actor)
                self.message_text.append(
                    f"    • U-Shape Left Pillar created on footing (offset={left_offset})")

            # ═══════════════════════════════════════════════════════════════
            # 4. RIGHT PILLAR (on top of right footing)
            # ═══════════════════════════════════════════════════════════════
            right_pillar_base = right_base.copy()
            right_pillar_base[2] = current_z_right
            right_actor = self._create_u_shape_pillar_actor(right_dims, right_pillar_base, right_color, render_angle_deg)
            if right_actor:
                self.renderer.AddActor(right_actor)
                component_actors.append(right_actor)
                self.message_text.append(
                    f"    • U-Shape Right Pillar created on footing (offset={right_offset})")

            # ═══════════════════════════════════════════════════════════════
            # 5. SPAN (auto-calculated connecting both pillar tops)
            # ═══════════════════════════════════════════════════════════════
            left_pillar_height = left_dims['height']
            right_pillar_height = right_dims['height']
            span_z = max(current_z_left + left_pillar_height,
                         current_z_right + right_pillar_height)

            total_offset_distance = left_offset + right_offset
            # CRITICAL: Use pillar 'length' (across road) to calculate span total length
            left_pillar_half_l = left_dims.get('length', 1.5) / 2.0
            right_pillar_half_l = right_dims.get('length', 1.5) / 2.0
            span_total_length = total_offset_distance + left_pillar_half_l + right_pillar_half_l

            span_cfg = bridge_config['span']
            span_center = (left_base + right_base) / 2.0
            span_center[2] = span_z

            span_actor = self._create_u_shape_span_actor(
                span_cfg, span_center, span_total_length, render_angle_deg)
            if span_actor:
                self.renderer.AddActor(span_actor)
                component_actors.append(span_actor)
                self.message_text.append(
                    f"    • U-Shape Span created (auto length={span_total_length:.2f}m)")

            # ═══════════════════════════════════════════════════════════════
            # 5a. CANTILEVER SPAN (If enabled)
            # ═══════════════════════════════════════════════════════════════
            cant_actor = None
            if bridge_config.get('cantilever'):
                cant_cfg = bridge_config['cantilever']
                side = cant_cfg.get('direction', 'Left')
                
                # Length outward from pillar, Width along road, Thickness=height
                cant_l = cant_cfg['length']
                cant_w = cant_cfg['width']
                cant_h = cant_cfg['thickness']
                
                if side == 'Left':
                    # Extend left from left pillar center
                    p_half_l = left_dims.get('length', 1.5) / 2.0
                    cant_pos = left_base.copy() + local_perp_xy * (p_half_l + cant_l / 2.0)
                else:
                    # Extend right from right pillar center
                    p_half_l = right_dims.get('length', 1.5) / 2.0
                    cant_pos = right_base.copy() - local_perp_xy * (p_half_l + cant_l / 2.0)
                
                cant_pos[2] = span_z
                
                # Reuse span actor creator (length=length across, width=along)
                cant_actor = self._create_u_shape_span_actor(
                    {'width': cant_w, 'height': cant_h, 'color': span_cfg['color']},
                    cant_pos, cant_l, render_angle_deg)
                if cant_actor:
                    self.renderer.AddActor(cant_actor)
                    component_actors.append(cant_actor)
                    self.message_text.append(f"    • U-Shape Cantilever ({side}) created")
                    
                    if cant_cfg.get('deck_support'):
                        cant_ds_cfg = cant_cfg['deck_support']
                        cant_ds_w = cant_ds_cfg['width']
                        cant_ds_l = cant_ds_cfg['length']
                        cant_ds_h = cant_ds_cfg['height']
                        cant_ds_pos_type = cant_ds_cfg.get('position', 'Center')  # Left / Center / Right
                        
                        # Compute lateral offset based on position within cantilever span
                        # cant_l = total cantilever length (outward from pillar)
                        # Center = no offset (already at cant_pos)
                        # Left   = shift toward far end of cantilever (outward end)
                        # Right  = shift toward pillar side (inner end)
                        half_cant_l = cant_l / 2.0
                        if cant_ds_pos_type == 'Left':
                            offset_factor = 1.0  # move toward outer (far) end
                        elif cant_ds_pos_type == 'Right':
                            offset_factor = -1.0  # move toward inner (pillar) end
                        else:
                            offset_factor = 0.0   # Center
                        
                        if side == 'Left':
                            perp_dir = local_perp_xy  # outward is +perp direction for left side
                        else:
                            perp_dir = -local_perp_xy  # outward is -perp direction for right side
                        
                        cant_ds_pos = cant_pos.copy()
                        cant_ds_pos = cant_ds_pos + perp_dir * (offset_factor * (half_cant_l - cant_ds_w / 2.0))
                        cant_ds_pos[2] = span_z + cant_h
                        
                        # Add deck_support to deck_actors to inherit transparency
                        if not hasattr(self, '_deck_actors_list'):
                            self._deck_actors_list = []
                        
                        cant_ds_actor = self._create_u_shape_span_actor(
                            {'width': cant_ds_w, 'height': cant_ds_h, 'color': (1.0, 1.0, 0.8)},
                            cant_ds_pos, cant_ds_l, render_angle_deg)
                        if cant_ds_actor:
                            self.renderer.AddActor(cant_ds_actor)
                            component_actors.append(cant_ds_actor)
                            self._deck_actors_list.append(cant_ds_actor)
                            self.message_text.append(f"    • U-Shape Cantilever Deck Support created (Position: {cant_ds_pos_type})")

            # ══════════════════════════════════════════════════════════════
            # 5b. DECK SUPPORTERS (Multiple)
            # ═══════════════════════════════════════════════════════════════
            deck_actors = []
            if 'deck_supporters' in bridge_config:
                span_top_z = span_z + span_cfg.get('height', 0.8)
                
                for i, ds_cfg in enumerate(bridge_config['deck_supporters']):
                    pos_type = ds_cfg.get('position', 'Center')
                    
                    d_val = ds_cfg.get('distance', '')
                    
                    if pos_type == 'Left':
                        # Halfway between center and left pillar, or use distance if specified
                        ds_dist = float(d_val) if d_val and str(d_val).strip() else (left_offset / 2.0)
                        ds_pos = base_point.copy() + local_perp_xy * ds_dist
                    elif pos_type == 'Right':
                        # Halfway between center and right pillar
                        ds_dist = float(d_val) if d_val and str(d_val).strip() else (right_offset / 2.0)
                        ds_pos = base_point.copy() - local_perp_xy * ds_dist
                    else:
                        ds_pos = base_point.copy()
                        
                    ds_pos[2] = span_top_z
                    
                    self.message_text.append(f"    • Deck Support #{i+1} ({pos_type}): {ds_cfg['length']}x{ds_cfg['width']}")
                    ds_actor = self._create_u_shape_span_actor(ds_cfg, ds_pos, ds_cfg['length'], render_angle_deg)
                    if ds_actor:
                        self.renderer.AddActor(ds_actor)
                        component_actors.append(ds_actor)
                        deck_actors.append(ds_actor)


            # ═══════════════════════════════════════════════════════════════
            # 5c. APPLY MATERIAL TRANSPARENCY to U-Shape component actors
            # ═══════════════════════════════════════════════════════════════
            try:
                mat_configs_u = bridge_config.get('u_shape_materials', {})
                u_actor_mat_pairs = [
                    (left_footing_actor if has_footing else None, mat_configs_u.get('footing', {})),
                    (right_footing_actor if has_footing else None, mat_configs_u.get('footing', {})),
                    (left_actor, mat_configs_u.get('left_pillar', {})),
                    (right_actor, mat_configs_u.get('right_pillar', {})),
                    (span_actor, mat_configs_u.get('span', {})),
                    (cant_actor, mat_configs_u.get('span', {})), # Cantilever uses span material
                ]
                # Add all deck supporters to material pairs
                for d_act in deck_actors:
                    u_actor_mat_pairs.append((d_act, mat_configs_u.get('deck_support', {})))
                if hasattr(self, '_deck_actors_list'):
                    for d_act in self._deck_actors_list:
                        u_actor_mat_pairs.append((d_act, mat_configs_u.get('deck_support', {})))
                    self._deck_actors_list = []

                for actor_ref, mat_cfg in u_actor_mat_pairs:
                    if actor_ref and mat_cfg:
                        tp = mat_cfg.get('transparency_percent', 0)
                        if tp > 0:
                            opacity = max(0.1, 1.0 - (tp / 100.0))
                            actor_ref.GetProperty().SetOpacity(opacity)
            except Exception:
                pass

            # ═══════════════════════════════════════════════════════════════
            # 6. REINFORCEMENT BARS for U-Shape components
            # ═══════════════════════════════════════════════════════════════
            try:
                mat_configs = bridge_config.get('u_shape_materials', {})
                
                # Footing rebar
                footing_mat = mat_configs.get('footing', {})
                if has_footing and footing_cfg and footing_mat:
                    self.add_reinforcement_for_rect_component(
                        footing_cfg, left_base, footing_cfg['color'], footing_mat, render_angle_deg)
                    self.add_reinforcement_for_rect_component(
                        footing_cfg, right_base, footing_cfg['color'], footing_mat, render_angle_deg)
                
                # Pillar rebar
                left_mat = mat_configs.get('left_pillar', {})
                if left_mat:
                    left_rect = {'length': left_dims['length'], 'width': left_dims['width'], 'height': left_dims['height']}
                    self.add_reinforcement_for_rect_component(
                        left_rect, [left_pillar_base[0], left_pillar_base[1], current_z_left],
                        left_color, left_mat, render_angle_deg)
                
                right_mat = mat_configs.get('right_pillar', {})
                if right_mat:
                    right_rect = {'length': right_dims['length'], 'width': right_dims['width'], 'height': right_dims['height']}
                    self.add_reinforcement_for_rect_component(
                        right_rect, [right_pillar_base[0], right_pillar_base[1], current_z_right],
                        right_color, right_mat, render_angle_deg)
                
                # Span rebar
                span_mat = mat_configs.get('span', {})
                if span_mat:
                    span_rect = {'length': span_total_length, 'width': span_cfg.get('width', 1.2), 'height': span_cfg.get('height', 0.8)}
                    self.add_reinforcement_for_rect_component(
                        span_rect, [span_center[0], span_center[1], span_z],
                        span_cfg['color'], span_mat, render_angle_deg)

                # Cantilever rebar
                if bridge_config.get('cantilever') and span_mat:
                    cant_cfg = bridge_config['cantilever']
                    cant_rect = {'length': cant_cfg['length'], 'width': cant_cfg['width'], 'height': cant_cfg['thickness']}
                    # Position was already calculated as cant_pos
                    self.add_reinforcement_for_rect_component(
                        cant_rect, cant_pos, span_cfg['color'], span_mat, render_angle_deg)
                
                # Multiple Deck Support rebar
                deck_mat = mat_configs.get('deck_support', {})
                if deck_mat and 'deck_supporters' in bridge_config:
                    for i, ds_cfg in enumerate(bridge_config['deck_supporters']):
                        # Re-calculate position for rebar (same logic as actor creation)
                        pos_type = ds_cfg.get('position', 'Center')
                        if pos_type == 'Left':
                            r_pos = base_point.copy() + local_perp_xy * (left_offset / 2.0)
                        elif pos_type == 'Right':
                            r_pos = base_point.copy() - local_perp_xy * (right_offset / 2.0)
                        else:
                            r_pos = base_point.copy()
                        r_pos[2] = span_z + span_cfg.get('height', 0.8)
                        
                        ds_rect = {'length': ds_cfg.get('length', 1.2), 'width': ds_cfg.get('width', 0.5), 'height': ds_cfg.get('height', 0.3)}
                        self.add_reinforcement_for_rect_component(
                            ds_rect, r_pos, ds_cfg['color'], deck_mat, render_angle_deg)

                self.message_text.append(f"    • U-Shape Reinforcement: {len(self.reinforcement_actors)} total actors")
            except Exception as re:
                self.message_text.append(f"    ⚠ U-Shape rebar warning: {str(re)}")

            # ═══════════════════════════════════════════════════════════════
            # Store and render
            # ═══════════════════════════════════════════════════════════════
            self.bridge_components[chainage_key] = {
                'config': bridge_config, 'actors': component_actors}
            self.bridge_component_actors.extend(component_actors)
            self.canvas.draw_idle()
            if hasattr(self, 'vtk_widget') and self.vtk_widget:
                render_window = self.vtk_widget.GetRenderWindow()
                if render_window:
                    self.renderer.ResetCameraClippingRange()
                    render_window.Render()
        except Exception as e:
            self.message_text.append(f"Error creating U-Shape: {e}")
            self.message_text.append(traceback.format_exc())

    def _create_u_shape_footing_actor(self, footing_cfg, center_point, base_z, angle):
        """Dedicated footing actor for U-Shape bridge"""
        cube_source = vtk.vtkCubeSource()
        cube_source.SetXLength(footing_cfg['length'])
        cube_source.SetYLength(footing_cfg['width'])
        cube_source.SetZLength(footing_cfg['height'])

        transform = vtk.vtkTransform()
        transform.Translate(center_point[0], center_point[1],
                          base_z + footing_cfg['height'] / 2.0)
        transform.RotateZ(angle)

        transform_filter = vtk.vtkTransformPolyDataFilter()
        transform_filter.SetInputConnection(cube_source.GetOutputPort())
        transform_filter.SetTransform(transform)

        mapper = vtk.vtkPolyDataMapper()
        mapper.SetInputConnection(transform_filter.GetOutputPort())

        actor = vtk.vtkActor()
        actor.SetMapper(mapper)
        actor.GetProperty().SetColor(*footing_cfg['color'])
        actor.GetProperty().SetOpacity(0.9)
        return actor

    def _create_u_shape_pillar_actor(self, dims, base_center, color, angle):
        """Dedicated rectangular pillar actor for U-Shape bridge.
        dims: dict with 'length', 'width', 'height'
        base_center: (x, y, z) where z is the bottom of the pillar"""
        cube_source = vtk.vtkCubeSource()
        cube_source.SetXLength(dims['length'])
        cube_source.SetYLength(dims['width'])
        cube_source.SetZLength(dims['height'])

        transform = vtk.vtkTransform()
        transform.Translate(base_center[0], base_center[1],
                          base_center[2] + dims['height'] / 2.0)
        transform.RotateZ(angle)

        transform_filter = vtk.vtkTransformPolyDataFilter()
        transform_filter.SetInputConnection(cube_source.GetOutputPort())
        transform_filter.SetTransform(transform)

        mapper = vtk.vtkPolyDataMapper()
        mapper.SetInputConnection(transform_filter.GetOutputPort())

        actor = vtk.vtkActor()
        actor.SetMapper(mapper)
        actor.GetProperty().SetColor(*color)
        actor.GetProperty().SetOpacity(0.95)
        return actor

    def _create_u_shape_span_actor(self, span_cfg, center_point, total_length, angle):
        """Dedicated span actor for U-Shape bridge.
        Stretches across the full distance between pillar outer edges."""
        cube_source = vtk.vtkCubeSource()
        # Userterminology swap: 'length' is along road (input), 'width' is across road (input)
        # FOR U-SHAPE SPAN:
        # XLength -> ACROSS ROAD (total_length auto-calculated)
        # YLength -> ALONG ROAD (span_cfg['width'] user input)
        cube_source.SetXLength(total_length)      # Across Road
        cube_source.SetYLength(span_cfg['width'])  # Along Road
        cube_source.SetZLength(span_cfg['height'])

        transform = vtk.vtkTransform()
        transform.Translate(center_point[0], center_point[1],
                          center_point[2] + span_cfg['height'] / 2.0)
        transform.RotateZ(angle)

        transform_filter = vtk.vtkTransformPolyDataFilter()
        transform_filter.SetInputConnection(cube_source.GetOutputPort())
        transform_filter.SetTransform(transform)

        mapper = vtk.vtkPolyDataMapper()
        mapper.SetInputConnection(transform_filter.GetOutputPort())

        actor = vtk.vtkActor()
        actor.SetMapper(mapper)
        actor.GetProperty().SetColor(*span_cfg['color'])
        actor.GetProperty().SetOpacity(0.9)
        return actor

    def create_l_shape_components(self, bridge_config, base_point, chainage_key):
        """Create L-Shape bridge components with dedicated actors:
        Footing (bottom), Vertical Pillar, Cantilever Span"""
        try:
            component_actors = []
            
            # --- GET EXACT BASE POINT AND TANGENT ANGLE AT THIS CHAINAGE ---
            ch_x_pos = bridge_config['chainage_km'] * 1000 + bridge_config['chainage_m'] - getattr(self, 'zero_start_chainage', 0.0)
            _, current_dir, _ = self.get_path_transformation_at_chainage(ch_x_pos)

            # Use saved angle to prevent zigzagging
            path_angle = float(bridge_config.get('path_rotation_deg', 0.0))
            
            # We add 90 degrees so that the X-dimension (length) points across the road (perpendicular)
            # while the Y-dimension (width) points along the road.
            render_angle_deg = path_angle + 90.0

            # Reconstruct the exact left perpendicular vector using the saved angle
            path_angle_rad = np.radians(path_angle)
            saved_dir_x = np.cos(path_angle_rad)
            saved_dir_y = np.sin(path_angle_rad)
            
            # Calculate true local perpendicular vector (Left-Facing by nature)
            perp_xy = np.array([-saved_dir_y, saved_dir_x, 0.0])

            # Override traditional "captured" angle with perpendicular alignment
            angle_deg = render_angle_deg
            current_z = float(base_point[2])

            self.message_text.append(f"      L-Shape Original angle: {path_angle:.2f}°")
            # 1. Footing (Always directly below the pillar)
            has_footing = bridge_config.get('has_footing', False)
            footing_actor = None
            if has_footing:
                footing_cfg = bridge_config['footing']
                vert_offset = bridge_config['vertical_pillar']['offset']
                footing_base = base_point.copy() + perp_xy * vert_offset
                footing_actor = self._create_l_shape_footing_actor(
                    footing_cfg, footing_base, current_z, angle_deg)
                if footing_actor:
                    self.renderer.AddActor(footing_actor)
                    component_actors.append(footing_actor)
                    current_z += footing_cfg['height']
                    self.message_text.append(f"    • L-Shape Footing created below pillar at offset={vert_offset}")

            # 2. Vertical Pillar
            vert_offset = bridge_config['vertical_pillar']['offset']
            vert_dims = bridge_config['vertical_pillar']['dimensions']
            vert_center = base_point.copy() + perp_xy * vert_offset
            vert_center[2] = current_z
            vert_color = bridge_config['vertical_pillar']['color']
            vert_actor = self._create_l_shape_pillar_actor(vert_dims, vert_center, vert_color, angle_deg)
            if vert_actor:
                self.renderer.AddActor(vert_actor)
                component_actors.append(vert_actor)
                self.message_text.append(f"    • L-Shape Vertical Pillar created (offset={vert_offset})")

            # 3. Cantilever Span (extends horizontally from top of pillar)
            pillar_height = vert_dims['height']
            span_cfg = bridge_config['span']
            span_z = current_z + pillar_height
            
            # Position span at top of pillar, extending based on direction
            direction_factor = -1.0 if span_cfg.get('direction') == 'Center' else 1.0
            
            # REFINED GEOMETRY: Total Width = User Width + Pillar Width
            # This ensures the span fully covers the pillar top AND extends by the user-requested width.
            pillar_w = vert_dims['width']
            user_extension_w = span_cfg['width']
            total_span_width = user_extension_w + pillar_w
            
            # Position span_center such that one edge is flush with the pillar side
            # Offset from pillar center = (total_width / 2 - pillar_width / 2) * direction
            # This simplifies to (user_extension_width / 2) * direction
            center_shift = (user_extension_w / 2.0) * direction_factor
            
            span_center = vert_center.copy()
            span_center += perp_xy * center_shift
            span_center[2] = span_z
            span_color = span_cfg['color']
            
            span_actor = self._create_l_shape_cantilever_actor(span_cfg, span_center, span_color, angle_deg, total_span_width)
            if span_actor:
                self.renderer.AddActor(span_actor)
                component_actors.append(span_actor)
                self.message_text.append(f"    • L-Shape Cantilever Span created {span_cfg.get('direction')} (Total Width={total_span_width:.2f}m)")

            # 4. DECK SUPPORT
            deck_actor = None
            if 'deck_support' in bridge_config:
                deck_cfg = bridge_config['deck_support']
                
                # Span's center point and height are available as span_center, span_cfg['height']
                span_top_z = span_z + span_cfg.get('height', 0.8)
                
                # Deck Support Center
                deck_center = [span_center[0], span_center[1], span_top_z]

                self.message_text.append(f"    • Deck Support: {deck_cfg['length']}x{deck_cfg['width']} H:{deck_cfg['height']}")
                
                # Re-using the cantilever actor creator because it's a simple rectangle
                deck_actor = self._create_l_shape_cantilever_actor(deck_cfg, deck_center, deck_cfg['color'], angle_deg, deck_cfg['width'])
                if deck_actor:
                    self.renderer.AddActor(deck_actor)
                    component_actors.append(deck_actor)


            # ═══════════════════════════════════════════════════════════════
            # APPLY MATERIAL TRANSPARENCY to L-Shape component actors
            # ═══════════════════════════════════════════════════════════════
            try:
                mat_configs_l = bridge_config.get('l_shape_materials', {})
                l_actor_mat_pairs = [
                    (footing_actor if has_footing else None, mat_configs_l.get('footing', {})),
                    (vert_actor, mat_configs_l.get('vertical_pillar', mat_configs_l.get('pillar', {}))),
                    (span_actor, mat_configs_l.get('span', mat_configs_l.get('cantilever_span', {}))),
                    (deck_actor, mat_configs_l.get('deck_support', {})),
                ]
                for actor_ref, mat_cfg in l_actor_mat_pairs:
                    if actor_ref and mat_cfg:
                        tp = mat_cfg.get('transparency_percent', 0)
                        if tp > 0:
                            opacity = max(0.1, 1.0 - (tp / 100.0))
                            actor_ref.GetProperty().SetOpacity(opacity)
            except Exception:
                pass

            # ═══════════════════════════════════════════════════════════════
            # REINFORCEMENT BARS for L-Shape components
            # ═══════════════════════════════════════════════════════════════
            try:
                mat_configs = bridge_config.get('l_shape_materials', {})
                
                # Footing rebar
                footing_mat = mat_configs.get('footing', {})
                if bridge_config.get('has_footing') and footing_cfg and footing_mat:
                    footing_base_pt = footing_base.copy()
                    footing_base_pt[2] = current_z - footing_cfg['height']
                    self.add_reinforcement_for_rect_component(
                        footing_cfg, footing_base_pt, footing_cfg['color'],
                        footing_mat, angle_deg)
                
                # Vertical Pillar rebar
                vert_mat = mat_configs.get('vertical_pillar', mat_configs.get('pillar', {}))
                if vert_mat:
                    vert_rect = {'length': vert_dims['length'], 'width': vert_dims['width'], 'height': vert_dims['height']}
                    self.add_reinforcement_for_rect_component(
                        vert_rect, [vert_center[0], vert_center[1], vert_center[2]],
                        vert_color, vert_mat, angle_deg)
                
                # Cantilever Span rebar
                span_mat = mat_configs.get('span', mat_configs.get('cantilever_span', {}))
                if span_mat:
                    span_rect = {'length': span_cfg['length'], 'width': total_span_width, 'height': span_cfg['height']}
                    self.add_reinforcement_for_rect_component(
                        span_rect, [span_center[0], span_center[1], span_center[2]],
                        span_color, span_mat, angle_deg)
                
                # Deck Support rebar
                deck_mat = mat_configs.get('deck_support', {})
                if deck_mat and 'deck_support' in bridge_config:
                    deck_cfg = bridge_config['deck_support']
                    deck_rect = {'length': deck_cfg.get('length', 1.0), 'width': deck_cfg.get('width', 1.0), 'height': deck_cfg.get('height', 0.3)}
                    self.add_reinforcement_for_rect_component(
                        deck_rect, deck_center,
                        deck_cfg['color'], deck_mat, angle_deg)

                self.message_text.append(f"    • L-Shape Reinforcement: {len(self.reinforcement_actors)} total actors")
            except Exception as re:
                self.message_text.append(f"    ⚠ L-Shape rebar warning: {str(re)}")

            self.bridge_components[chainage_key] = {'config': bridge_config, 'actors': component_actors}
            self.bridge_component_actors.extend(component_actors)
            self.canvas.draw_idle()
            if hasattr(self, 'vtk_widget') and self.vtk_widget:
                render_window = self.vtk_widget.GetRenderWindow()
                if render_window:
                    self.renderer.ResetCameraClippingRange()
                    render_window.Render()
        except Exception as e:
            self.message_text.append(f"Error creating L-Shape: {e}")
            self.message_text.append(traceback.format_exc())

    def _create_l_shape_footing_actor(self, footing_cfg, center_point, base_z, angle):
        """Dedicated footing actor for L-Shape bridge"""
        cube_source = vtk.vtkCubeSource()
        cube_source.SetXLength(footing_cfg['length'])
