    def load_bridge_components_from_json(self, layer_path):
        """
        Load bridge components from JSON and recreate:
          - 3D VTK actors
          - 2D construction dots (red circles on the zero/projection line)
          - 2D labels (above the graph, yellow bg, dark red text)
        """
        try:
            components = None
            try:
                from json_manager import load_from_master_config
                components = load_from_master_config(layer_path, "Bridge_components")
            except Exception as e:
                print(f"Failed to load from master config: {e}")

            if components is None:
                bridge_file_path = os.path.join(layer_path, 'bridge_components.json')
                if not os.path.exists(bridge_file_path):
                    self.message_text.append(f"  • No bridge_components.json found → nothing to restore")
                    return
                with open(bridge_file_path, 'r', encoding='utf-8') as f:
                    components = json.load(f)

            if not components:
                self.message_text.append(f"  • bridge_components.json is empty")
                return

            self.message_text.append(f"  → Loading {len(components)} bridge component(s)...")

            # ─── Clear previous 2D construction dots & labels ───────────────────────
            if hasattr(self, 'construction_dot_scatter') and self.construction_dot_scatter:
                try:
                    self.construction_dot_scatter.remove()
                except:
                    pass
                self.construction_dot_scatter = None

            if hasattr(self, 'construction_dot_labels') and self.construction_dot_labels:
                for artist in self.construction_dot_labels:
                    try:
                        artist.remove()
                    except:
                        pass
                self.construction_dot_labels.clear()
            else:
                self.construction_dot_labels = []

            # Prepare data for scatter (dots) and text (labels)
            x_positions = []
            labels_data = []

            # ─── Process each saved bridge component ────────────────────────────────
            for idx, comp in enumerate(components, 1):
                try:
                    # Get construction dot name
                    dot_name = comp.get('construction_dot', f'P{idx}')
                    
                    # 1. Rebuild config for 3D (dynamically recalculating X, Y along the projection line)
                    chainage_total_m = float(comp.get('chainage_km', 0)) * 1000 + float(comp.get('chainage_m', 0))
                    ch_x_pos = chainage_total_m - getattr(self, 'zero_start_chainage', 0.0)
                    
                    # Load exact coordinates directly from the saved JSON.
                    # This ensures the bridge perfectly aligns with the projection line,
                    # which is also rendered using its saved JSON coordinates.
                    coords = comp.get('coordinates_3d', {})
                    point_3d = [
                        float(coords.get('x', 0.0)),
                        float(coords.get('y', 0.0)),
                        float(coords.get('z', 0.0))
                    ]
                    dynamic_rot_deg = float(comp.get('path_rotation_deg', 0.0))

                    # ===== STORE FULL COMPONENT DATA FOR LATER RETRIEVAL =====
                    # Ensure the loaded component data keeps the original exact 3D coords and rotation
                    comp_copy = dict(comp)
                    comp_copy['coordinates_3d'] = {'x': point_3d[0], 'y': point_3d[1], 'z': point_3d[2]}
                    comp_copy['path_rotation_deg'] = dynamic_rot_deg
                    self.loaded_bridge_components_data[dot_name] = comp_copy

                    # Determine long_type for proper handling
                    long_type = comp.get('long_type', '')

                    # Only access comp['pillar'] for Normal bridge type
                    # U-Shape has left_pillar/right_pillar, L-Shape has vertical_pillar
                    if long_type not in ('U Shape Pillar', 'L Shape Pillar') and 'pillar' in comp:
                        pillar_dims = comp['pillar'].get('dimensions', {})
                        pillar_type_lower = str(comp['pillar'].get('type', 'circular')).lower()

                    # Rebuild bridge_config from saved data
                    bridge_config = {
                        'chainage_km': float(comp.get('chainage_km', 0)),
                        'chainage_m': float(comp.get('chainage_m', 0)),
                        'coordinates_3d': point_3d,
                        'bridge_type': comp.get('bridge_type', 'long'),
                        'long_type': long_type,
                        'pillar_name': comp.get('pillar_name', ''),
                        'has_footing': comp.get('has_footing', False),
                        'has_pile': comp.get('has_pile', False)
                    }

                    # Dynamically add all relevant component dictionaries
                    component_keys = [
                        'base', 'pillar', 'span', 'deck_support', 
                        'footing', 'left_pillar', 'right_pillar',
                        'vertical_pillar', 'cantilever_span',
                        'materials', 'u_shape_materials', 'l_shape_materials',
                        'deck_supporters', 'cantilever'
                    ]
                    for ck in component_keys:
                        if ck in comp:
                            import copy
                            bridge_config[ck] = copy.deepcopy(comp[ck])
                            
                    # Force dynamic recalculation of path rotation
                    bridge_config['path_rotation_deg'] = dynamic_rot_deg

                    # Create 3D actors using the reconstructed config
                    self.create_bridge_components(bridge_config)


                    # 2. Calculate x-position on 2D graph
                    chainage_total_m = float(comp['chainage_km']) * 1000 + float(comp['chainage_m'])
                    x_pos = chainage_total_m - getattr(self, 'zero_start_chainage', 0.0)

                    # Store for scatter
                    x_positions.append(x_pos)

                    # Store label data
                    labels_data.append({
                        'x': x_pos,
                        'text': dot_name,
                        'point_number': int(dot_name[1:]) if dot_name.startswith('P') else idx,
                        'dot_name': dot_name  # ===== ADD CONSTRUCTION DOT NAME =====
                    })

                    self.message_text.append(
                        f"    ✓ Restored bridge {dot_name} @ chainage {chainage_total_m:.2f}m "
                        f"(graph x = {x_pos:.2f})"
                    )

                except Exception as e:
                    self.message_text.append(f"    ✗ Failed component {idx}: {str(e)}")
                    self.message_text.append(traceback.format_exc())

            # ─── Draw red dots on the projection line (for bridge mode) ─────────────────────
            if x_positions:
                # Get Y values from projection line for each X position
                y_positions = []
                for x_pos in x_positions:
                    # Convert x_pos back to actual chainage
                    actual_chainage = x_pos + getattr(self, 'zero_start_chainage', 0.0)
                    # Get Y value from projection line (pass layer_path to load from JSON if needed)
                    y_val = self.get_projection_line_y_at_chainage(actual_chainage, layer_path=layer_path)
                    y_positions.append(y_val)
                
                self.construction_dot_scatter = self.ax.scatter(
                    x_positions,
                    y_positions,                         # Use projection line Y values instead of [0.0]
                    s=140,                               # size
                    color='red',
                    edgecolor='darkred',
                    linewidth=1.8,
                    zorder=30,
                    picker=True
                )

                # Attach metadata to scatter points
                if hasattr(self.construction_dot_scatter, 'set_urls'):
                    self.construction_dot_scatter.set_urls([f"construction_dot_{i}" for i in range(len(x_positions))])

            # Draw labels above dots
            label_offset = 0.4
            for label_info in labels_data:
                actual_ch = label_info['x'] + getattr(self, 'zero_start_chainage', 0.0)
                y_pos = self.get_projection_line_y_at_chainage(actual_ch, layer_path=layer_path)
                txt = self.ax.text(label_info['x'], y_pos + label_offset, label_info['text'],
                    fontsize=13, fontweight='bold', color='darkred', ha='center', va='bottom',
                    bbox=dict(boxstyle="round,pad=0.45", fc="yellow", ec="darkred", lw=1.5, alpha=0.92),
                    zorder=35, picker=True)
                txt.point_data = {'type': 'construction_dot', 'point_number': label_info['point_number'], 'x': label_info['x'], 'y': y_pos, 'dot_name': label_info['dot_name']}
                self.construction_dot_labels.append(txt)
            self.canvas.draw_idle()
            self.message_text.append("  ✓ All bridge components restored")
        except Exception as e:
            self.message_text.append(f"✗ Error loading bridge components: {str(e)}")
            self.message_text.append(traceback.format_exc())

    def open_deck_config_dialog(self, deck_label, p1_name=None, p2_name=None):
        """Called when user clicks D1 / D2 label"""
        if p1_name is None or p2_name is None:
            if deck_label in self.deck_components:
                p1_name = self.deck_components[deck_label]['p1']
                p2_name = self.deck_components[deck_label]['p2']
            else:
                return

        p1 = self.loaded_bridge_components_data.get(p1_name, {})
        p2 = self.loaded_bridge_components_data.get(p2_name, {})

        p1_ch_str = f"KM {p1.get('chainage_km', 0)} + {p1.get('chainage_m', 0):.2f}m"
        p2_ch_str = f"KM {p2.get('chainage_km', 0)} + {p2.get('chainage_m', 0):.2f}m"

        distance = abs(
            (p2.get('chainage_km', 0) * 1000 + p2.get('chainage_m', 0)) -
            (p1.get('chainage_km', 0) * 1000 + p1.get('chainage_m', 0))
        )

        loaded = self.loaded_decks_data.get(deck_label)
        
        # If no saved data exists for this deck, try to auto-detect curve configuration from projection line
        if not loaded:
            p1_ch = p1.get('chainage_km', 0) * 1000 + p1.get('chainage_m', 0)
            p2_ch = p2.get('chainage_km', 0) * 1000 + p2.get('chainage_m', 0)
            mid_ch = (p1_ch + p2_ch) / 2.0
            
            best_match = None
            min_dist = float('inf')
            
            if hasattr(self, 'curve_labels'):
                for curve in self.curve_labels:
                    c_ch = curve.get('chainage', 0.0)
                    d = abs(c_ch - mid_ch)
                    if d < min_dist:
                        min_dist = d
                        best_match = curve
            
            # If a curve label is found within reasonable distance, pre-fill dialog
            if best_match and min_dist < (distance / 2.0 + 5.0):
                c_cfg = best_match.get('config', {})
                loaded = {
                    'curve_angle': c_cfg.get('angle', 0.0),
                    'inner_curve': c_cfg.get('inner_curve', False),
                    'outer_curve': c_cfg.get('outer_curve', True)
                }
                self.message_text.append(f"ℹ Auto-detected curve configuration from projection line for {deck_label}.")

        dialog = DeckConfigDialog(
            deck_label=deck_label,
            p1_chainage=p1_ch_str,
            p2_chainage=p2_ch_str,
            distance=distance,
            parent=self,
            loaded_data=loaded,
            p1_data=p1,
            p2_data=p2
        )

        if dialog.exec_() == QDialog.Accepted:
            config = dialog.get_configuration()
            self.save_deck_configuration(config, deck_label, p1_name, p2_name)
            self.visualize_deck_slab(config, deck_label, p1_name, p2_name)

