    def add_deck_between_pillars(self, p1_name, p2_name):
        """Automatically creates D1/D2/... label at the TOP of the 2D graph (high Y position)"""
        if p1_name not in self.loaded_bridge_components_data or p2_name not in self.loaded_bridge_components_data:
            return

        p1 = self.loaded_bridge_components_data[p1_name]
        p2 = self.loaded_bridge_components_data[p2_name]

        ch1 = p1['chainage_km'] * 1000 + p1['chainage_m']
        ch2 = p2['chainage_km'] * 1000 + p2['chainage_m']
        mid_ch = (ch1 + ch2) / 2.0

        x_mid = mid_ch - getattr(self, 'zero_start_chainage', 0.0)

        # ────────────────────────────────────────────────────────────────
        # Place label HIGH at the top of the graph (like P1/P2/P3 labels)
        # Use a fixed high Y value or calculate based on current ylim
        # ────────────────────────────────────────────────────────────────
        y_top = self.ax.get_ylim()[1] * 0.92          # 92% of the top of current view
        # Alternative fixed high value (adjust if your elevation scale is very different):
        # y_top = 3.0   # or 4.0, etc. — test what looks good above all points

        deck_num = len(self.deck_labels) + 1
        deck_label = f"D{deck_num}"

        # Avoid duplicate
        if any(txt.get_text() == deck_label for txt in self.deck_labels):
            return

        txt = self.ax.text(
            x_mid,
            y_top,                          # ← HIGH position
            deck_label,
            fontsize=14,
            fontweight='bold',
            color='#1565c0',                # nice blue
            ha='center',
            va='bottom',
            bbox=dict(
                boxstyle="round,pad=0.5",
                fc="#bbdefb",
                ec="#1976d2",
                lw=2.2,
                alpha=0.95
            ),
            zorder=45,                      # above everything else
            picker=5                        # make it easily clickable
        )

        txt.point_data = {
            'type': 'deck_label',
            'deck_label': deck_label,
            'p1_name': p1_name,
            'p2_name': p2_name,
            'mid_chainage': mid_ch
        }

        self.deck_labels.append(txt)
        self.deck_components[deck_label] = {
            'p1': p1_name,
            'p2': p2_name,
            'mid_x': x_mid,
            'mid_y': y_top,                 # store high y
            'config': None
        }

        self.canvas.draw_idle()
        self.message_text.append(f"✓ Deck label {deck_label} placed at TOP of graph between {p1_name}–{p2_name}")

