    def visualize_deck_slab(self, config, deck_label, p1_name, p2_name):
        """
        Creates deck slab between two pillars - supports BOTH straight AND curved arc geometry!
        """
        import vtk

        p1 = self.loaded_bridge_components_data.get(p1_name, {})
        p2 = self.loaded_bridge_components_data.get(p2_name, {})

        def get_cp_pos(cp):
            c3d = cp.get('coordinates_3d', {})
            return np.array([float(c3d.get('x', 0)), float(c3d.get('y', 0)), float(c3d.get('z', 0))])

        def get_h(p_obj, pk):
            try:
                b = p_obj.get('footing') or p_obj.get('base', {})
                bh = float(b.get('height') or b.get('dimensions', {}).get('height', 1.0))
                if pk == 'Right':
                    pi = p_obj.get('right_pillar') or p_obj.get('pillar', {})
                else:
                    pi = p_obj.get('left_pillar') or p_obj.get('pillar', {})
                ph = float(pi.get('height') or pi.get('dimensions', {}).get('height', 8.0))
                sp = p_obj.get('span', {})
                sh = float(sp.get('height') or sp.get('thickness') or 0.8)
                ds = p_obj.get('deck_supporters', [])
                suh = next((d for d in ds if d.get('position') == pk), ds[0]).get('height', 0.3) if ds else (p_obj.get('deck_support', {}).get('height') or 0.3)
                return bh + ph + sh + float(suh)
            except:
                return 13.0

        p1_pos = get_cp_pos(p1)
        p2_pos = get_cp_pos(p2)

        # Get curve angle
        curve_angle = float(config.get('curve_angle', 0.0))
        curve_direction = config.get('curve_direction', '')
        curve_angle = self._apply_curve_direction(curve_angle, curve_direction)
        is_curved = abs(curve_angle) >= 0.1

        # Chord direction
        chord = np.array([p2_pos[0] - p1_pos[0], p2_pos[1] - p1_pos[1]])
        chord_len = np.linalg.norm(chord)
        if chord_len < 0.01:
            return

        chord_dir = chord / chord_len

        # Perpendicular directions
        p1_angle = p1.get('path_rotation_deg')
        if p1_angle is not None:
            rad1 = np.radians(float(p1_angle))
            perp_dir1 = np.array([-np.sin(rad1), np.cos(rad1)])
        else:
            perp_dir1 = np.array([-chord_dir[1], chord_dir[0]])

        p2_angle = p2.get('path_rotation_deg')
        if p2_angle is not None:
            rad2 = np.radians(float(p2_angle))
            perp_dir2 = np.array([-np.sin(rad2), np.cos(rad2)])
        else:
            perp_dir2 = np.array([-chord_dir[1], chord_dir[0]])

        default_perp = np.array([-chord_dir[1], chord_dir[0]])
        if np.dot(perp_dir1, default_perp) < 0:
            perp_dir1 = -perp_dir1
        if np.dot(perp_dir2, default_perp) < 0:
            perp_dir2 = -perp_dir2

        # Supporter positions
        p1_sels = config.get('p1_supporter_pos', ['Center'])
        p2_sels = config.get('p2_supporter_pos', ['Center'])
        selected_positions = sorted(list(set(p1_sels) | set(p2_sels)))

        for pos_key in selected_positions:
            # Deck configs
            if config.get('deck_type') == 'Pre-cast':
                d_configs = config.get('all_deck_configs', [])
            else:
                d_configs = [{
                    'deck_width': config.get('deck_width', 8.5),
                    'deck_thickness': config.get('deck_thickness', 0.75),
                    'deck_elevation': config.get('deck_elevation', 0.0),
                    'color': (0.55, 0.55, 0.55)
                }]

            for d_cfg in d_configs:
                shape = d_cfg.get('deck_shape', 'Rectangle')
                color = d_cfg.get('color', (0.55, 0.55, 0.55))
                parallel_gap = float(config.get('parallel_deck_gap', 0.1))

                # Extract width for offset calculation
                if shape in ["Trapezoidal", "Metro Box Girder"]:
                    width = float(d_cfg.get('total_width', 10.0))
                else:
                    width = float(d_cfg.get('deck_width', 8.5))

                # Calculate offsets
                if pos_key == 'Left':
                    offset1 = ((width + parallel_gap) / 2.0)
                    offset2 = ((width + parallel_gap) / 2.0)
                elif pos_key == 'Right':
                    offset1 = -((width + parallel_gap) / 2.0)
                    offset2 = -((width + parallel_gap) / 2.0)
                else:
                    offset1 = 0.0
                    offset2 = 0.0

                offset_vec1 = np.array([perp_dir1[0] * offset1, perp_dir1[1] * offset1, 0.0])
                offset_vec2 = np.array([perp_dir2[0] * offset2, perp_dir2[1] * offset2, 0.0])

                main_start = p1_pos + offset_vec1
                main_end = p2_pos + offset_vec2

                z1_main = main_start[2] + get_h(p1, pos_key)
                z2_main = main_end[2] + get_h(p2, pos_key)

                def get_cross_section_pts(center, perp, z_base, cfg):
                    sh = cfg.get('deck_shape', 'Rectangle')
                    el = float(cfg.get('deck_elevation', 0.0))
                    if sh in ["Trapezoidal", "Metro Box Girder"]:
                        tw = float(cfg.get('total_width', 10.0))
                        iw = float(cfg.get('inner_width', 6.0))
                        bw = float(cfg.get('beam_bottom_width', 3.5))
                        dep = float(cfg.get('beam_depth', 2.2))
                        st = float(cfg.get('slab_thickness', 0.25))
                        y_vals = [-bw/2, bw/2, iw/2, tw/2, tw/2, -tw/2, -tw/2, -iw/2]
                        z_vals = [0, 0, dep-st, dep-st, dep, dep, dep-st, dep-st]
                        return [np.array([center[0] + perp[0]*y, center[1] + perp[1]*y, z_base + el + z]) for y, z in zip(y_vals, z_vals)]
                    else:
                        w = float(cfg.get('deck_width', 8.5))
                        t = float(cfg.get('deck_thickness', 0.75))
                        y_vals = [-w/2, w/2, w/2, -w/2]
                        z_vals = [0, 0, t, t]
                        return [np.array([center[0] + perp[0]*y, center[1] + perp[1]*y, z_base + el + z]) for y, z in zip(y_vals, z_vals)]

                def draw_segment(pts1, pts2, color_rgb):
                    n = len(pts1)
                    v_points = vtk.vtkPoints()
                    for p in pts1: v_points.InsertNextPoint(*p)
                    for p in pts2: v_points.InsertNextPoint(*p)
                    v_polys = vtk.vtkCellArray()
                    for i in range(n):
                        q = vtk.vtkQuad()
                        q.GetPointIds().SetId(0, i); q.GetPointIds().SetId(1, (i+1)%n)
                        q.GetPointIds().SetId(2, n + (i+1)%n); q.GetPointIds().SetId(3, n + i)
                        v_polys.InsertNextCell(q)
                    for base in [0, n]:
                        cap = vtk.vtkPolygon()
                        cap.GetPointIds().SetNumberOfIds(n)
                        if base == 0:
                            for i in range(n): cap.GetPointIds().SetId(i, n - 1 - i)
                        else:
                            for i in range(n): cap.GetPointIds().SetId(i, n + i)
                        v_polys.InsertNextCell(cap)
                    p_data = vtk.vtkPolyData()
                    p_data.SetPoints(v_points); p_data.SetPolys(v_polys)
                    mapper = vtk.vtkPolyDataMapper()
                    mapper.SetInputData(p_data)
                    actor = vtk.vtkActor()
                    actor.SetMapper(mapper)
                    actor.GetProperty().SetColor(*color_rgb)
                    actor.GetProperty().SetOpacity(0.95)
                    self.renderer.AddActor(actor)
                    self.deck_actors.append(actor)

                # ═══════════════════════════════════════════════════════════
                # DRAW DECK - STRAIGHT OR CURVED
                # ═══════════════════════════════════════════════════════════
                if is_curved:
                    theta = np.deg2rad(curve_angle)
                    half_theta = abs(theta) / 2.0
                    R = chord_len / (2.0 * np.sin(half_theta))
                    h = R * np.cos(half_theta)
                    U = chord_dir
                    N = np.array([-U[1], U[0]])
                    arc_center = (main_start[:2] + main_end[:2]) / 2.0 + (h if theta > 0 else -h) * N
                    v1, v2 = main_start[:2] - arc_center, main_end[:2] - arc_center
                    a_start, a_end = np.atan2(v1[1], v1[0]), np.atan2(v2[1], v2[0])
                    if theta > 0:
                        while a_end < a_start: a_end += 2.0 * np.pi
                    else:
                        while a_end > a_start: a_end -= 2.0 * np.pi
                    num_segs = max(50, int(abs(curve_angle) * 2))
                    for idx in range(num_segs):
                        t1, t2 = idx/float(num_segs), (idx+1)/float(num_segs)
                        ang1, ang2 = a_start + t1*(a_end-a_start), a_start + t2*(a_end-a_start)
                        z1_seg, z2_seg = z1_main + t1*(z2_main-z1_main), z1_main + t2*(z2_main-z1_main)
                        c1 = arc_center + R * np.array([np.cos(ang1), np.sin(ang1)])
                        c2 = arc_center + R * np.array([np.cos(ang2), np.sin(ang2)])
                        r1, r2 = np.array([np.cos(ang1), np.sin(ang1)]), np.array([np.cos(ang2), np.sin(ang2)])
                        draw_segment(get_cross_section_pts(c1, r1, z1_seg, d_cfg), get_cross_section_pts(c2, r2, z2_seg, d_cfg), color)
                else:
                    start_offset = float(config.get('start_deck_offset', 0.0))
                    end_offset = float(config.get('end_deck_offset', 0.0))
                    slope = (z2_main - z1_main) / chord_len if chord_len > 0.001 else 0.0
                    draw_segment(get_cross_section_pts(main_start[:2], perp_dir1, z1_main, d_cfg), get_cross_section_pts(main_end[:2], perp_dir2, z2_main, d_cfg), color)
                    
                    if start_offset > 0.0 or end_offset > 0.0:
                        start_angle, end_angle = float(config.get('start_offset_angle', 0.0)), float(config.get('end_offset_angle', 0.0))
                        start_dir, end_dir = config.get('start_offset_direction', 'Straight'), config.get('end_offset_direction', 'Straight')
                        def get_ang_rad(deg, dir): return np.radians(-deg) if dir == 'Left' else (np.radians(deg) if dir == 'Right' else 0.0)
                        def rot_2d(v, rad):
                            cos_t, sin_t = np.cos(rad), np.sin(rad)
                            return np.array([v[0]*cos_t - v[1]*sin_t, v[0]*sin_t + v[1]*cos_t])
                        s_ang_rad, e_ang_rad = get_ang_rad(start_angle, start_dir), get_ang_rad(end_angle, end_dir)
                        s_vec, e_vec = rot_2d(-chord_dir, s_ang_rad), rot_2d(chord_dir, e_ang_rad)
                        p_start, p_end = rot_2d(perp_dir1, s_ang_rad), rot_2d(perp_dir2, e_ang_rad)
                        if start_offset > 0.0:
                            c_ext = main_start + np.array([s_vec[0]*start_offset, s_vec[1]*start_offset, 0.0])
                            z_ext = z1_main - (start_offset * slope)
                            draw_segment(get_cross_section_pts(c_ext[:2], p_start, z_ext, d_cfg), get_cross_section_pts(main_start[:2], perp_dir1, z1_main, d_cfg), color)
                        if end_offset > 0.0:
                            c_ext = main_end + np.array([e_vec[0]*end_offset, e_vec[1]*end_offset, 0.0])
                            z_ext = z2_main + (end_offset * slope)
                            draw_segment(get_cross_section_pts(main_end[:2], perp_dir2, z2_main, d_cfg), get_cross_section_pts(c_ext[:2], p_end, z_ext, d_cfg), color)


        if hasattr(self, 'vtk_widget'):
            self.vtk_widget.GetRenderWindow().Render()

