    def visualize_lane_markings(self, data_input, clear_existing=True, layer_path=None):
        """Render white lane marking lines on top of the road surface baseline"""
        if clear_existing:
            self.clear_lane_markings()
        
        # 1. Prepare Lane Configurations
        # data_input can be a single dict (Page 1) or a list of dicts (Drop Lanes/Page 2)
        configs = data_input if isinstance(data_input, list) else [data_input]

        # Sort configurations by start chainage to ensure proper gap detection
        def get_start_ch(c):
             for k in ['from_chainage_rel', 'from_chainage', 'from_abs_m']:
                 val = c.get(k)
                 if val is not None: return float(val)
             return 0.0
        
        configs_to_process = sorted(configs, key=get_start_ch)

        # Helper to calculate offsets for a given config
        def calc_offsets(config):
            center_w = float(config.get('center_lane_width', config.get('center_lane_width_m', 0.0)))
            off_l = center_w / 2.0
            off_r = center_w / 2.0
            n_left = int(config.get('lanes_left', 0))
            n_right = int(config.get('lanes_right', 0))
            width = float(config.get('lane_width_m', 3.5))
            shoulder_l = config.get('hard_shoulder_left', False)
            shoulder_r = config.get('hard_shoulder_right', False)
            shoulder_width_l = float(config.get('Left shoulder lane width', config.get('shoulder_width_m', 2.5)))
            shoulder_width_r = float(config.get('Right shoulder lane width', config.get('shoulder_width_m', 2.5)))
            
            center_style = config.get('center_lane_style', 'Continuous')
            
            offsets = {'left': [], 'right': []}
            
            # Left
            if n_left > 0 or off_l > 0: 
                offsets['left'].append({'off': off_l, 'type': 'Inner', 'color': 'White', 'style': center_style})
            
            curr_l = off_l
            for i in range(1, n_left + 1):
                l_width = float(config.get(f"Left Lane {i} Width", config.get(f"Left Lane {i} width", width)))
                l_style = config.get(f"Left Lane {i} Style", config.get(f"Left Lane {i} style", "Dashed"))
                curr_l += l_width
                is_outer = (i == n_left)
                # Shoulder inner edge must be Continuous
                outer_style = 'Continuous' if (is_outer and shoulder_l) else l_style
                offsets['left'].append({'off': curr_l, 'type': 'Divider' if not is_outer else 'Outer', 'color': 'White', 'style': outer_style})
            
            if shoulder_l:
                offsets['left'].append({'off': curr_l + shoulder_width_l, 'type': 'Shoulder', 'color': 'Yellow', 'style': config.get("Left Shoulder Style", "Continuous")})
                
            # Right
            if n_right > 0 or off_r > 0: 
                offsets['right'].append({'off': -off_r, 'type': 'Inner', 'color': 'White', 'style': center_style})
            
            curr_r = off_r
            for i in range(1, n_right + 1):
                r_width = float(config.get(f"Right Lane {i} Width", config.get(f"Right Lane {i} width", width)))
                r_style = config.get(f"Right Lane {i} Style", config.get(f"Right Lane {i} style", "Dashed"))
                curr_r += r_width
                is_outer = (i == n_right)
                # Shoulder inner edge must be Continuous
                outer_style = 'Continuous' if (is_outer and shoulder_r) else r_style
                offsets['right'].append({'off': -curr_r, 'type': 'Divider' if not is_outer else 'Outer', 'color': 'White', 'style': outer_style})
            
            if shoulder_r:
                offsets['right'].append({'off': -(curr_r + shoulder_width_r), 'type': 'Shoulder', 'color': 'Yellow', 'style': config.get("Right Shoulder Style", "Continuous")})
                
            return offsets

        # Helper to prepare actor data
        line_width = 0.15
        interval = 3.0
        def make_lane_data(offset, color='White', style='Continuous', w=line_width, ch_start=None, ch_end=None, offset_end=None, z_bias=0.02):
            d = {
                'offset': offset,
                'width': w,
                'color': color,
                'style': style,
                'interval': interval,
                'z_bias': z_bias
            }
            if config.get('layer_folder'):
                d['layer_path'] = config['layer_folder']
            elif layer_path:
                d['layer_path'] = layer_path
            if ch_start is not None: d['start_chainage'] = ch_start
            if ch_end is not None: d['end_chainage'] = ch_end
            if offset_end is not None:
                 d['offset_start'] = offset
                 d['offset_end'] = offset_end
            return d

        # 1. First Pass: Render Sections
        static_configs_data = []
        base_z_bias = 0.08  # Increased base z-bias to ensure it sits above the road
        for idx, config in enumerate(configs_to_process):
            start_ch = get_start_ch(config)
            end_ch = config.get('to_chainage_rel', config.get('to_chainage', config.get('to_abs_m', 0.0)))
            start_ch, end_ch = float(start_ch), float(end_ch)
            
            # Increment z_bias for each layer config to avoid z-fighting between markings
            current_z_bias = base_z_bias + (idx * 0.16)
            
            offsets = calc_offsets(config)
            static_configs_data.append({'start_ch': start_ch, 'end_ch': end_ch, 'offsets': offsets})
            
            for side in ['left', 'right']:
                for l_data in offsets[side]:
                    self.create_lane_line_actor(make_lane_data(
                        l_data['off'], l_data['color'], l_data['style'], ch_start=start_ch, ch_end=end_ch, z_bias=current_z_bias
                    ))

        # 2. Second Pass: Generate Tapers between sections
        for i in range(len(static_configs_data) - 1):
             c1 = static_configs_data[i]
             c2 = static_configs_data[i+1]
             
             if c2['start_ch'] > c1['end_ch'] + 0.05:
                  gap_start = c1['end_ch']
                  gap_end = c2['start_ch']
                  
                  for side in ['left', 'right']:
                       c1_lines = c1['offsets'][side]
                       c2_lines = c2['offsets'][side]
                       
                       def get_line_by_type(lines, l_type):
                            for l in lines:
                                 if l['type'] == l_type: return l
                            return None
                            
                       for l_type in ['Inner', 'Outer', 'Shoulder']:
                            l1 = get_line_by_type(c1_lines, l_type)
                            l2 = get_line_by_type(c2_lines, l_type)
                            if l1 and l2:
                                 self.create_lane_line_actor(make_lane_data(
                                     l1['off'], l1['color'], 'Continuous', ch_start=gap_start, ch_end=gap_end, offset_end=l2['off']
                                 ))

        # Trigger Render
        if hasattr(self, 'vtk_widget') and self.vtk_widget:
            self.vtk_widget.GetRenderWindow().Render()
        elif hasattr(self, 'vtkWidget') and self.vtkWidget:
            self.vtkWidget.GetRenderWindow().Render()

    def clear_lane_markings(self):
        """Remove all lane marking actors from the scene"""
        if hasattr(self, 'lane_actors'):
            if hasattr(self, 'renderer'):
                for a in self.lane_actors:
                    self.renderer.RemoveActor(a)
            self.lane_actors.clear()

