    def _open_generic_asset_dialog(self, dialog_class, asset_type, is_edit_mode=False):
        """Helper to open any street light or signal pole dialog variant"""
        if not self.construction_mode_active and not self.current_worksheet_name:
             QMessageBox.warning(self, "No Context", "Please load a worksheet/layer first.")
             return

        # Load road_surface_baseline from unified config
        layer_folder = os.path.join(self.WORKSHEETS_BASE_DIR, self.current_worksheet_name, "designs", self.current_layer_name)
        
        try:
            from json_manager import DesignConstructionManager
            road_data = DesignConstructionManager.load_baseline_from_unified(layer_folder, 'road_surface_baseline')
            
            if not road_data:
                QMessageBox.warning(self, "Missing Data", "road_surface_baseline not found in current layer.")
                return
        except Exception as e:
            print(f"Error loading road baseline: {e}")
            QMessageBox.warning(self, "Error", f"Failed to load road baseline: {e}")
            return

        dialog = dialog_class(road_surface_data=road_data, is_edit_mode=is_edit_mode, parent=self)
        if dialog.exec_() == QDialog.Accepted:
            data = dialog.get_data()
            
            # Check if this is a Drop operation
            is_drop_mode = data.get('is_drop_mode', False)
            
            if is_drop_mode:
                # Handle Drop operation for poles
                # TODO: Implement drop mode logic for poles (remove/delete poles)
                self.message_text.append(f" Drop mode for poles not yet fully implemented. Pole data: {data}")
                return
            
            # --- Angle Calculation Logic ---
            pt = data.get('point_data', {})
            if pt and ('angle' not in pt or float(pt.get('angle', 0)) == 0):
                self._calculate_missing_angle(pt, dialog.points)
            
            # --- Lane Offset Logic ---
            total_left_offset, total_right_offset = self._get_lane_offsets()
            
            # --- Action Mapping ---
            if asset_type == "street_light":
                create_func = self.create_street_light_actor
            else:
                create_func = self.create_signal_pole_actor

            if data['left_shoulder']:
                create_func(data, side='left', custom_offset=total_left_offset)
            if data['right_shoulder']:
                create_func(data, side='right', custom_offset=total_right_offset)
            if data['center']:
                create_func(data, side='center', custom_offset=0.0)

    def _calculate_missing_angle(self, pt, all_pts):
        """Helper to calculate missing angle from neighboring points"""
        try:
            target_ch = float(pt.get('chainage_m', -999))
            idx = -1
            for i, p in enumerate(all_pts):
                if abs(float(p.get('chainage_m', -999)) - target_ch) < 0.01:
                    idx = i
                    break
            
            if idx != -1:
                prev_pt = all_pts[idx-1] if idx > 0 else None
                next_pt = all_pts[idx+1] if idx < len(all_pts)-1 else None
                
                def get_xy(p):
                    if 'point' in p: return p['point'][0], p['point'][1]
                    if 'world_coordinates' in p: return p['world_coordinates'][0], p['world_coordinates'][1]
                    if 'x' in p: return p['x'], p['y']
                    return 0, 0
                
                cx, cy = get_xy(pt)
                dx, dy = 0.0, 0.0
                if next_pt:
                    nx, ny = get_xy(next_pt)
                    dx = nx - cx
                    dy = ny - cy
                elif prev_pt:
                    px, py = get_xy(prev_pt)
                    dx = cx - px
                    dy = cy - py
                    
                if abs(dx) > 1e-6 or abs(dy) > 1e-6:
                    angle = np.degrees(np.arctan2(dy, dx))
                    pt['angle'] = angle

        except Exception as e:
            print(f"Error calculating missing angle: {e}")

    def _get_lane_offsets(self):
        """Helper to fetch lane offsets from lane_marking.json"""
        subfolder = getattr(self, 'current_subfolder_type', 'designs')
        lane_file = os.path.join(self.WORKSHEETS_BASE_DIR, self.current_worksheet_name, subfolder, self.current_layer_name, "lane_marking.json")
        lane_config = {}
        if os.path.exists(lane_file):
            try:
                with open(lane_file, 'r') as f:
                    lane_config = json.load(f)
            except:
                pass
        
        try:
            l_off = float(lane_config.get('offset_left_m') or 0.0)
            r_off = float(lane_config.get('offset_right_m') or 0.0)
            n_l = int(lane_config.get('lanes_left') or 2)
            n_r = int(lane_config.get('lanes_right') or 2)
            l_width = float(lane_config.get('lane_width_m') or 3.5)
            s_width = float(lane_config.get('shoulder_width_m') or 2.5)
            
            total_left_offset = l_off + (n_l * l_width) + s_width
            total_right_offset = r_off + (n_r * l_width) + s_width
            
            # Fallback if zero
            if total_left_offset == 0: total_left_offset = 9.5
            if total_right_offset == 0: total_right_offset = 9.5
            
            return total_left_offset, total_right_offset
        except:
            return 9.5, 9.5

