    def show_simulation_panel(self):
        """Show simulation panel with sliding animation from right"""
        # Get the content widget geometry
        content_rect = self.content_widget.geometry()
        
        # Calculate positions
        panel_width = self.simulation_panel.width()
        start_x = content_rect.right()  # Start off-screen to the right
        end_x = content_rect.right() - panel_width  # End at right edge of content
        
        # Set initial position (off-screen right)
        self.simulation_panel.setGeometry(
            start_x,
            content_rect.top(),
            panel_width,
            content_rect.height()
        )
        
        # Show the panel
        self.simulation_panel.show()
        self.simulation_panel_initial_pos = QPoint(0, 0)

        # Ensure the play button is brought to front over the panel
        if hasattr(self, 'play_simulation_btn') and self.play_simulation_btn.isVisible():
            self.play_simulation_btn.raise_()

        # Create and start animation
        self.simulation_animation = QPropertyAnimation(self.simulation_panel, b"geometry")
        self.simulation_animation.setDuration(300)  # 300ms animation
        
        # Animate from off-screen right to visible position
        start_rect = QRect(start_x, content_rect.top(), panel_width, content_rect.height())
        end_rect = QRect(end_x, content_rect.top(), panel_width, content_rect.height())
        
        self.simulation_animation.setStartValue(start_rect)
        self.simulation_animation.setEndValue(end_rect)
        self.simulation_animation.setEasingCurve(QEasingCurve.OutCubic)
        self.simulation_animation.start()
        
        # Toggle UI for simulation mode
        if hasattr(self, 'two_D_frame'):
            self.two_D_frame.setVisible(False)
        if hasattr(self, 'report_frame'):
            self.report_frame.setVisible(True)
            # Populate the report data
            self.populate_simulation_report()

        # Change ONLY master design layers to dotted when simulation starts
        master_layers = ['surface', 'construction', 'road_surface', 'deck_line', 'projection_line', 'zero']
        for ltype in master_layers:
            if hasattr(self, 'line_types') and ltype in self.line_types:
                for artist in self.line_types[ltype].get('artists', []):
                    try:
                        artist.set_linestyle(':')
                    except:
                        pass
        
        if hasattr(self, 'canvas') and self.canvas:
            self.canvas.draw_idle()

