        self.simulation_animation.setStartValue(current_rect)
        self.simulation_animation.setEndValue(end_rect)
        self.simulation_animation.setEasingCurve(QEasingCurve.OutCubic)
        
        # Hide panel after animation completes
        self.simulation_animation.finished.connect(lambda: self.simulation_panel.hide())
        self.simulation_animation.start()
        
        # Restore UI when leaving simulation mode (Modified to force update)
        if hasattr(self, 'report_frame'):
            self.report_frame.setVisible(False)
        if hasattr(self, 'two_D_frame'):
            # Only restore 2D frame if worksheet is actually in 2D mode
            dimension = "2D"
