    def open_side_wall_dialog(self, is_edit_mode=False):
        self._open_road_asset_dialog(SideWallDialog, "side_wall", is_edit_mode)

    def open_footpath_dialog(self, is_edit_mode=False):
        self._open_road_asset_dialog(FootPathDialog, "footpath", is_edit_mode)

    def open_divider_dialog(self, is_edit_mode=False):
        self._open_road_asset_dialog(DividerDialog, "divider", is_edit_mode)
        
    def _open_road_asset_dialog(self, dialog_class, asset_key, is_edit_mode=False):
        if not self.construction_mode_active and not self.current_worksheet_name:
             QMessageBox.warning(self, "No Context", "Please load a worksheet/layer first.")
             return

        # Load Road Surface Data from unified config
        subfolder = getattr(self, 'current_subfolder_type', 'designs')
        layer_folder = getattr(self, 'current_design_layer_path', None)
        if not layer_folder or not os.path.exists(layer_folder):
            layer_folder = os.path.join(self.WORKSHEETS_BASE_DIR, getattr(self, 'current_worksheet_name', ''), subfolder, getattr(self, 'current_layer_name', ''))
        
        try:
            from json_manager import DesignConstructionManager
            road_data = DesignConstructionManager.load_baseline_from_unified(layer_folder, 'road_surface_baseline')
            
            if not road_data:
                QMessageBox.warning(self, "Missing Data", "road_surface_baseline not found.")
                return
        except Exception as e:
            print(f"Error loading road baseline: {e}")
            QMessageBox.warning(self, "Error", f"Failed to load road baseline: {e}")
            return

        dialog = dialog_class(road_surface_data=road_data, is_edit_mode=is_edit_mode, parent=self)
        if dialog.exec_() == QDialog.Accepted:
            data = dialog.get_data()
            
            # Check if this is a Drop operation
            is_drop_mode = data.get('is_drop_mode', False)
            
            if is_drop_mode:
                # Handle Drop (Trim Chainage) Operation
                try:
                    os.makedirs(layer_folder, exist_ok=True)
                    from json_manager import DesignConstructionManager
                    
                    selected_asset_name = data.get('lane_name', '').strip()
                    drop_from_km = int(float(data.get('from_km', 0) or 0))
                    drop_from_ch = int(float(data.get('from_chainage', 0) or 0))
                    drop_to_km = int(float(data.get('to_km', 0) or 0))
                    drop_to_ch = int(float(data.get('to_chainage', 0) or 0))
                    
                    drop_from_abs = drop_from_km * 1000 + drop_from_ch
                    drop_to_abs = drop_to_km * 1000 + drop_to_ch
                    
                    # CRITICAL: Load entire reference asset structure
                    ref_asset = DesignConstructionManager.get_reference_asset(layer_folder, asset_key)
                    if not ref_asset or not isinstance(ref_asset, dict):
                        self.message_text.append(f"  No asset structure found for {asset_key}")
                        return
                    
                    # CRITICAL: Verify the selected asset exists in the structure
                    if selected_asset_name not in ref_asset:
                        self.message_text.append(f"  Asset '{selected_asset_name}' not found in {asset_key}. Available: {list(ref_asset.keys())}")
                        return
                    
                    master_data = DesignConstructionManager.load_master(layer_folder)
                    asset_mappings = master_data.get("asset_mapping", [])
                    
                    dependent_asset_names = set()
                    linked_mappings = []
                    
                    for mapping in asset_mappings:
                        if mapping.get("ref_asset_name") == selected_asset_name or mapping.get("lane_id") == selected_asset_name:
                            if "poles" in mapping:
                                overlapping = []
                                for p in mapping["poles"]:
                                    p_abs = float(p.get("chainage_abs", 0))
                                    if drop_from_abs <= p_abs <= drop_to_abs:
                                        overlapping.append(p)
                                if overlapping:
                                    linked_name = mapping.get("title", mapping.get("pole_type", "asset"))
                                    dependent_asset_names.add(linked_name)
                                    linked_mappings.append((mapping, overlapping))
                            else:
                                map_from = int(float(mapping.get("from_km", 0) or 0)) * 1000 + int(float(mapping.get("from_chainage", 0) or 0))
                                map_to = int(float(mapping.get("to_km", 0) or 0)) * 1000 + int(float(mapping.get("to_chainage", 0) or 0))
                                if max(drop_from_abs, map_from) <= min(drop_to_abs, map_to):
                                    linked_name = mapping.get("title", mapping.get("pole_type", "asset"))
                                    dependent_asset_names.add(linked_name)
                                    linked_mappings.append((mapping, None))
                                    
                    if dependent_asset_names:
                        linked_names = ", ".join(dependent_asset_names)
                        msg_box = QMessageBox()
                        msg_box.setIcon(QMessageBox.Warning)
                        msg_box.setWindowTitle("Confirm Erase")
                        msg_text = f"You are erase the {selected_asset_name} & {selected_asset_name} has linked with the {linked_names} are you sure you want to erase the {selected_asset_name} it will be erase the {linked_names} or other assets"
                        msg_box.setText(msg_text)
                        msg_box.setStandardButtons(QMessageBox.Ok | QMessageBox.Cancel)
                        msg_box.setDefaultButton(QMessageBox.Cancel)
                        
                        if msg_box.exec_() != QMessageBox.Ok:
                            return
                        
                        updated_asset_mappings = []
                        for mapping in asset_mappings:
                            link_info = next((m for m in linked_mappings if m[0] == mapping), None)
                            if link_info:
                                _, overlapping = link_info
                                if overlapping is not None:
                                    remaining_poles = [
                                        p for p in mapping["poles"]
                                        if not (drop_from_abs <= float(p.get("chainage_abs", 0)) <= drop_to_abs)
                                    ]
                                    if remaining_poles:
                                        mapping["poles"] = remaining_poles
                                        mapping["num_poles"] = len(remaining_poles)
                                        updated_asset_mappings.append(mapping)
                                else:
                                    pass
                            else:
                                updated_asset_mappings.append(mapping)
                        
                        master_data["asset_mapping"] = updated_asset_mappings
                        DesignConstructionManager.save_master(layer_folder, master_data)
                    
                    if ref_asset and isinstance(ref_asset, dict) and selected_asset_name in ref_asset:
                        asset_data = ref_asset[selected_asset_name]
                        updated_data = False
                        
                        # Handle both dict and list formats
                        if isinstance(asset_data, dict):
                            # Single asset object - update in place
                            item_from = int(float(asset_data.get('from_chainage', 0) or 0))
                            item_to = int(float(asset_data.get('to_chainage', 0) or 0))
                            item_from_km = int(float(asset_data.get('from_km', 0) or 0))
                            item_to_km = int(float(asset_data.get('to_km', 0) or 0))
                            item_from_abs = item_from_km * 1000 + item_from
                            item_to_abs = item_to_km * 1000 + item_to
                            
                            if drop_from_abs <= item_from_abs and drop_to_abs >= item_to_abs:
                                # Drop range covers entire asset - delete it
                                del ref_asset[selected_asset_name]
                                updated_data = True
                            elif drop_to_abs > item_from_abs and drop_to_abs < item_to_abs and drop_from_abs <= item_from_abs:
                                # Trim the beginning - update from_chainage and from_km ONLY
                                new_from = drop_to_abs - (drop_to_km * 1000)
                                ref_asset[selected_asset_name]['from_chainage'] = str(int(new_from))
                                ref_asset[selected_asset_name]['from_km'] = str(drop_to_km)
                                # Set is_drop_mode to true when user performs drop operation
                                ref_asset[selected_asset_name]['is_drop_mode'] = True
                                updated_data = True
                            elif drop_from_abs > item_from_abs and drop_from_abs < item_to_abs and drop_to_abs >= item_to_abs:
                                # Trim the end - update to_chainage and to_km ONLY
                                new_to = drop_from_abs - (drop_from_km * 1000)
                                ref_asset[selected_asset_name]['to_chainage'] = str(int(new_to))
                                ref_asset[selected_asset_name]['to_km'] = str(drop_from_km)
                                # Set is_drop_mode to true when user performs drop operation
                                ref_asset[selected_asset_name]['is_drop_mode'] = True
                                updated_data = True
                            elif drop_from_abs > item_from_abs and drop_to_abs < item_to_abs:
                                # Drop in the middle - split into two segments
                                first_part = dict(asset_data)
                                first_part['to_chainage'] = str(int(drop_from_abs - (drop_from_km * 1000)))
                                first_part['to_km'] = str(drop_from_km)
                                first_part['is_drop_mode'] = True
                                
                                second_part = dict(asset_data)
                                second_part['from_chainage'] = str(int(drop_to_abs - (drop_to_km * 1000)))
                                second_part['from_km'] = str(drop_to_km)
                                second_part['is_drop_mode'] = True
                                
                                ref_asset[selected_asset_name] = [first_part, second_part]
                                updated_data = True
                        elif isinstance(asset_data, list):
                            # Multiple asset objects
                            updated_data_list = []
                            for item in asset_data:
                                item_from = int(float(item.get('from_chainage', 0) or 0))
                                item_to = int(float(item.get('to_chainage', 0) or 0))
                                item_from_km = int(float(item.get('from_km', 0) or 0))
                                item_to_km = int(float(item.get('to_km', 0) or 0))
                                item_from_abs = item_from_km * 1000 + item_from
                                item_to_abs = item_to_km * 1000 + item_to
                                
                                if drop_from_abs <= item_from_abs and drop_to_abs >= item_to_abs:
                                    # Drop range covers entire item - skip it (delete)
                                    continue
                                elif drop_to_abs > item_from_abs and drop_to_abs < item_to_abs and drop_from_abs <= item_from_abs:
                                    # Trim the beginning
                                    new_from = drop_to_abs - (drop_to_km * 1000)
                                    item['from_chainage'] = str(int(new_from))
                                    item['from_km'] = str(drop_to_km)
                                    # Set is_drop_mode to true when user performs drop operation
                                    item['is_drop_mode'] = True
                                    updated_data_list.append(item)
                                elif drop_from_abs > item_from_abs and drop_from_abs < item_to_abs and drop_to_abs >= item_to_abs:
                                    # Trim the end
                                    new_to = drop_from_abs - (drop_from_km * 1000)
                                    item['to_chainage'] = str(int(new_to))
                                    item['to_km'] = str(drop_from_km)
                                    # Set is_drop_mode to true when user performs drop operation
                                    item['is_drop_mode'] = True
                                    updated_data_list.append(item)
                                elif drop_from_abs > item_from_abs and drop_to_abs < item_to_abs:
                                    # Drop in the middle - split into two segments
                                    first_part = dict(item)
                                    first_part['to_chainage'] = str(int(drop_from_abs - (drop_from_km * 1000)))
                                    first_part['to_km'] = str(drop_from_km)
                                    first_part['is_drop_mode'] = True
                                    
                                    second_part = dict(item)
                                    second_part['from_chainage'] = str(int(drop_to_abs - (drop_to_km * 1000)))
                                    second_part['from_km'] = str(drop_to_km)
                                    second_part['is_drop_mode'] = True
                                    
                                    updated_data_list.extend([first_part, second_part])
                                else:
                                    # No overlap - keep as is
                                    updated_data_list.append(item)
                            
                            if len(updated_data_list) == 0:
                                # No items remain - delete the entire asset entry
                                del ref_asset[selected_asset_name]
                            else:
                                # CRITICAL: Replace ONLY this asset's data, preserve everything else
                                ref_asset[selected_asset_name] = updated_data_list
                            updated_data = True
                        
                        # CRITICAL: Save preserving entire structure - updates existing key only
                        if updated_data:
                            try:
                                # Load master JSON and update reference_assets directly
                                master_data = DesignConstructionManager.load_master(layer_folder)
                                if "reference_assets" not in master_data:
                                    master_data["reference_assets"] = {}
                                master_data["reference_assets"][asset_key] = ref_asset
                                ok = DesignConstructionManager.save_master(layer_folder, master_data)
                                
                                if ok:
                                    self.message_text.append(f" {data['asset_name']} ({selected_asset_name}) UPDATED with new chainage: {drop_to_km}+{drop_to_ch} to {data.get('to_km')}+{data.get('to_chainage')}")
                                    # Remove old visualization
                                    self._remove_reference_asset_visualization(asset_key, selected_asset_name)
                                    
                                    # Visualize updated fragments immediately
                                    old_path = getattr(self, 'current_design_layer_path', None)
                                    self.current_design_layer_path = layer_folder
                                    try:
                                        updated_items = ref_asset.get(selected_asset_name)
                                        if updated_items:
                                            if isinstance(updated_items, list):
                                                for sub_asset in updated_items:
                                                    lane_offset = self._compute_lane_offset_from_json(
                                                        layer_folder, sub_asset.get('lane_name', '')
                                                    )
                                                    sub_asset['lane_offset'] = lane_offset
                                                    self.visualize_road_asset(sub_asset)
                                            else:
                                                lane_offset = self._compute_lane_offset_from_json(
                                                    layer_folder, updated_items.get('lane_name', '')
                                                )
                                                updated_items['lane_offset'] = lane_offset
                                                self.visualize_road_asset(updated_items)
                                    finally:
                                        if old_path is not None:
                                            self.current_design_layer_path = old_path
                                        else:
                                            self.current_design_layer_path = layer_folder
                                else:
                                    self.message_text.append(f" Failed to save {selected_asset_name}")
                            except Exception as save_err:
                                self.message_text.append(f" Error saving drop operation: {str(save_err)}")
                        else:
                            self.message_text.append(f" No overlapping chainage in {selected_asset_name} for drop range")
                    else:
                        self.message_text.append(f"  No {selected_asset_name} found to drop")
                except Exception as e:
                    print(f"Error during drop operation: {e}")
                    self.message_text.append(f" Error dropping {data['asset_name']}: {str(e)}")
            else:
                # Handle Normal Edit/Create Operation
                try:
                    os.makedirs(layer_folder, exist_ok=True)
                    
                    #  Save strictly into design_construction_config.json (top-level reference_assets) 
                    try:
                        from json_manager import DesignConstructionManager
                        
                        # Get the lane_name to use as key (MUST be provided by dialog)
                        lane_name = data.get('lane_name', '').strip()
                        if not lane_name:
                            self.message_text.append(f" Error: Lane name is required but was not provided")
                            return
                        
                        # Load master JSON
                        master_data = DesignConstructionManager.load_master(layer_folder)
                        if "reference_assets" not in master_data or not isinstance(master_data["reference_assets"], dict):
                            master_data["reference_assets"] = {"side_wall": {}, "divider": {}, "footpath": {}}
                        
                        # Ensure the asset_key category exists and is a dict
                        if not isinstance(master_data["reference_assets"].get(asset_key), dict):
                            master_data["reference_assets"][asset_key] = {}
                        
                        # Ensure the lane_name is present in the data being saved
                        data['lane_name'] = lane_name
                        
                        # Update only this specific lane entry in the dictionary
                        master_data["reference_assets"][asset_key][lane_name] = data
                        
                        # Save the entire master JSON back
                        ok = DesignConstructionManager.save_master(layer_folder, master_data)
                        if ok:
                            self.message_text.append(f" {data['asset_name']} ({lane_name}) updated in design_construction_config.json")
                        else:
                            self.message_text.append(f" Failed to save {lane_name} to design_construction_config.json")
                            return
                    except ValueError as ve:
                        self.message_text.append(f" Validation Error: {str(ve)}")
                        return
                    except Exception as dc_e:
                        print(f"Error: could not save {asset_key} to design_construction_config.json: {dc_e}")
                        self.message_text.append(f" Error saving {asset_key}: {str(dc_e)}")
                        return

            # ========================================================================================================================   
                # # Push to API
                # asset_specs = f"width={data.get('width', 0)}, height={data.get('height', 0)}, length={data.get('length', 0)}"
                # lane_payload = {
                #     "lda_id": data.get("lane_id", ""),
                #     "asset_id": getattr(self, 'current_asset_id', ""),
                #     "asset_specifications": asset_specs
                # }
                
                # print(f"\n[API CALL] PUT: {WorksheetAPI.BASE_URL}/data/create-lane (for asset)")
                # print(f"  Payload: {lane_payload}")
                # api_resp = WorksheetAPI.update_lane(lane_payload)
                # if api_resp.get("success"):
                #     self.message_text.append(f"    Asset pushed to database successfully.")
                # else:
                #     self.message_text.append(f"    Asset API put failed: {api_resp.get('message', 'Unknown error')}")
            # ========================================================================================================================

                    #  Compute lane offset from lane_marking.json 
                    lane_offset = self._compute_lane_offset_from_json(layer_folder, data.get('lane_name', ''))
                    data['lane_offset'] = lane_offset
                    print(f"DEBUG: Computed lane_offset = {lane_offset} for lane '{data.get('lane_name', '')}'")

                    # Visualize grey rectangular actor on lane
                    old_path = getattr(self, 'current_design_layer_path', None)
                    self.current_design_layer_path = layer_folder
                    try:
                        self.visualize_road_asset(data)
                    finally:
                        if old_path is not None:
                            self.current_design_layer_path = old_path
                        else:
                            self.current_design_layer_path = layer_folder # Leave it set correctly!
                
                except Exception as e:
                    print(f"Error in asset dialog handling: {e}")
                    import traceback
                    traceback.print_exc()

    def _remove_reference_asset_visualization(self, asset_key, asset_name):
        """Remove reference asset (side_wall, divider, footpath) visualization from the 3D view."""
        try:
            # Remove actors associated with this asset
            if hasattr(self, 'renderer'):
                # Find and remove actors by matching asset name in their metadata
                actors_to_remove = []
                for actor in self.renderer.GetActors().GetLastItem():
                    if hasattr(actor, 'GetClassName'):
                        if f'{asset_key}_{asset_name}' in str(getattr(actor, 'asset_id', '')):
                            actors_to_remove.append(actor)
                
                for actor in actors_to_remove:
                    self.renderer.RemoveActor(actor)
                
        ## Mayur Wakhare 7-7-2026 
                self.vtk_widget.GetRenderWindow().Render()
                ############################################
                self.message_text.append(f" Visualization updated: {asset_name} visualization removed")
        except Exception as e:
            print(f"Warning: Could not remove visualization: {e}")

