    def _get_global_start_offset(self, layer_folder):
        """Get global start chainage offset from road_surface_baseline in unified config."""
        try:
            from json_manager import DesignConstructionManager
            baseline_data = DesignConstructionManager.load_baseline_from_unified(layer_folder, 'road_surface_baseline')
            
            if baseline_data:
                polylines = baseline_data.get("polylines", [])
                if polylines:
                    start_str = polylines[0].get("start_chainage_str", "")
                    if start_str:
                        start_str = start_str.replace(" ", "")
                        if "+" in start_str:
                            parts = start_str.split("+")
                            return float(parts[0]) * 1000 + float(parts[1])
                        else:
                            return float(start_str)
        except Exception as e:
            print(f"Warning: Could not determine global start offset: {e}")
        return 0.0

    def create_pole_actors(self, pole_positions_abs, lane_offset, ref_height, pole_height, pole_diameter, layer_folder, pole_type, cantilever_config=None, traffic_light_config=None, num_directions=1, pole_color_hex="#808080", cantilever_color_hex="#808080"):
        """Create VTK pole actors with cantilever arms and traffic lights at each chainage position."""
        import numpy as np
        import vtk
        import math

        def hex_to_rgb(hex_code):
            hex_code = hex_code.lstrip('#')
            try:
                # Convert to 0-1 scale for VTK
                return tuple(int(hex_code[i:i+2], 16) / 255.0 for i in (0, 2, 4))
            except Exception:
                return (0.5, 0.5, 0.5)

        # Load road baseline for Z-coordinates
        road_surface_points = []
        try:
            from json_manager import DesignConstructionManager
            road_data = DesignConstructionManager.load_baseline_from_unified(layer_folder, 'road_surface_baseline')
            
            if road_data:
                for poly in road_data.get("polylines", []):
                    for pt in poly.get("points", []):
                        road_surface_points.append((pt['chainage_m'], pt['relative_elevation_m']))
        except Exception as e:
            print(f"Error loading road baseline for poles: {e}")
            return

        if not road_surface_points:
            return

        road_surface_points.sort(key=lambda x: x[0])
        all_chs = [p[0] for p in road_surface_points]
        all_zs = [p[1] for p in road_surface_points]

        # Get zero line direction
        z_start = np.array(self.zero_start_point, dtype=float)
        z_end = np.array(self.zero_end_point, dtype=float)
        dir_vec = z_end - z_start
        dist = np.linalg.norm(dir_vec)
        if dist > 0:
            dir_vec /= dist
        perp = np.array([-dir_vec[1], dir_vec[0], 0.0])

        # Get global offset
        global_start_offset = self._get_global_start_offset(layer_folder)

        # Track actors
        if not hasattr(self, 'pole_actors'):
            self.pole_actors = []

        # Color based on type or dialog 
        pole_color_rgb = hex_to_rgb(pole_color_hex)
        cantilever_color_rgb = hex_to_rgb(cantilever_color_hex)

        # Cantilever defaults
        cant_diameter = 0.07
        cant_length = 2.0
        cant_angle_deg = 90  # angle from vertical (90 = horizontal)
        if cantilever_config:
            cant_diameter = float(cantilever_config.get('diameter', 0.07))
            cant_length = float(cantilever_config.get('length', 2.0))
            cant_angle_deg = float(cantilever_config.get('angle_from_vertical_deg', 90))

        # Traffic light defaults (signal_pole only)
        tl_plate_height = 3.0
        tl_plate_width = 0.5
        tl_plate_thickness = 0.2
        tl_light_radius = 0.15
        if traffic_light_config and pole_type == "signal_pole":
            tl_plate_height = float(traffic_light_config.get('plate_height', 3.0))
            tl_plate_width = float(traffic_light_config.get('plate_width', 0.5))
            tl_plate_thickness = float(traffic_light_config.get('plate_thickness', 0.2))
            tl_light_radius = float(traffic_light_config.get('light_radius', 0.15))

        cant_angle_rad = math.radians(cant_angle_deg)

        for abs_ch in pole_positions_abs:
            rel_ch = abs_ch - global_start_offset

            # Interpolate Z at this chainage
            rel_z = float(np.interp(rel_ch, all_chs, all_zs))

            # Compute 3D base position (on top of reference asset)
            base_pos = z_start + dir_vec * rel_ch + perp * lane_offset
            base_pos[2] += rel_z + ref_height + 0.05

            # 
            # 1) VERTICAL POLE (cylinder along Z)
            # 
            pole_cyl = vtk.vtkCylinderSource()
            pole_cyl.SetRadius(pole_diameter / 2.0)
            pole_cyl.SetHeight(pole_height)
            pole_cyl.SetResolution(16)
            pole_cyl.Update()

            pole_tf = vtk.vtkTransform()
            pole_tf.Translate(base_pos[0], base_pos[1], base_pos[2] + pole_height / 2.0)
            pole_tf.RotateX(90)  # Y-up  Z-up

            pole_tf_filter = vtk.vtkTransformPolyDataFilter()
            pole_tf_filter.SetInputConnection(pole_cyl.GetOutputPort())
            pole_tf_filter.SetTransform(pole_tf)
            pole_tf_filter.Update()

            pole_actor = self._convert_to_point_cloud(pole_tf_filter, pole_color_rgb, distance=0.05)

            self.renderer.AddActor(pole_actor)
            self.pole_actors.append(pole_actor)

            # 
            # 2) CANTILEVER ARM(S) + TRAFFIC LIGHT PLATE(S)
            # 
            # Pole top position
            pole_top = base_pos.copy()
            pole_top[2] += pole_height

            # Determine base inward direction: cantilever points TOWARD road center
            if lane_offset > 0:
                base_inward = -perp
            else:
                base_inward = perp

            # Define directions based on num_directions
            arm_directions_2d = []
            if num_directions == 1:
                arm_directions_2d = [base_inward]
            elif num_directions == 2:
                # Opposite sides (180 deg)
                arm_directions_2d = [base_inward, -base_inward]
            elif num_directions == 4:
                # 90 deg intervals
                arm_directions_2d = [base_inward, -base_inward, dir_vec, -dir_vec]
            else:
                arm_directions_2d = [base_inward] # Default fallback

            for arm_dir_2d in arm_directions_2d:
                # Calculate 3D cantilever direction with tilt
                cant_horiz = math.sin(cant_angle_rad)
                cant_vert = math.cos(cant_angle_rad)
                
                cant_dir_3d = arm_dir_2d * cant_horiz
                cant_dir_3d[2] = -cant_vert 

                # Normalize cantilever direction
                cant_dir_len = np.linalg.norm(cant_dir_3d)
                if cant_dir_len > 0:
                    cant_dir_3d = cant_dir_3d / cant_dir_len

                # Cantilever center position
                cant_center = pole_top + cant_dir_3d * (cant_length / 2.0)
                # Cantilever tip position
                cant_tip = pole_top + cant_dir_3d * cant_length

                # Create cantilever cylinder
                cant_cyl = vtk.vtkCylinderSource()
                cant_cyl.SetRadius(cant_diameter / 2.0)
                cant_cyl.SetHeight(cant_length)
                cant_cyl.SetResolution(16)
                cant_cyl.Update()

                # VTK cylinder is along Y axis by default. Orient to cant_dir_3d.
                y_axis = np.array([0.0, 1.0, 0.0])
                cant_dir_norm = cant_dir_3d.copy()
                rot_axis = np.cross(y_axis, cant_dir_norm)
                rot_axis_len = np.linalg.norm(rot_axis)
                dot_val = np.dot(y_axis, cant_dir_norm)

                cant_tf = vtk.vtkTransform()
                cant_tf.Translate(cant_center[0], cant_center[1], cant_center[2])
                if rot_axis_len > 1e-8:
                    rot_axis = rot_axis / rot_axis_len
                    rot_angle_deg = math.degrees(math.acos(np.clip(dot_val, -1.0, 1.0)))
                    cant_tf.RotateWXYZ(rot_angle_deg, rot_axis[0], rot_axis[1], rot_axis[2])
                elif dot_val < 0:
                    cant_tf.RotateX(180)

                cant_tf_filter = vtk.vtkTransformPolyDataFilter()
                cant_tf_filter.SetInputConnection(cant_cyl.GetOutputPort())
                cant_tf_filter.SetTransform(cant_tf)
                cant_tf_filter.Update()

                cant_actor = self._convert_to_point_cloud(cant_tf_filter, cantilever_color_rgb, distance=0.05)

                self.renderer.AddActor(cant_actor)
                self.pole_actors.append(cant_actor)

                #  Traffic Light Plate (if applicable) 
                if pole_type == "signal_pole" and traffic_light_config is not None:
                    plate_center = cant_tip.copy()
                    plate_center[2] -= tl_plate_height / 2.0 

                    plate_src = vtk.vtkCubeSource()
                    plate_src.SetXLength(tl_plate_thickness) 
                    plate_src.SetYLength(tl_plate_width)     
                    plate_src.SetZLength(tl_plate_height)    
                    plate_src.Update()

                    # Determine plate orientation
                    # Plate width (Y) should be perpendicular to arm_dir_2d to face traffic
                    # local X -> arm_dir_2d, local Y -> cross(Z, arm_dir_2d), local Z -> Z
                    plate_x = arm_dir_2d.copy()
                    plate_z = np.array([0.0, 0.0, 1.0])
                    plate_y = np.cross(plate_z, plate_x)
                    
                    plate_matrix = vtk.vtkMatrix4x4()
                    plate_matrix.Identity()
                    for r in range(3):
                        plate_matrix.SetElement(r, 0, plate_x[r])
                        plate_matrix.SetElement(r, 1, plate_y[r])
                        plate_matrix.SetElement(r, 2, plate_z[r])
                    plate_matrix.SetElement(0, 3, plate_center[0])
                    plate_matrix.SetElement(1, 3, plate_center[1])
                    plate_matrix.SetElement(2, 3, plate_center[2])

                    plate_tf = vtk.vtkTransform()
                    plate_tf.SetMatrix(plate_matrix)

                    plate_tf_filter = vtk.vtkTransformPolyDataFilter()
                    plate_tf_filter.SetInputConnection(plate_src.GetOutputPort())
                    plate_tf_filter.SetTransform(plate_tf)
                    plate_tf_filter.Update()

                    plate_actor = self._convert_to_point_cloud(plate_tf_filter, (0.15, 0.15, 0.15), opacity=0.95, distance=0.05)

                    self.renderer.AddActor(plate_actor)
                    self.pole_actors.append(plate_actor)

                    #  Lights 
                    margin = tl_light_radius + 0.1
                    light_spacing = (tl_plate_height - 2*margin) / 2.0
                    
                    # Normals for lights (front and back of plate)
                    face_normal_front = plate_y.copy()
                    face_normal_back = -plate_y.copy()

                    light_colors = {"Red": (1,0,0), "Yellow": (1,1,0), "Green": (0,1,0)}
                    for idx, (cname, rgb) in enumerate(light_colors.items()):
                        light_z = plate_center[2] + (tl_plate_height/2.0) - margin - idx*light_spacing
                        
                        for f_norm in [face_normal_front, face_normal_back]:
                            disc = vtk.vtkDiskSource()
                            disc.SetInnerRadius(0.0)
                            disc.SetOuterRadius(tl_light_radius)
                            disc.SetRadialResolution(1)
                            disc.SetCircumferentialResolution(32)
                            disc.Update()

                            disc_pos = plate_center.copy()
                            disc_pos[2] = light_z
                            disc_pos += f_norm * (tl_plate_width/2.0 + 0.01)

                            disc_tf = vtk.vtkTransform()
                            disc_tf.Translate(disc_pos[0], disc_pos[1], disc_pos[2])
                            
                            z_axis = np.array([0,0,1])
                            rot_ax = np.cross(z_axis, f_norm)
                            rot_ax_len = np.linalg.norm(rot_ax)
                            dot_v = np.dot(z_axis, f_norm)

                            if rot_ax_len > 1e-8:
                                rot_angle = math.degrees(math.acos(np.clip(dot_v, -1.0, 1.0)))
                                disc_tf.RotateWXYZ(rot_angle, rot_ax[0], rot_ax[1], rot_ax[2])
                            elif dot_v < 0:
                                disc_tf.RotateX(180)

                            disc_tf_f = vtk.vtkTransformPolyDataFilter()
                            disc_tf_f.SetInputConnection(disc.GetOutputPort())
                            disc_tf_f.SetTransform(disc_tf)
                            disc_tf_f.Update()

                            disc_a = self._convert_to_point_cloud(disc_tf_f, rgb, distance=0.05)
                            self.renderer.AddActor(disc_a)
                            self.pole_actors.append(disc_a)

        self.vtk_widget.GetRenderWindow().Render()
        self.message_text.append(f" {len(pole_positions_abs)} {pole_type.replace('_', ' ')} poles created with cantilever arms.")

