    def open_share_with_buddies_dialog(self):
        """Open the ShareWithBuddiesDialog using the current worksheets path.

        Uses `self.WORKSHEETS_BASE_DIR` if available (set by PointCloudViewer),
        otherwise falls back to a `worksheets` folder in the current working directory.
        """
        try:
            worksheets_path = getattr(self, 'WORKSHEETS_BASE_DIR', None)
            if not worksheets_path:
                worksheets_path = os.path.join(os.getcwd(), 'worksheets')
            dialog = ShareWithBuddiesDialog(worksheets_path, parent=self)
            dialog.exec_()
        except Exception as e:
            QMessageBox.critical(self, "Error", f"Failed to open Share dialog:\n{e}")   
