    def upload_construction_material_data(self):
        """
        Uploads material_construction_config.json to the server using mode=2.
        Uses the material layer ID (from Mode 3) instead of the design layer.
        """
        try:
            import json
            import os
            from API import WorksheetAPI
            from PyQt5.QtWidgets import QMessageBox

            # 1. Check if we have a current construction layer path
            if not hasattr(self, 'current_construction_layer_path') or not self.current_construction_layer_path:
                QMessageBox.warning(
                    self, "No Construction Layer",
                    "No active construction layer. Please create or select a construction layer first."
                )
                return

            # 2. Path to material_construction_config.json
            unified_file_path = os.path.join(
                self.current_construction_layer_path,
                "material_construction_config.json"
            )

            if not os.path.exists(unified_file_path):
                QMessageBox.warning(
                    self, "No Construction Data",
                    f"material_construction_config.json not found at:\n{unified_file_path}\n\n"
                    "Please add construction materials first."
                )
                return

            # 3. Load the construction material data
            with open(unified_file_path, 'r', encoding='utf-8') as rf:
                material_payload = json.load(rf)

            print(f"✓ Loaded construction material data from: {unified_file_path}")

            # 4. Get API parameters
            api_user_id = getattr(self, 'current_api_user_id', None) or \
                        getattr(self, 'current_user_id', None) or \
                        getattr(self, 'current_user', None)

            # IMPORTANT: Use material layer ID from Mode 3, NOT design layer ID
            material_layer_id = getattr(self, 'current_material_layer_id', None)
            
            # If not set, try to retrieve it from parent or fallback to design layer (with warning)
            if not material_layer_id:
                # Optionally, you could call Mode 3 again to recreate the material layer
                QMessageBox.warning(
                    self, "Missing Material Layer",
                    "Material layer ID not found. Please create a material layer first (Mode 3)."
                )
                return
            
            worksheet_id = getattr(self, 'current_worksheet_id', None) or \
                        getattr(self, 'created_worksheet_id', None)

            # 5. Validate required parameters
            if not api_user_id:
                QMessageBox.warning(self, "Missing User ID", "User ID not found. Please login.")
                return
            if not worksheet_id:
                QMessageBox.warning(self, "Missing Worksheet ID", "No worksheet selected.")
                return

            print(f"Upload parameters: user_id={api_user_id}, mode=2, layer_id={material_layer_id} (material layer), worksheet_id={worksheet_id}")

            if hasattr(self, 'message_text'):
                self.message_text.append("⏳ Uploading material construction data to server...")

            # 6. Call the API with mode=2 and the material layer ID
            resp = WorksheetAPI.update_worksheet_layer(
                api_user_id,
                2,                      # mode=2 for construction material data
                material_layer_id,      # Use material layer ID (type 2)
                worksheet_id,
                material_payload
            )

            # 7. Handle response
            if resp.get('success'):
                success_msg = f"✓ Construction material data uploaded successfully!\nMaterial Layer ID: {material_layer_id}\nWorksheet ID: {worksheet_id}"
                print(f"✓ Uploaded construction data to server (material_layer_id={material_layer_id})")
                QMessageBox.information(self, "Success", success_msg)
                if hasattr(self, 'message_text'):
                    self.message_text.append("✓ Construction data uploaded to server successfully.")
            else:
                errmsg = resp.get('message') or resp.get('text') or str(resp)
                error_msg = f"Upload failed:\n{errmsg}"
                print(f"⚠ Failed to upload construction data: {errmsg}")
                QMessageBox.warning(self, "Upload Failed", error_msg)
                if hasattr(self, 'message_text'):
                    self.message_text.append(f"⚠ Upload failed: {errmsg}")

        except Exception as e:
            error_msg = f"Unexpected error: {str(e)}"
            print(f"⚠ {error_msg}")
            QMessageBox.critical(self, "Error", error_msg)
            if hasattr(self, 'message_text'):
                self.message_text.append(f"⚠ Exception: {e}")

    def add_text_marker_on_baseline_plane(self, baseline_data, chainage_m=None,
                                      left_offset=1.5, up_offset=1.0,
                                      scale=1.5):
        created_by = baseline_data.get("created_by")
        user_id = baseline_data.get("user_id")

        # Allow user_id to be None or empty string
        if not created_by:
            return

        # Build text string: only name if user_id missing
        if user_id:
            text_str = f"Created by: {created_by} ({user_id})"
        else:
            text_str = f"Created by: {created_by}"
        
        # Determine chainage (first point of the baseline if not provided)
        if chainage_m is None:
            for poly in baseline_data.get("polylines", []):
                points = poly.get("points", [])
                if points:
                    chainage_m = points[0]["chainage_m"]
                    break
            if chainage_m is None:
                return

        pos = self.get_point_at_chainage(baseline_data, chainage_m)
        direction = self.get_direction_at_chainage(baseline_data, chainage_m)

        # Normalize direction for left offset
        norm = (direction[0]**2 + direction[1]**2)**0.5
        if norm > 0:
            dir_unit = [direction[0]/norm, direction[1]/norm, 0]
        else:
            dir_unit = [1, 0, 0]
        
        # Left vector = rotate 90° CCW
        left = [-dir_unit[1], dir_unit[0], 0]
        norm_left = (left[0]**2 + left[1]**2)**0.5
        if norm_left > 0:
            left = [left[0]/norm_left, left[1]/norm_left, 0]
        
        final_pos = [
            pos[0] + left[0] * left_offset,
            pos[1] + left[1] * left_offset,
            pos[2] + up_offset
        ]

        # Create polygonal text geometry
        text_source = vtk.vtkVectorText()
        text_source.SetText(text_str)

        mapper = vtk.vtkPolyDataMapper()
        mapper.SetInputConnection(text_source.GetOutputPort())

        actor = vtk.vtkActor()
        actor.SetMapper(mapper)
        actor.SetScale(scale, scale, scale)
        actor.SetPosition(final_pos[0], final_pos[1], final_pos[2])

        # Make text black and self‑illuminated
        actor.GetProperty().SetColor(0, 0, 0)
        actor.GetProperty().SetAmbient(1.0)
        actor.GetProperty().SetDiffuse(0.0)

        # Rotate to align with road direction (parallel)
        angle_deg = math.degrees(math.atan2(direction[1], direction[0]))
        actor.RotateZ(angle_deg)

        self.renderer.AddActor(actor)
        self.baseline_text_actors.append(actor)

    # ===== Aniket added on 05-05-2026 : For adding chainage markers along the baseline (poles + sticker boards with text) =====
    def add_chainage_markers_along_baseline(self, baseline_data, left_offset=5.0):
        """
        Iterates over the surface baseline, calculates the left-side offset, 
        and adds a straight pole with a white sticker board and chainage text.
        """
        import vtk
        import math
        
        if not baseline_data or "polylines" not in baseline_data:
            return

        added_markers_count = 0

        for poly in baseline_data.get("polylines", []):
            points = poly.get("points", [])
            if not points:
                continue

            for point in points:
                chainage_m = point.get("chainage_m")
                pos = point.get("world_coordinates")
                
                if chainage_m is None or pos is None:
                    continue

                # Get the forward direction of the baseline at this specific chainage
                direction = self.get_direction_at_chainage(baseline_data, chainage_m)

                # Normalize forward direction
                norm = (direction[0]**2 + direction[1]**2)**0.5
                if norm > 0:
                    dir_unit = [direction[0]/norm, direction[1]/norm, 0]
                else:
                    dir_unit = [1, 0, 0]

                # Calculate left vector (Rotate 90 degrees CCW)
                left_vec = [-dir_unit[1], dir_unit[0], 0]
                norm_left = (left_vec[0]**2 + left_vec[1]**2)**0.5
                if norm_left > 0:
                    left_vec = [left_vec[0]/norm_left, left_vec[1]/norm_left, 0]

                # --- Calculate World Position for the Pole Base ---
                # Place pole exactly at the 'left_offset' from center, on the ground (Z-axis)
                pole_base_pos = [
                    pos[0] + left_vec[0] * left_offset,
                    pos[1] + left_vec[1] * left_offset,
                    pos[2]
                ]

                # ==========================================
                # 1. Create the Straight Pole (1cm dia, 1m ht)
                # ==========================================
                pole_radius = 0.005  # 1 cm diameter = 0.005 m radius
                pole_height = 1.0     # 1 meter height
                
                pole_source = vtk.vtkCylinderSource()
                pole_source.SetRadius(pole_radius)
                pole_source.SetHeight(pole_height)
                pole_source.SetResolution(16)

                pole_mapper = vtk.vtkPolyDataMapper()
                pole_mapper.SetInputConnection(pole_source.GetOutputPort())

                pole_actor = vtk.vtkActor()
                pole_actor.SetMapper(pole_mapper)
                # VTK Cylinder defaults along Y axis, rotate it to stand up along Z axis
                pole_actor.RotateX(90)
                # Place the center of the cylinder. Since the height is 1m, moving it up by 0.5m anchors the base perfectly.
                pole_actor.SetPosition(pole_base_pos[0], pole_base_pos[1], pole_base_pos[2] + (pole_height / 2.0))
                # Set pole color (e.g., silver/grey)
                pole_actor.GetProperty().SetColor(0.7, 0.7, 0.7)
                self.renderer.AddActor(pole_actor)

                # ==========================================
                # 2. Create the Background Sticker Board
                # ==========================================
                board_width = 1.4
                board_height = 0.4
                
                # To make board face the road center:
                # Let's align text so it reads along road direction, up is Z. Then normal faces the road center (-left_vec).
                # Actually, facing the road center is right_vec = [dir_unit[1], -dir_unit[0], 0].
                angle_deg = math.degrees(math.atan2(dir_unit[1], dir_unit[0]))
                
                board_source = vtk.vtkCubeSource()
                board_source.SetXLength(board_width)
                board_source.SetYLength(0.01) # 1cm thick
                board_source.SetZLength(board_height)
                
                board_mapper = vtk.vtkPolyDataMapper()
                board_mapper.SetInputConnection(board_source.GetOutputPort())

                board_actor = vtk.vtkActor()
                board_actor.SetMapper(board_mapper)
                
                # Rotate around Z so X axis aligns with dir_unit (road path). Y axis aligns with left_vec.
                # The board is centered at origin.
                board_actor.SetOrientation(0, 0, angle_deg)
                
                # Put the board at top of the pole
                board_center_z = pole_base_pos[2] + pole_height + (board_height / 2.0)
                board_actor.SetPosition(pole_base_pos[0], pole_base_pos[1], board_center_z)
                # White background color
                board_actor.GetProperty().SetColor(1.0, 1.0, 1.0)
                self.renderer.AddActor(board_actor)

                # ==========================================
                # 3. Add Chainage Text onto Sticker Board (Both Sides)
                # ==========================================
                point_ch_str = point.get("chainage_str")
                if point_ch_str:
                    if "+" in point_ch_str:
                        parts = point_ch_str.split("+")
                        km_str = parts[0].strip()
                        m_str = parts[1].split(".")[0].strip()
                        chainage_str = f"{km_str}+{int(m_str):03d}"
                    else:
                        chainage_str = point_ch_str
                else:
                    # Fallback if not found in JSON
                    km = int(chainage_m // 1000)
                    m = int(chainage_m % 1000)
                    chainage_str = f"{km}+{m:03d}"
                
                # --- Front text ---
                text_source_front = vtk.vtkVectorText()
                text_source_front.SetText(chainage_str)
                text_source_front.Update() # Get bounds before mapping
                
                bnd = text_source_front.GetOutput().GetBounds() # [xmin, xmax, ymin, ymax, zmin, zmax]
                cx = (bnd[0] + bnd[1]) / 2.0
                cy = (bnd[2] + bnd[3]) / 2.0
                cz = (bnd[4] + bnd[5]) / 2.0

                text_mapper_front = vtk.vtkPolyDataMapper()
                text_mapper_front.SetInputConnection(text_source_front.GetOutputPort())

                text_actor_front = vtk.vtkActor()
                text_actor_front.SetMapper(text_mapper_front)
                # Dark Blue / Black text color
                text_actor_front.GetProperty().SetColor(0, 0.1, 0.5) 
                
                # Setup scaling to fit inside the 1.4 x 0.4m board
                text_scale = 0.18 
                
                # Calculate correct position outward from the board
                right_vec = [dir_unit[1], -dir_unit[0], 0]
                text_pos_front = [
                    pole_base_pos[0] + right_vec[0] * 0.015,
                    pole_base_pos[1] + right_vec[1] * 0.015,
                    board_center_z
                ]
                
                # Use vtkTransform to explicitly guarantee the text writes horizontally
                text_transform_front = vtk.vtkTransform()
                text_transform_front.PostMultiply()
                text_transform_front.Translate(-cx, -cy, -cz) 
                text_transform_front.Scale(text_scale, text_scale, text_scale)
                text_transform_front.RotateX(90) 
                text_transform_front.RotateZ(angle_deg) 
                text_transform_front.Translate(text_pos_front[0], text_pos_front[1], text_pos_front[2])
                
                text_actor_front.SetUserTransform(text_transform_front)
                self.renderer.AddActor(text_actor_front)

                # --- Back text ---
                text_mapper_back = vtk.vtkPolyDataMapper()
                text_mapper_back.SetInputConnection(text_source_front.GetOutputPort())

                text_actor_back = vtk.vtkActor()
                text_actor_back.SetMapper(text_mapper_back)
                text_actor_back.GetProperty().SetColor(0, 0.1, 0.5) 
                
                text_pos_back = [
                    pole_base_pos[0] - right_vec[0] * 0.015,
                    pole_base_pos[1] - right_vec[1] * 0.015,
                    board_center_z
                ]
                
                text_transform_back = vtk.vtkTransform()
                text_transform_back.PostMultiply()
                text_transform_back.Translate(-cx, -cy, -cz) 
                text_transform_back.Scale(text_scale, text_scale, text_scale)
                text_transform_back.RotateX(90)
                text_transform_back.RotateZ(angle_deg + 180) # Flip horizontally for reading from backside
                text_transform_back.Translate(text_pos_back[0], text_pos_back[1], text_pos_back[2])
                
                text_actor_back.SetUserTransform(text_transform_back)
                self.renderer.AddActor(text_actor_back)

                # Keep track for removal later if you refresh layers
                if not hasattr(self, 'chainage_marker_actors'):
                    self.chainage_marker_actors = []
                self.chainage_marker_actors.extend([pole_actor, board_actor, text_actor_front, text_actor_back])
                
                added_markers_count += 1

        print(f"Added {added_markers_count} Chainage Markers to the Road Surface Baseline")
        if hasattr(self, 'vtk_widget') and self.vtk_widget:
            self.vtk_widget.GetRenderWindow().Render()


    def add_text_marker_at_position(self, position, direction, text_str, scale=1.5, left_offset=3.0, up_offset=5.0):
        """Add a highly visible 3D text marker at a given world position."""
        import math
        import vtk
        import numpy as np

        # Compute left offset
        dir_vec = np.array(direction[:2] + [0])
        norm = np.linalg.norm(dir_vec)
        if norm > 0:
            dir_unit = dir_vec / norm
        else:
            dir_unit = np.array([1, 0, 0])
        left = np.array([-dir_unit[1], dir_unit[0], 0])
        left_norm = np.linalg.norm(left)
        if left_norm > 0:
            left = left / left_norm

        final_pos = [
            position[0] + left[0] * left_offset,
            position[1] + left[1] * left_offset,
            position[2] + up_offset
        ]

        # Create vector text
        text_source = vtk.vtkVectorText()
        text_source.SetText(text_str)

        mapper = vtk.vtkPolyDataMapper()
        mapper.SetInputConnection(text_source.GetOutputPort())

        actor = vtk.vtkActor()
        actor.SetMapper(mapper)
        actor.SetScale(scale, scale, scale)
        actor.SetPosition(final_pos[0], final_pos[1], final_pos[2])

        # Bright red for debugging
        actor.GetProperty().SetColor(0, 0, 0)
        actor.GetProperty().SetAmbient(1.0)
        actor.GetProperty().SetDiffuse(0.0)

        # Rotate to align with direction
        angle_deg = math.degrees(math.atan2(direction[1], direction[0])) + 180
        actor.RotateZ(angle_deg)

        self.renderer.AddActor(actor)
        self.baseline_text_actors.append(actor)
        self.vtk_widget.GetRenderWindow().Render()

    def get_point_at_chainage(self, baseline_data, chainage_m):
        """Return world coordinates (x, y, z) at the given chainage."""
        for poly in baseline_data.get("polylines", []):
            points = poly.get("points", [])
            if len(points) < 2:
                continue
            for i in range(len(points) - 1):
                pt1, pt2 = points[i], points[i+1]
                if pt1["chainage_m"] <= chainage_m <= pt2["chainage_m"]:
                    t = (chainage_m - pt1["chainage_m"]) / (pt2["chainage_m"] - pt1["chainage_m"])
                    w1, w2 = pt1["world_coordinates"], pt2["world_coordinates"]
                    x = w1[0] + t * (w2[0] - w1[0])
                    y = w1[1] + t * (w2[1] - w1[1])
                    z = w1[2] + t * (w2[2] - w1[2])
                    return [x, y, z]
        # Fallback: zero line
        start = np.array(self.zero_start_point)
        end = np.array(self.zero_end_point)
        t = chainage_m / self.total_distance if self.total_distance > 0 else 0
        pos = start + t * (end - start)
        return [pos[0], pos[1], pos[2]]

    def get_direction_at_chainage(self, baseline_data, chainage_m):
        """Return unit tangent direction (x, y) at the given chainage."""
        for poly in baseline_data.get("polylines", []):
            points = poly.get("points", [])
            if len(points) < 2:
                continue
            for i in range(len(points) - 1):
                pt1, pt2 = points[i], points[i+1]
                if pt1["chainage_m"] <= chainage_m <= pt2["chainage_m"]:
                    w1, w2 = pt1["world_coordinates"], pt2["world_coordinates"]
                    vec = [w2[0]-w1[0], w2[1]-w1[1], 0]
                    norm = (vec[0]**2 + vec[1]**2)**0.5
                    if norm > 0:
                        return [vec[0]/norm, vec[1]/norm, 0]
                    return [1, 0, 0]
        # Fallback: zero line direction
        start = np.array(self.zero_start_point)
        end = np.array(self.zero_end_point)
        dir_vec = end - start
        dir_vec = dir_vec / np.linalg.norm(dir_vec)
        return [dir_vec[0], dir_vec[1], 0]

    def clear_baseline_text_actors(self):
        for actor in self.baseline_text_actors:
            self.renderer.RemoveActor(actor)
        self.baseline_text_actors.clear()

    # ======= Aniket Added on 08-05-2026: Animated stage label transition =======
    def _show_stage_label_animated(self, new_text: str):
        """Swap the sim_stage_label text with a fade-out → text-change → fade-in animation.

        When switching between stages:
          1. Fade the label OUT  (opacity 1 → 0, slide up slightly)
          2. Change the text     (invisible so the swap is seamless)
          3. Fade the label IN   (opacity 0 → 1, slide down to original position)

        If the label is not yet visible, it is made visible and animated straight in.
        """
        if not hasattr(self, 'sim_stage_label'):
            return

        label = self.sim_stage_label

        # Ensure an opacity effect is attached
        effect = label.graphicsEffect()
        if not isinstance(effect, QGraphicsOpacityEffect):
            effect = QGraphicsOpacityEffect(label)
            label.setGraphicsEffect(effect)

        # Stop any running animation to avoid conflicts
        if hasattr(self, '_stage_label_anim') and self._stage_label_anim is not None:
            self._stage_label_anim.stop()

        FADE_MS   = 180   # ms per fade phase
        SLIDE_PX  = 12    # pixels of vertical slide

        label.setVisible(True)
        self.update_sim_label_position()
        base_pos = label.pos()

        # ── Phase 1 — Fade OUT + slide UP ────────────────────────────────
        fade_out  = QPropertyAnimation(effect, b"opacity", label)
        fade_out.setDuration(FADE_MS)
        fade_out.setStartValue(effect.opacity())
        fade_out.setEndValue(0.0)
        fade_out.setEasingCurve(QEasingCurve.OutCubic)

        slide_up  = QPropertyAnimation(label, b"pos", label)
        slide_up.setDuration(FADE_MS)
        slide_up.setStartValue(base_pos)
        slide_up.setEndValue(QPoint(base_pos.x(), base_pos.y() - SLIDE_PX))
        slide_up.setEasingCurve(QEasingCurve.OutCubic)

        phase1 = QParallelAnimationGroup(label)
        phase1.addAnimation(fade_out)
        phase1.addAnimation(slide_up)

        # ── Phase 2 — Fade IN + slide back DOWN ──────────────────────────
        fade_in   = QPropertyAnimation(effect, b"opacity", label)
        fade_in.setDuration(FADE_MS)
        fade_in.setStartValue(0.0)
        fade_in.setEndValue(1.0)
        fade_in.setEasingCurve(QEasingCurve.InCubic)

        slide_dn  = QPropertyAnimation(label, b"pos", label)
        slide_dn.setDuration(FADE_MS)
        slide_dn.setStartValue(QPoint(base_pos.x(), base_pos.y() - SLIDE_PX))
        slide_dn.setEndValue(base_pos)
        slide_dn.setEasingCurve(QEasingCurve.InCubic)

        phase2 = QParallelAnimationGroup(label)
        phase2.addAnimation(fade_in)
        phase2.addAnimation(slide_dn)

        # ── Wire phases sequentially ──────────────────────────────────────
        seq = QSequentialAnimationGroup(label)
        seq.addAnimation(phase1)
        seq.addAnimation(phase2)

        # Change the text at the invisible mid-point (between phase1 and phase2)
        def _swap_text():
            label.setText(new_text)
            self.update_sim_label_position()       # re-centre after text may have changed width
            # Recalculate base_pos after re-centering so slide-back lands correctly
            new_base = label.pos()
            slide_dn.setStartValue(QPoint(new_base.x(), new_base.y() - SLIDE_PX))
            slide_dn.setEndValue(new_base)
            slide_up.setEndValue(QPoint(new_base.x(), new_base.y() - SLIDE_PX))

        phase1.finished.connect(_swap_text)

        self._stage_label_anim = seq
        seq.start()

    # ---- Aniket added on 03-05-2026: Simulation Stage Handling ---- (shows data from design/material layers, but only for the active stage, and with specific styling to differentiate from master design)
    # ============================================================================================================================================
    def handle_simulation_stage_change(self, state, stage_key):
        """Handler for simulation stage checkbox change."""
        from PyQt5.QtCore import Qt
        import os
        import json
        import traceback

        if state != Qt.Checked:
            # Check if any other stage is checked. If not, clear the temporary visuals.
            any_checked = any(cb.isChecked() for cb in self.stage_checkboxes)
            if not any_checked:
                self.clear_all_simulation_visuals()
                # Re-dotted the master design lines (since clearing might have removed them or we want them dotted in sim mode)
                self.show_simulation_panel() 
            return

        # 1. Mutual Exclusivity: Uncheck all other stage checkboxes
        for cb in self.stage_checkboxes:
            if getattr(cb, 'stage_key', None) != stage_key:
                cb.blockSignals(True)
                cb.setChecked(False)
                cb.blockSignals(False)

        # 2. Clear already loaded graph data and 3D actors
        self.clear_all_simulation_visuals()

        # 3. Load stage configuration
        if not hasattr(self, 'current_worksheet_name') or not self.current_worksheet_name:
            return
            
        worksheet_dir = os.path.join(self.WORKSHEETS_BASE_DIR, self.current_worksheet_name)
        config_path = os.path.join(worksheet_dir, "simulation_config.txt")
        
        if not os.path.exists(config_path):
            return

        try:
            with open(config_path, 'r', encoding='utf-8') as f:
                config = json.load(f)
            
            stage_data = config.get(str(stage_key))
            if not stage_data:
                return

            # ======= Aniket Added on 08-05-2026: animated stage label swap =======
            # Build the new label text and animate the transition
            s_name = stage_data.get("stage_name", "")
            txt = f"Stage {stage_key}"
            if s_name:
                txt = f"Stage {stage_key} - {s_name}"
            # _show_stage_label_animated handles: fade-out old text → swap → fade-in new text
            self._show_stage_label_animated(txt)
                
            design_path = stage_data.get("design_layer_path")
            material_path = stage_data.get("material_layer_path")

            # Auto-resolve design_path from material config if missing
            if (not design_path or not os.path.exists(design_path)) and material_path and os.path.exists(material_path):
                layer_config_file = os.path.join(material_path, "Construction_Layer_config.txt")
                if os.path.exists(layer_config_file):
                    try:
                        with open(layer_config_file, 'r', encoding='utf-8') as f:
                            layer_config = json.load(f)
                        design_name = layer_config.get("design_layer_name")
                        if design_name:
                            design_path = os.path.join(worksheet_dir, "designs", design_name)
                    except Exception as e:
                        print(f"Error reading material config: {e}")

            # 4. Load and Visualize Design Layer (Stage Design)
            if design_path and os.path.exists(design_path):
                # Load all baselines from this specific stage design folder
                loaded_baselines = self.load_all_baselines_from_layer(design_path)
                
                # # STRICTOR: Respect the "show_road_surface" toggle for this stage
                # # Handle potential string values from JSON
                # show_road_surface = self._as_bool_flag(stage_data.get("show_road_surface", False))
                
                # if not show_road_surface:
                #     # Remove from current visualization batch
                #     for k in ["road_surface", "road_surface_baseline", "road surface"]:
                #         if k in loaded_baselines:
                #             del loaded_baselines[k]
                    
                #     # Also ensure global line_types doesn't have stale polylines for this stage
                #     if 'road_surface' in self.line_types:
                #         self.line_types['road_surface']['polylines'] = []
                
                # Visualize on 2D Graph (solid for the active stage)
                for ltype in loaded_baselines.keys():
                    self.redraw_baseline_on_graph(ltype, style="solid")
                
                # Visualize on 3D VTK
                self.generate_3d_planes_from_baselines(loaded_baselines)
                
                # Load stage assets saved inside design_construction_config.json
                self.load_design_layer_assets_from_json(design_path)
                
                # Load 3D Point Cloud Actors
                self.load_json_files_to_3d_pointcloud(design_path)

            # 5. Load and Visualize Material Layer (Stage Material)
            if material_path and os.path.exists(material_path):
                # We reuse the construction layer loading logic
                layer_config_file = os.path.join(material_path, "Construction_Layer_config.txt")
                if os.path.exists(layer_config_file):
                    with open(layer_config_file, 'r', encoding='utf-8') as f:
                        layer_config = json.load(f)
                    
                    referenced_baselines = layer_config.get("base_lines_reference", [])
                    if isinstance(referenced_baselines, str):
                        referenced_baselines = [referenced_baselines]
                    
                    for baseline_filename in referenced_baselines:
                        baseline_file_path = os.path.join(material_path, baseline_filename)
                        if not os.path.exists(baseline_file_path) and design_path:
                            baseline_file_path = os.path.join(design_path, baseline_filename)
                        
                        if os.path.exists(baseline_file_path):
                            with open(baseline_file_path, 'r', encoding='utf-8') as f:
                                b_data = json.load(f)
                            ltype = b_data.get("baseline_key", "construction")
                            
                            # # STRICTOR: Also filter road surface from material layer references if toggle is off
                            # show_road_surface = self._as_bool_flag(stage_data.get("show_road_surface", False))
                            # if not show_road_surface and ltype in ["road_surface", "road_surface_baseline"]:
                            #     continue

                            color = b_data.get("color", "gray")
                            polylines_2d = []
                            for poly in b_data.get("polylines", []):
                                poly_2d = [(pt["chainage_m"], pt["relative_elevation_m"]) for pt in poly.get("points", [])]
                                if len(poly_2d) >= 2:
                                    polylines_2d.append(poly_2d)
                            
                            if ltype not in self.line_types:
                                self.line_types[ltype] = {'color': color, 'polylines': [], 'artists': []}
                            
                            # Draw on Graph
                            all_x, all_y = [], []
                            for poly in polylines_2d:
                                xs, ys = zip(*poly)
                                all_x.extend(xs)
                                all_y.extend(ys)
                            if all_x:
                                artist, = self.ax.plot(all_x, all_y, color=color, linestyle=':', linewidth=3, alpha=0.8, zorder=10)
                                self.line_types[ltype]['artists'].append(artist)
                                self.line_types[ltype]['polylines'] = polylines_2d

                # Load material visualization (actors/fills)
                self.message_text.append(f"Stage {stage_key} Material Loaded.")
                self.render_simulation_materials(material_path)

            # 6. Apply stage-specific excavation logic if checked
            if stage_data.get("excavation", False):
                # We need road_surface and construction baselines for excavation
                road_data = self.line_types.get("surface") or self.line_types.get("road_surface") or self.line_types.get("road_surface_baseline")
                const_data = self.line_types.get("construction") or self.line_types.get("construction_baseline")
                
                if road_data and const_data:
                    self.message_text.append(f"⛏ Applying Excavation for Stage {stage_key}...")
                    self.apply_excavation_simulation(road_data, const_data)
                else:
                    self.message_text.append(f"⚠️ Cannot apply excavation for Stage {stage_key}: road surface or construction baseline missing.")

            # 7. Update Report Section
            self.update_report_for_stage(stage_key, stage_data)

            # Redraw canvas and render VTK
            self.canvas.draw_idle()
            if hasattr(self, 'vtk_widget'):
                self.vtk_widget.GetRenderWindow().Render()

        except Exception as e:
            print(f"Error handling stage change: {e}")
            traceback.print_exc()

