            username = getattr(self, "username", "User")

            if not user_id:
                QMessageBox.warning(self, "Error", "User not logged in.")
                return

            # Define user worksheet directory
            base_path = os.path.join(r"C:\3D_Tool\user", str(user_id), "road")
            os.makedirs(base_path, exist_ok=True)

            # Get current worksheet data
            current_worksheet_data = getattr(self, "current_worksheet_data", {})
