    def update_baseline_actor(self, baseline_key, base_data):

        renderer = self.vtk_widget.GetRenderWindow().GetRenderers().GetFirstRenderer()

        actor_attr = f"{baseline_key}_actor"

        # remove old actor
        if hasattr(self, actor_attr):
            old_actor = getattr(self, actor_attr)
            renderer.RemoveActor(old_actor)

        points = vtk.vtkPoints()
        lines = vtk.vtkCellArray()

        point_id = 0

        for poly in base_data.get("polylines", []):
            pts = poly.get("points", [])

            prev_id = None
            prev_chainage_val = None

            for pt in pts:
                if pt.get("hidden") == True:
                    prev_id = None
                    prev_chainage_val = None                                #  THIS LINE ADD
                    continue
                coords = pt.get("world_coordinates")
                if not coords:
                    prev_id = None
                    prev_chainage_val = None
                    continue

                try:
                    km, ch = pt.get("chainage_str", "0+0").split("+")
                    curr_val = float(km) * 1000 + float(ch)
                except:
                    curr_val = None

                points.InsertNextPoint(coords)


                if prev_id is not None and prev_chainage_val is not None and curr_val is not None:

                    #  ONLY CONNECT IF EXACT CONTINUOUS (STEP = 20)
                    # if abs(curr_val - prev_chainage_val - 20) < 0.01:
                    if abs(curr_val - prev_chainage_val) <= 25:

                        line = vtk.vtkLine()
                        line.GetPointIds().SetId(0, prev_id)
                        line.GetPointIds().SetId(1, point_id)
                        lines.InsertNextCell(line)

                    else:
                        # GAP → BREAK CONNECTION
                        prev_id = None
                        prev_chainage_val = None                        #  ADD THIS

                prev_id = point_id
                prev_chainage_val = curr_val
                point_id += 1

        polydata = vtk.vtkPolyData()
        polydata.SetPoints(points)
        polydata.SetLines(lines)

        mapper = vtk.vtkPolyDataMapper()
        mapper.SetInputData(polydata)

        actor = vtk.vtkActor()
        actor.SetMapper(mapper)
        actor.GetProperty().SetLineWidth(3)

        renderer.AddActor(actor)

        setattr(self, actor_attr, actor)

        self.vtk_widget.GetRenderWindow().Render()


